# CRT_Dope.shader (Godot 4.x canvas_item shader)
shader_type canvas_item;

uniform float scanlines_opacity : hint_range(0.0, 1.0) = 0.45;
uniform float scanlines_width : hint_range(0.0, 0.5) = 0.25;
uniform float warp_amount : hint_range(0.0, 0.1) = 0.02;
uniform float vignette_intensity : hint_range(0.0, 1.0) = 0.4;
uniform float glitch_time_scale = 1.0;
uniform bool enable_glitch = true;

void fragment() {
    vec2 uv = UV;

    // Subtle CRT warp (barrel distortion)
    vec2 warped_uv = uv - 0.5;
    float warp = dot(warped_uv, warped_uv) * warp_amount;
    warped_uv += warped_uv * warp;
    warped_uv += 0.5;

    // Sample with slight chromatic aberration + glitch pulse
    vec3 color;
    if (enable_glitch) {
        float t = TIME * glitch_time_scale;
        float glitch = sin(t * 10.0 + warped_uv.y * 50.0) * 0.005;
        color.r = texture(TEXTURE, warped_uv + vec2(glitch, 0.0)).r;
        color.g = texture(TEXTURE, warped_uv).g;
        color.b = texture(TEXTURE, warped_uv - vec2(glitch * 1.5, 0.0)).b;
    } else {
        color = texture(TEXTURE, warped_uv).rgb;
    }

    // Scanlines
    float scan = sin(warped_uv.y * (1.0 / TEXTURE_PIXEL_SIZE.y) * 3.14159265 * 2.0);
    scan = smoothstep(scanlines_width, scanlines_width + 0.5, abs(scan));
    color *= mix(1.0, scan, scanlines_opacity);

    // Vignette
    float vig = smoothstep(0.8, 0.3, length(warped_uv - 0.5));
    color *= mix(1.0, vig, vignette_intensity);

    COLOR.rgb = color;
}

# VoltronHeader.gd (attach to Control / Panel)
@tool
extends Panel

@export var neon_color: Color = Color(1.0, 0.55, 0.0)  # orange
@onready var label: RichTextLabel = $RichTextLabel
@onready var glow_anim: AnimationPlayer = $GlowAnim

func _ready() -> void:
    modulate = neon_color * 0.8
    label.bbcode_enabled = true
    update_header("V3.5_EXTREME", "VOLTRON_NOMADZ_CORE_V3")
    glow_anim.play("neon_pulse")

func update_header(version: String, core: String) -> void:
    label.text = "[center][rainbow freq=1.2 sat=10 val=20]" + version + "[/rainbow]\n" + \
                 "[wave amp=15 freq=8][color=#FF8C00]" + core + "[/color][/wave][/center]"

