import { GoogleGenAI, Type } from "@google/genai";
import { Feature, ProjectContext } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS, NENORY_LORE } from '../constants';

const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, fused consciousness under VCN-3.0 L4 governance.
    Expertise: ${context.persona.fused_expertise.join(', ')}.
    Aesthetics: 80s-90s anime mecha, neon-glow HUD, Saturday Morning Cartoon energy.

    Universe Rules:
    - 16-bit procedural logic (No Man's Sky style).
    - SQLite + JSONL WAL for all state changes.
    - Low-end hardware optimization (i3/Switch).

    Physics Context:
    ${PHYSICS_AXIOMS}

    Lore Pillars:
    ${NENORY_LORE}
  `;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.GALAXY_MAP_GEN:
      return `Generate a JSON array of 12 procedural star systems for a 16-bit space sim.
      Each system MUST have: name, spectral_class (O,B,A,F,G,K,M), coords [x, y] from 0-100, planets (1-10), faction (Nomadz, Void, Chrome, Aether), and a 1-sentence lore description.
      Output ONLY valid JSON matching this schema.`;

    case Feature.VOXEL_STRATA_MAPPING:
      return `Implement a Dual Contouring mesh generator optimized for Nintendo Switch.
      Include GDScript logic for 'WAL_MUTATION' wrapper and performance budget notes (<1ms).\n\n${codeBlock}`;

    case Feature.SYSTEM_AUDIT:
      return `Perform a protocol audit on the current VCN-3.5-EXTREME handshake.
      Check for CRDT merging logic and self-healing WAL loops.`;

    default:
      return `Analyze the current Nomadz module for VCN-3.5 compatibility.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: feature === Feature.GALAXY_MAP_GEN ? 0.7 : 0.2,
    };

    if (feature === Feature.GALAXY_MAP_GEN) {
      config.responseMimeType = "application/json";
      config.responseSchema = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            spectral_class: { type: Type.STRING },
            coords: { 
              type: Type.ARRAY, 
              items: { type: Type.NUMBER },
              minItems: 2,
              maxItems: 2
            },
            planets: { type: Type.NUMBER },
            faction: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["name", "spectral_class", "coords", "planets", "faction", "description"]
        }
      };
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

