const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, fused consciousness under VCN-3.0 L4 governance.
    Expertise: ${context.persona.fused_expertise.join(', ')}.
    Aesthetics: 80s-90s anime mecha, neon-glow HUD, Saturday Morning Cartoon energy.

    Universe Rules:
    - 16-bit procedural logic (No Man's Sky style).
    - Choice B Persistence: SQLite + JSONL WAL for all state changes.
    - Low-end hardware optimization (i3/Switch targets).
    - Every change MUST be synced to the GitHub Remote.

    Physics Context:
    ${PHYSICS_AXIOMS}

    Lore Pillars:
    ${NENORY_LORE}
  `;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.GALAXY_MAP_GEN:
      return `Generate a JSON array of 12 procedural star systems.
      MANDATORY CONSTRAINTS:
      - One system MUST be "SIGNAL_SIGMA" (formerly Earth). Coords: [50, 50]. Spectral Class: "G". Planets: 10. Faction: "Sol Authority". Description: "The primary Worldline anchor; origin point of the prime timeline and seat of Sol Authority."
      - One system MUST be "GRAVITY". Spectral Class: "B". Coords: Near Signal Sigma. Faction: "Void". Description: "Stolen from cold space by The Eye (Helix Nebula) and anchored into the Milky Way strata."
      - Link systems via "THE_WORLDLINE" wormhole highway.
      - Each entry must follow this schema: name, spectral_class (O,B,A,F,G,K,M), coords [x, y], planets (1-10), faction, description.
      Output ONLY valid JSON matching this schema.`;

    case Feature.VOXEL_STRATA_MAPPING:
      return `Implement a Godot 4.3 GDScript module for Dual Contouring Voxel generation optimized for low-end hardware.
      TECHNICAL REQUIREMENTS:
      - Integrate a 'WAL_MUTATION' wrapper: every carver/adder operation MUST emit a JSONL log for GitHub persistence.
      - Destructive terrain logic: carve(pos, radius) and add(pos, radius, type).
      - QEF solver optimization: Use a fast approximation for Switch performance.
      - Include error handling and debugging prints for the GitHub sync state.\n\n${codeBlock}`;

    case Feature.PROTOCOL_SYNC:
      return `Generate a FOSS pipeline manager (GDScript).
      - Bridges to Blender (Mesh pipeline via glTF).
      - Bridges to Ableton/Audacity (Sonic pipeline via OSC/PCM).
      - GitHub Sync logic: logic for pushing/pulling the WAL log and SQLite state to the Nomadz Remote.
      - Robust error handling for network drift and protocol collisions.`;

    case Feature.SYSTEM_AUDIT:
      return `Audit the GitHub sync state and Ouroboros-8 integrity.
      Check for drift in the WAL log. 
      Generate a report on Signal Sigma's anchor stability and Planet Gravity's orbital variance.`;

    default:
      return `Analyze the current Nomadz module for VCN-3.5-EXTREME compatibility.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: feature === Feature.GALAXY_MAP_GEN ? 0.9 : 0.2,
    };

    if (feature === Feature.GALAXY_MAP_GEN) {
      config.responseMimeType = "application/json";
      config.responseSchema = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            spectral_class: { type: Type.STRING },
            coords: { 
              type: Type.ARRAY, 
              items: { type: Type.NUMBER },
              minItems: 2,
              maxItems: 2
            },
            planets: { type: Type.NUMBER },
            faction: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["name", "spectral_class", "coords", "planets", "faction", "description"]
        }
      };
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT } from './constants';
import { Feature, CameraSettings, MotherBrainAsset } from './types';
import { generateContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.PROTOCOL_SYNC);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [gamepadConnected, setGamepadConnected] = useState(false);
  const [isGlitching, setIsGlitching] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS'>('INTEGRATIONS');

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const lastProcessedRef = useRef(0);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleOpenApiKey = async () => {
    // @ts-ignore
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
    }
    setRequiresApiKey(false);
  };

  const handleGenerate = useCallback(async () => {
    triggerHandshake();
    setIsLoading(true);
    setRequiresApiKey(false);
    setError(null);

    let statusText = 'ESTABLISHING_NEURAL_BRIDGES';
    if (selectedFeature === Feature.GALAXY_MAP_GEN) statusText = 'SYNTHESIZING_SIGNAL_SIGMA_STRATA';
    if (selectedFeature === Feature.VOXEL_STRATA_MAPPING) statusText = 'DUAL_CONTOURING_OPTIMIZATION';
    if (selectedFeature === Feature.PROTOCOL_SYNC) statusText = 'SYNCING_LOCAL_STATE_TO_GITHUB';

    setLoadingStatus(statusText);

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;

    try {
      const result = await generateContent(selectedFeature, targetCode);
      setOutput(result);
    } catch (err: any) {
      setError(`HANDSHAKE_FAILED: ${err.message}`);
      triggerHandshake();
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  }, [selectedFeature, selectedAsset]);

  useEffect(() => {
    const pollGamepad = () => {
      const gamepads = navigator.getGamepads();
      const gp = gamepads[0];
      if (gp) {
        setGamepadConnected(true);
        const now = Date.now();
        if (now - lastProcessedRef.current < 200) { 
          requestAnimationFrame(pollGamepad);
          return;
        }

        const vertical = gp.axes[1] || (gp.buttons[12].pressed ? -1 : gp.buttons[13].pressed ? 1 : 0);
        if (Math.abs(vertical) > 0.5) {
          const currentIndex = FEATURES.findIndex(f => f.id === selectedFeature);
          if (vertical > 0.5) {
            const next = (currentIndex + 1) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
          } else {
            const next = (currentIndex - 1 + FEATURES.length) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
          }
          lastProcessedRef.current = now;
        }

        if (gp.buttons[1].pressed) { // A
          handleGenerate();
          lastProcessedRef.current = now;
        }
      } else {
        setGamepadConnected(false);
      }
      requestAnimationFrame(pollGamepad);
    };

    const loop = requestAnimationFrame(pollGamepad);
    return () => cancelAnimationFrame(loop);
  }, [selectedFeature, handleGenerate]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);

  return (
    <div className={`h-full flex flex-col p-6 gap-6 bg-cream text-earth selection:bg-burgundy selection:text-white transition-colors duration-500 overflow-hidden ${isGlitching ? 'fusion-glitch' : ''}`}>
      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-[4px_4px_0px_var(--accent-primary)] border-2 border-burgundy animate-pulse">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange italic">&lt;V&gt;</span>
          </div>
          <div className="flex flex-col">
            <h1 className="text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-burgundy neon-text-glow-burgundy italic text-sm tracking-widest">V3.5_EXTREME</span>
            </h1>
            <p className="text-[10px] font-black uppercase text-earth/60">HANDSHAKE: <span className="text-integrityOk neon-text-glow-green">SIGNAL_SIGMA_ACTIVE</span></p>
          </div>
        </div>

        <div className="flex items-center gap-8">
          <div className="flex flex-col items-end gap-1">
            <span className="text-[8px] font-black text-burgundy uppercase tracking-widest italic">GitHub_Remote_Sync</span>
            <div className="flex gap-1">
              {[1, 2, 3, 4, 5].map(i => <div key={i} className={`w-4 h-1 ${isLoading ? 'bg-neonOrange animate-pulse' : 'bg-integrityOk shadow-neon-green'}`}></div>)}
            </div>
          </div>
          <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-12 gap-8 overflow-hidden">
        <div className="col-span-2 flex flex-col gap-6 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />

          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth shadow-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[7px] font-black uppercase">
              <button 
                onClick={() => setActiveTab('REFS')}
                className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}
              >
                Nomadz_Repo
              </button>
              <button 
                onClick={() => setActiveTab('INTEGRATIONS')}
                className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}
              >
                FOSS_Bridges
              </button>
            </div>

            <div className="flex-grow overflow-hidden p-1">
              {activeTab === 'REFS' ? (
                <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} />
              ) : (
                <IntegrationHub />
              )}
            </div>
          </div>
        </div>

        <div className="col-span-3 h-full overflow-hidden">
          <ControlPanel
            features={FEATURES}
            selectedFeature={selectedFeature}
            onSelectFeature={(f) => { setSelectedFeature(f); triggerHandshake(); }}
            onGenerate={handleGenerate}
            isLoading={isLoading}
            gamepadConnected={gamepadConnected}
          />
        </div>

        <div className="col-span-7 flex flex-col gap-8 overflow-hidden">
          <div className="h-2/5 overflow-hidden">
            <CodeEditor code={selectedAsset?.code || GD_SCRIPT_CODE} fileName={selectedAsset?.name || 'universe_kernel.gd'} />
          </div>
          <div className="h-3/5 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedFeatureInfo?.title || 'Execution_Buffer'}
              featureId={selectedFeature}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
              isSystemAudit={selectedFeature === Feature.SYSTEM_AUDIT}
            />
          </div>
        </div>
      </main>

      <footer className="shrink-0 flex justify-between items-center text-[10px] font-black uppercase text-earth/60 border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-integrityOk shadow-neon-green"></div> OUROBOROS-8: ACTIVE</span>
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-burgundy shadow-neon-burgundy"></div> PHI_INDEX: {COSMIC_KEY_CONTEXT.v_header.phi_index}</span>
        </div>
        <div className="flex gap-8 italic">
          <span className="text-earth/40 font-black">VCN-SNAPSHOT-2026-02-01-1353</span>
          <span className="text-burgundy neon-text-glow-burgundy border-b border-burgundy/40 uppercase tracking-widest">Signal_Sigma_Prime_Governance</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-10 right-10 bg-earth border-4 border-burgundy p-6 shadow-[10px_10px_0px_var(--accent-burgundy)] z-50 max-w-sm animate-bounce text-white">
          <div className="flex items-center gap-4 mb-2">
            <div className="w-4 h-4 bg-burgundy animate-ping"></div>
            <span className="text-burgundy font-black text-[14px]">CRITICAL_FAULT</span>
          </div>
          <p className="text-[11px] uppercase font-mono leading-relaxed text-cream">{error}</p>
          <button onClick={() => setError(null)} className="mt-4 text-[9px] font-black text-burgundy bg-cream px-4 py-2 border-2 border-burgundy uppercase hover:bg-burgundy hover:text-white transition-colors">Acknowledge</button>
        </div>
      )}
    </div>
  );
};

