const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.GALAXY_MAP_GEN:
      return `Generate a JSON array of 12 procedural star systems.
      MANDATORY CONSTRAINTS:
      - One system MUST be "SIGNAL_SIGMA" (formerly Earth). Coords: [50, 50]. Spectral Class: "G". Planets: 10. Faction: "Sol Authority". Description: "The primary Worldline anchor; the origin point of the prime VCN timeline."
      - One system MUST be "GRAVITY". Spectral Class: "B". Coords: [55, 48] (Near Signal Sigma). Faction: "Void". Description: "Stolen from cold space by The Eye and placed into the Milky Way strata; a rogue planet with an anomalous mass core."
      - Link all systems via "THE_WORLDLINE" wormhole highway.
      - Every description must mention its position on the Worldline highway.
      - Return ONLY the JSON array matching the schema.`;

    case Feature.VOXEL_STRATA_MAPPING:
      return `Implement a Godot 4.3 GDScript module for Dual Contouring Voxel generation optimized for low-end hardware.
      TECHNICAL REQUIREMENTS:
      - Integrate a 'WAL_MUTATION' wrapper: every carver/adder operation MUST emit a JSONL log for GitHub persistence.
      - Destructive terrain logic: carve(pos, radius) and add(pos, radius, type).
      - QEF solver optimization: Use a fast approximation for Switch performance.
      - Include error handling and debugging prints for the GitHub sync state.\n\n${codeBlock}`;

    case Feature.PROTOCOL_SYNC:
      return `Generate a FOSS pipeline manager (GDScript).
      - Bridges to Blender (Mesh pipeline via glTF).
      - Bridges to Ableton/Audacity (Sonic pipeline via OSC/PCM).
      - Google Drive Integration: logic for indexing archive assets for narrative and audio cues.
      - GitHub Sync logic: logic for pushing/pulling the WAL log and SQLite state to the Nomadz Remote.
      - Robust error handling for network drift and protocol collisions.`;

    case Feature.SYSTEM_AUDIT:
      return `Audit the GitHub sync state and Ouroboros-8 integrity.
      Check for drift in the WAL log. 
      Generate a report on Signal Sigma's anchor stability and Planet Gravity's orbital variance.`;

    default:
      return `Analyze the current Nomadz module for VCN-3.5-EXTREME compatibility.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: feature === Feature.GALAXY_MAP_GEN ? 0.9 : 0.2,
      // Using googleSearch tool if the model supports it for Drive/Web grounding
      tools: [{ googleSearch: {} }]
    };

    if (feature === Feature.GALAXY_MAP_GEN) {
      config.responseMimeType = "application/json";
      config.responseSchema = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            spectral_class: { type: Type.STRING },
            coords: { 
              type: Type.ARRAY, 
              items: { type: Type.NUMBER },
              minItems: 2,
              maxItems: 2
            },
            planets: { type: Type.NUMBER },
            faction: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["name", "spectral_class", "coords", "planets", "faction", "description"]
        }
      };
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

import React, { useState } from 'react';
import { StarSystem } from '../types';

interface GalaxyMapProps {
  systems: StarSystem[];
  isLoading: boolean;
}

const GalaxyMap: React.FC<GalaxyMapProps> = ({ systems, isLoading }) => {
  const [selectedSystem, setSelectedSystem] = useState<StarSystem | null>(null);

  const getStarColor = (spectral: string) => {
    switch (spectral) {
      case 'O': return '#00ffff';
      case 'B': return '#88ffff';
      case 'A': return '#ffffff';
      case 'F': return '#ffff88';
      case 'G': return '#ffff00';
      case 'K': return '#ffaa00';
      case 'M': return '#ff4400';
      default: return '#ffffff';
    }
  };

  return (
    <div className="h-full flex flex-col gap-4 animate-in fade-in zoom-in-95 duration-700">
      <div className="flex justify-between items-center bg-burgundy/10 border-2 border-burgundy p-4 shadow-[0_0_15px_var(--accent-burgundy)] relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-px bg-burgundy/30 animate-[scan_2s_linear_infinite]"></div>
        <div>
          <h2 className="text-burgundy font-black uppercase text-[12px] tracking-widest italic neon-text-glow-burgundy">Worldline_Wormhole_Feed_v3.5</h2>
          <p className="text-earth/60 text-[8px] font-bold uppercase mt-1">Highway: ACTIVE | Anchor: SIGNAL_SIGMA [50, 50]</p>
        </div>
        <div className="text-integrityOk font-black text-[10px] animate-pulse">BRIDGE_OS_STABLE</div>
      </div>

      <div className="flex-grow grid grid-cols-12 gap-4">
        {/* The Grid Map */}
        <div className="col-span-8 bg-black border-2 border-earth relative overflow-hidden brutalist-grid opacity-90 group">
          <div className="absolute inset-0 bg-burgundy/5 pointer-events-none"></div>

          {/* Worldline visual lines connecting systems */}
          <svg className="absolute inset-0 w-full h-full pointer-events-none z-0 opacity-20">
            {systems.map((s, i) => {
              if (i === 0) return null;
              const prev = systems[i-1];
              return (
                <line 
                  key={i}
                  x1={`${prev.coords[0]}%`} 
                  y1={`${prev.coords[1]}%`} 
                  x2={`${s.coords[0]}%`} 
                  y2={`${s.coords[1]}%`} 
                  stroke="#FF8C00" 
                  strokeWidth="0.5" 
                  strokeDasharray="4 2"
                />
              );
            })}
          </svg>

          {systems.map((s, i) => {
            const isAnchor = s.name === "SIGNAL_SIGMA";
            const isGravity = s.name === "GRAVITY";
            return (
              <button
                key={i}
                onClick={() => setSelectedSystem(s)}
                className={`absolute -translate-x-1/2 -translate-y-1/2 transition-all duration-300 z-10 ${isAnchor ? 'w-10 h-10' : isGravity ? 'w-8 h-8 animate-pulse' : 'w-4 h-4 hover:scale-150'}`}
                style={{
                  left: `${s.coords[0]}%`,
                  top: `${s.coords[1]}%`,
                }}
              >
                <div 
                  className={`w-full h-full rounded-full ${isAnchor ? 'animate-spin shadow-[0_0_25px_var(--accent-primary)] border-2 border-neonOrange bg-gradient-to-tr from-neonOrange to-yellow-300' : isGravity ? 'shadow-[0_0_20px_#88ffff] border-2 border-cyan-400 bg-cyan-900' : 'shadow-[0_0_15px_currentColor]'}`}
