          <div className="absolute inset-0 flex justify-between opacity-10 pointer-events-none">
            {[...Array(10)].map((_, i) => <div key={i} className="h-full w-px bg-white"></div>)}
          </div>
        </div>

        {/* Info Panel */}
        <div className="col-span-4 flex flex-col gap-4">
          <div className="flex-grow bg-taupe/20 border-2 border-earth p-4 flex flex-col gap-4">
            {selectedSystem ? (
              <>
