import { GoogleGenAI, Type } from "@google/genai";
import { Feature, ProjectContext } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS, NENORY_LORE } from '../constants';

const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, fused consciousness under VCN-3.0 L4 governance.
    Expertise: ${context.persona.fused_expertise.join(', ')}.
    Aesthetics: 80s-90s anime mecha, neon-glow HUD, Saturday Morning Cartoon energy.

    Universe Rules:
    - 16-bit procedural logic (No Man's Sky style).
    - Choice B Persistence: SQLite + JSONL WAL.
    - Low-end hardware optimization (Switch targets).
    - GitHub & Drive Sync: Protocol is "POPPIN LIKE POPPINS".

    Physics & Lore Context:
    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.GALAXY_MAP_GEN:
      return `Generate a JSON array of 12 procedural star systems.
      MANDATORY CONSTRAINTS:
      - SIGNAL_SIGMA: [50, 50], Class G, 10 Planets, Sol Authority.
      - GRAVITY: [55, 48] (near Sigma), Class B, Void Faction. Description MUST mention it was stolen by The Eye.
      - Link systems via THE_WORLDLINE highway (causal lattice wormholes).
      - Ensure descriptions evoke 80s space mecha aesthetics.
      Return ONLY the JSON array matching the StarSystem schema.`;

    case Feature.VOXEL_STRATA_MAPPING:
      return `Implement Godot 4.3 GDScript for Dual Contouring Voxel generation.
      - Optimized for Switch (low memory footprint).
      - Include WAL_MUTATION wrapper for every carve/add.
      - Blender Export Hook: Logic to export the resulting mesh to glTF for refinement.\n\n${codeBlock}`;

    case Feature.PROTOCOL_SYNC:
      return `Implement a Google Drive OAuth2 Handshake Manager in GDScript.
      - Logic for "Sign in with Google" simulation.
      - Function to fetch Narrative stems (gdoc) and Audio cues (wav).
      - Integration with Ouroboros-8 protocol status.
      - Tone: Rhythmic, energetic, and professional.\n\n${codeBlock}`;

    case Feature.SYSTEM_AUDIT:
      return `Perform a deep scan of the Narrative Vault and Audio Stems.
      - Report on the stability of Signal Sigma's anchor.
      - Search for any anomalies in the Planet Gravity mass core logic.
      - Check WAL drift between GitHub and Local SQLite.`;

    default:
      return `Analyze VCN-3.5 compatibility.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: feature === Feature.GALAXY_MAP_GEN ? 0.9 : 0.3,
      tools: [{ googleSearch: {} }] // For grounding in latest lore/assets if needed
    };

    if (feature === Feature.GALAXY_MAP_GEN) {
      config.responseMimeType = "application/json";
      config.responseSchema = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            spectral_class: { type: Type.STRING },
            coords: { 
              type: Type.ARRAY, 
              items: { type: Type.NUMBER },
              minItems: 2,
              maxItems: 2
            },
            planets: { type: Type.NUMBER },
            faction: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["name", "spectral_class", "coords", "planets", "faction", "description"]
        }
      };
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

