  return (
    <div 
      className="bg-taupe/5 border-2 border-earth/40 flex flex-col h-full overflow-hidden shadow-inner rolodex-container"
      onWheel={handleWheel}
      ref={containerRef}
    >
      <div className="bg-earth px-3 py-1.5 border-b border-earth flex justify-between items-center z-30 shrink-0">
        <h3 className="text-[9px] font-black text-cream uppercase tracking-widest italic">Wormhole_Assets</h3>
        <div className="flex gap-1 items-center">
          <div className="w-1.5 h-1.5 bg-neonOrange animate-pulse"></div>
        </div>
      </div>

      <div className="flex-grow overflow-hidden p-1 flex flex-col perspective-[1200px] transform-style-3d bg-cream/20">
        <div className="space-y-0 py-8">
          {MOTHER_BRAIN_ASSETS.map((asset, i) => (
