import React, { useState, useEffect, useRef } from 'react';
import { MotherBrainAsset } from '../types';
import { MOTHER_BRAIN_ASSETS } from '../constants';

interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
  index: number;
  scrollOffset: number;
  isPanelActive: boolean;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId, index, scrollOffset, isPanelActive }) => {
  const [isOpen, setIsOpen] = useState(level < 1 || asset.id === 'ai-core-yellow');
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.id === 'ai-core-yellow') return '📂';
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      case 'image_asset': return '🖼️';
      case 'data_pillar': return '🏛️';
      default: return '📄';
    }
  };

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (hasChildren) {
      setIsOpen(!isOpen);
    } else {
      onSelect(asset);
    }
  };

  const style = asset.color && asset.type === 'folder' 
    ? { borderLeft: `4px solid ${asset.color}`, color: asset.color } 
    : {};

  // More pronounced rolling cylinder math
  const itemsVisible = 12;
  const anglePerItem = 18;
  const relativeIndex = index - scrollOffset;
  const rotation = relativeIndex * anglePerItem;

  // Hide items that are too far back or forward in the loop
  const opacity = Math.max(0, 1 - Math.abs(relativeIndex) / (itemsVisible / 2));
  const z = Math.cos(rotation * Math.PI / 180) * 150 - 150;
  const yTranslate = Math.sin(rotation * Math.PI / 180) * 150;

  const currentRotation = isPanelActive ? 0 : rotation;
  const currentY = isPanelActive ? 0 : yTranslate;
  const currentZ = isPanelActive ? 0 : z;

  return (
    <div 
      className={`rolodex-item absolute w-full font-mono text-[9px] select-none transition-all duration-300 group`}
      style={{
        transform: `translateY(${currentY}px) translateZ(${currentZ}px) rotateX(${-currentRotation}deg)`,
        opacity: opacity,
        pointerEvents: opacity < 0.3 ? 'none' : 'auto',
        zIndex: Math.round(opacity * 100)
      }}
    >
      <div 
        className={`flex items-center gap-2 py-1.5 px-3 cursor-pointer transition-all border-l-2 ${
          isSelected 
            ? 'bg-burgundy/20 border-burgundy text-earth shadow-[0_0_15px_rgba(128,0,32,0.2)]' 
            : 'border-transparent text-earth/70 hover:bg-white hover:border-neonOrange hover:text-earth'
        }`}
        style={{ paddingLeft: `${level * 8 + 12}px`, ...style }}
        onClick={handleClick}
      >
        <span className={`opacity-80 transition-transform group-hover:scale-110`}>{getIcon()}</span>
        <span className={`truncate transition-all ${asset.id === 'ai-core-yellow' ? 'font-black tracking-widest uppercase text-earth underline decoration-burgundy/40' : ''} ${isSelected ? 'font-black text-burgundy' : 'group-hover:font-bold'}`}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-earth/20 ml-4 mt-0.5">
          {asset.children!.map((child, i) => (
            <AssetNode 
              key={child.id} 
              asset={child} 
              level={level + 1} 
              onSelect={onSelect} 
              selectedId={selectedId} 
              index={index + (i + 1) * 0.5} 
              scrollOffset={scrollOffset} 
              isPanelActive={isPanelActive} 
            />
          ))}
        </div>
      )}
    </div>
  );
};

interface MotherBrainRepoProps {
  onSelectAsset: (asset: MotherBrainAsset) => void;
  selectedAssetId?: string;
  isPanelActive: boolean;
