export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: feature === Feature.GALAXY_MAP_GEN ? 0.9 : 0.4,
    };

    if (feature === Feature.GALAXY_MAP_GEN) {
      config.responseMimeType = "application/json";
      config.responseSchema = {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            name: { type: Type.STRING },
            spectral_class: { type: Type.STRING },
            coords: { 
              type: Type.ARRAY, 
              items: { type: Type.NUMBER },
              minItems: 2,
              maxItems: 2
            },
            planets: { type: Type.NUMBER },
            faction: { type: Type.STRING },
            description: { type: Type.STRING }
          },
          required: ["name", "spectral_class", "coords", "planets", "faction", "description"]
        }
      };
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

