import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import UISettingsPanel from './components/UISettingsPanel';
import NeonParticles from './components/NeonParticles';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT, HARDWARE_TARGETS } from './constants';
import { Feature, CameraSettings, MotherBrainAsset, UISettings, HardwareProfile } from './types';
import { generateContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.PROTOCOL_SYNC);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [gamepadConnected, setGamepadConnected] = useState(false);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS'>('INTEGRATIONS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0,
    scanlineWeight: 0.25,
    flickerSpeed: 0.1,
    enableSway: true,
    chromaticAberration: true,
    theme: 'cream',
    moltMode: true,
    touchOptimization: false,
    hardwareProfile: 'BALANCED'
  });

  const lastProcessedRef = useRef(0);

  // Auto-calibrate settings based on Hardware Profile
  useEffect(() => {
    switch (uiSettings.hardwareProfile) {
      case 'LEGACY':
        setUiSettings(prev => ({ 
          ...prev, 
          glitchIntensity: 0.2, 
          scanlineWeight: 0.1, 
          enableSway: false, 
          chromaticAberration: false,
          touchOptimization: true 
        }));
        break;
      case 'MOBILE_STARK':
        setUiSettings(prev => ({ 
          ...prev, 
          glitchIntensity: 1.2, 
          touchOptimization: true,
          enableSway: true 
        }));
        break;
      case 'ULTRA':
        setUiSettings(prev => ({ 
          ...prev, 
          glitchIntensity: 2.5, 
          chromaticAberration: true, 
          enableSway: true 
        }));
        break;
    }
  }, [uiSettings.hardwareProfile]);

  // Sync UI settings to HTML attributes and CSS variables
  useEffect(() => {
    const root = document.documentElement;
    root.setAttribute('data-theme', uiSettings.theme);
    root.style.setProperty('--glitch-intensity', uiSettings.glitchIntensity.toString());
    root.style.setProperty('--scanline-opacity', uiSettings.scanlineWeight.toString());
    root.style.setProperty('--flicker-duration', `${uiSettings.flickerSpeed}s`);
    root.style.setProperty('--chromatic-shift', uiSettings.chromaticAberration ? '2px' : '0px');
  }, [uiSettings]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: 'cream' | 'void') => {
    if (uiSettings.moltMode) {
      setIsMolting(true);
      setTimeout(() => {
        setUiSettings(prev => ({ ...prev, theme: newTheme }));
        setTimeout(() => setIsMolting(false), 400);
      }, 300);
    } else {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
    }
  }, [uiSettings.moltMode]);

  const handleOpenApiKey = async () => {
    // @ts-ignore
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
    }
    setRequiresApiKey(false);
  };

  const handleGenerate = useCallback(async () => {
    triggerHandshake();
    setIsLoading(true);
    setRequiresApiKey(false);
    setError(null);

    let statusText = 'ESTABLISHING_NEURAL_BRIDGES';
    if (selectedFeature === Feature.GALAXY_MAP_GEN) statusText = 'SYNTHESIZING_SIGNAL_SIGMA_STRATA';
    if (selectedFeature === Feature.VOXEL_STRATA_MAPPING) statusText = 'DUAL_CONTOURING_OPTIMIZATION';
    if (selectedFeature === Feature.PROTOCOL_SYNC) statusText = 'SYNCING_LOCAL_STATE_TO_GITHUB';

    setLoadingStatus(statusText);

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;

    try {
      const result = await generateContent(selectedFeature, targetCode);
      setOutput(result);
    } catch (err: any) {
      setError(`HANDSHAKE_FAILED: ${err.message}`);
      triggerHandshake();
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  }, [selectedFeature, selectedAsset]);

  useEffect(() => {
    const pollGamepad = () => {
      const gamepads = navigator.getGamepads();
      const gp = gamepads[0];
      if (gp) {
        setGamepadConnected(true);
        const now = Date.now();
        if (now - lastProcessedRef.current < 200) { 
          requestAnimationFrame(pollGamepad);
          return;
        }

        const vertical = gp.axes[1] || (gp.buttons[12]?.pressed ? -1 : gp.buttons[13]?.pressed ? 1 : 0);
        if (Math.abs(vertical) > 0.5) {
          const currentIndex = FEATURES.findIndex(f => f.id === selectedFeature);
          if (vertical > 0.5) {
            const next = (currentIndex + 1) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
            setParticleTrigger(prev => prev + 1);
          } else {
            const next = (currentIndex - 1 + FEATURES.length) % FEATURES.length;
            setSelectedFeature(FEATURES[next].id);
            setParticleTrigger(prev => prev + 1);
          }
          lastProcessedRef.current = now;
        }

        if (gp.buttons[1]?.pressed) { // A
          handleGenerate();
          lastProcessedRef.current = now;
        }
      } else {
        setGamepadConnected(false);
      }
      requestAnimationFrame(pollGamepad);
    };

    const loop = requestAnimationFrame(pollGamepad);
    return () => cancelAnimationFrame(loop);
  }, [selectedFeature, handleGenerate]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);
  const shouldSway = uiSettings.enableSway && !isLoading && !isUISettingsOpen && !isMolting;

  return (
    <div className={`h-full flex flex-col p-4 md:p-6 gap-4 md:gap-6 bg-cream text-earth selection:bg-burgundy selection:text-white transition-all duration-700 overflow-hidden 
      ${isGlitching ? 'fusion-glitch' : ''} 
      ${shouldSway ? 'tv-glitch-active' : 'no-sway'}`}>

      {isMolting && <div className="molting-shred"></div>}

      <UISettingsPanel 
        settings={uiSettings} 
        onUpdate={setUiSettings} 
        onThemeChange={handleMolt}
        onClose={() => setIsUISettingsOpen(false)} 
        isActive={isUISettingsOpen} 
      />

      <header className="flex shrink-0 flex-col md:flex-row items-start md:items-center justify-between border-b-4 border-earth pb-4 px-2 relative gap-4">
        <div className="flex items-center gap-6 relative">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-[4px_4px_0px_var(--accent-primary)] border-2 border-burgundy relative">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange italic">&lt;V&gt;</span>
             <NeonParticles trigger={particleTrigger} color={uiSettings.theme === 'void' ? 'var(--accent-ok)' : 'var(--accent-primary)'} />
          </div>
          <div className="flex flex-col">
            <h1 className="text-2xl md:text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-burgundy neon-text-glow-burgundy italic text-sm tracking-widest">V3.5_EXTREME</span>
            </h1>
            <p className="text-[9px] md:text-[10px] font-black uppercase text-earth/60 tracking-widest">
              HARDWARE: <span className="text-integrityOk neon-text-glow-green">{(HARDWARE_TARGETS as any)[uiSettings.hardwareProfile].name}</span>
            </p>
          </div>
        </div>

        <div className="flex items-center justify-between w-full md:w-auto gap-4 md:gap-8">
          <button 
            onClick={() => setIsUISettingsOpen(true)}
            className="flex flex-col items-center justify-center border-2 border-burgundy/40 px-3 py-1 bg-burgundy/10 hover:bg-burgundy/20 transition-all text-burgundy font-black text-[10px] uppercase tracking-tighter"
          >
            AESTHETICS
            <div className="flex gap-0.5 mt-0.5">
               {[1,2,3].map(i => <div key={i} className={`w-1 h-1 ${uiSettings.theme === 'void' ? 'bg-integrityOk' : 'bg-burgundy/60'}`}></div>)}
            </div>
          </button>
          <div className="hidden sm:flex flex-col items-end gap-1">
            <span className="text-[8px] font-black text-burgundy uppercase tracking-widest italic">GitHub_Remote_Sync</span>
            <div className="flex gap-1">
              {[1, 2, 3, 4, 5].map(i => <div key={i} className={`w-4 h-1 ${isLoading ? 'bg-neonOrange animate-pulse' : 'bg-integrityOk shadow-neon-green'}`}></div>)}
            </div>
          </div>
          <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-1 md:grid-cols-12 gap-4 md:gap-8 overflow-hidden">
        {/* Left Sidebar */}
        <div className="hidden lg:flex lg:col-span-2 flex-col gap-6 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />

          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth shadow-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[7px] font-black uppercase">
              <button 
                onClick={() => setActiveTab('REFS')}
                className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}
              >
                Nomadz_Repo
              </button>
              <button 
                onClick={() => setActiveTab('INTEGRATIONS')}
                className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}
              >
                FOSS_Bridges
              </button>
            </div>

            <div className="flex-grow overflow-hidden p-1 bg-cream/30">
              {activeTab === 'REFS' ? (
                <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={isLoading || isUISettingsOpen || isMolting} profile={uiSettings.hardwareProfile} />
              ) : (
                <IntegrationHub />
              )}
            </div>
          </div>
        </div>

        {/* Center Panel */}
        <div className="col-span-1 md:col-span-4 lg:col-span-3 h-[40vh] md:h-full overflow-hidden order-2 md:order-1">
          <ControlPanel
            features={FEATURES}
            selectedFeature={selectedFeature}
            onSelectFeature={(f) => { setSelectedFeature(f); triggerHandshake(); }}
            onGenerate={handleGenerate}
            isLoading={isLoading}
            gamepadConnected={gamepadConnected}
            touchOptimization={uiSettings.touchOptimization}
          />
        </div>

        {/* Right Panel */}
        <div className="col-span-1 md:col-span-8 lg:col-span-7 flex flex-col gap-4 md:gap-8 overflow-hidden order-1 md:order-2">
          <div className="h-[25vh] md:h-[35%] lg:h-2/5 overflow-hidden">
            <CodeEditor code={selectedAsset?.code || GD_SCRIPT_CODE} fileName={selectedAsset?.name || 'universe_kernel.gd'} />
          </div>
          <div className="h-[35vh] md:h-[65%] lg:h-3/5 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedFeatureInfo?.title || 'Execution_Buffer'}
              featureId={selectedFeature}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
              isSystemAudit={selectedFeature === Feature.SYSTEM_AUDIT}
            />
          </div>
        </div>
      </main>

      <footer className="shrink-0 hidden md:flex justify-between items-center text-[10px] font-black uppercase text-earth/60 border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-integrityOk shadow-neon-green"></div> OUROBOROS-8: ACTIVE</span>
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-burgundy shadow-neon-burgundy"></div> PHI_INDEX: {COSMIC_KEY_CONTEXT.v_header.phi_index}</span>
        </div>
        <div className="flex gap-8 italic">
          <span className="text-earth/40 font-black">VCN-SNAPSHOT-2026-02-01-1353</span>
          <span className="text-burgundy neon-text-glow-burgundy border-b border-burgundy/40 uppercase tracking-widest">Signal_Sigma_Prime_Governance</span>
        </div>
      </footer>

      {error && (
        <div className="fixed bottom-4 right-4 md:bottom-10 md:right-10 bg-earth border-4 border-burgundy p-4 md:p-6 shadow-[10px_10px_0px_var(--accent-burgundy)] z-50 max-w-xs md:max-w-sm animate-bounce text-white">
