import React, { useState, useEffect, useRef, useCallback } from 'react';
import { MotherBrainAsset, HardwareProfile } from '../types';
import { MOTHER_BRAIN_ASSETS } from '../constants';

interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
  index: number;
  scrollOffset: number;
  isPanelActive: boolean;
  profile: HardwareProfile;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId, index, scrollOffset, isPanelActive, profile }) => {
  const [isOpen, setIsOpen] = useState(level < 1 || asset.id === 'ai-core-yellow');
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.id === 'ai-core-yellow') return '📂';
    switch (asset.type) {
      case 'folder': return isOpen ? '📂' : '📁';
      case 'godot_project': return '⚙️';
      case 'addon': return '🧩';
      case 'script': return '📜';
      case 'scene': return '🎬';
      case 'image_asset': return '🖼️';
      case 'data_pillar': return '🏛️';
      default: return '📄';
    }
  };

  const handleClick = (e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    if (hasChildren) {
      setIsOpen(!isOpen);
    } else {
      onSelect(asset);
    }
  };

  const style = asset.color && asset.type === 'folder' 
    ? { borderLeft: `4px solid ${asset.color}`, color: asset.color } 
    : {};

  const isLegacy = profile === 'LEGACY';
  const itemsVisible = 12;
  const anglePerItem = 18;
  const relativeIndex = index - scrollOffset;
  const rotation = relativeIndex * anglePerItem;

  const opacity = Math.max(0, 1 - Math.abs(relativeIndex) / (itemsVisible / 2));

  // Disable 3D transforms for Legacy hardware targets
  const z = isLegacy ? 0 : Math.cos(rotation * Math.PI / 180) * 150 - 150;
  const yTranslate = isLegacy ? relativeIndex * 30 : Math.sin(rotation * Math.PI / 180) * 150;
  const xRotate = isLegacy ? 0 : -rotation;

  const currentRotation = isPanelActive ? 0 : xRotate;
  const currentY = isPanelActive ? 0 : yTranslate;
  const currentZ = isPanelActive ? 0 : z;

  return (
    <div 
      className={`rolodex-item absolute w-full font-mono text-[9px] select-none transition-all duration-300 group`}
      style={{
        transform: `translateY(${currentY}px) translateZ(${currentZ}px) rotateX(${currentRotation}deg)`,
        opacity: isLegacy ? (Math.abs(relativeIndex) < 5 ? 1 : 0) : opacity,
        pointerEvents: opacity < 0.3 && !isLegacy ? 'none' : 'auto',
        zIndex: Math.round(opacity * 100)
      }}
    >
      <div 
        className={`flex items-center gap-2 py-1.5 px-3 cursor-pointer transition-all border-l-2 ${
          isSelected 
            ? 'bg-burgundy/20 border-burgundy text-earth shadow-[0_0_15px_rgba(128,0,32,0.2)]' 
            : 'border-transparent text-earth/70 hover:bg-white hover:border-neonOrange hover:text-earth'
        }`}
        style={{ paddingLeft: `${level * 8 + 12}px`, ...style }}
        onClick={handleClick}
        onTouchEnd={handleClick}
      >
        <span className={`opacity-80 transition-transform group-hover:scale-110`}>{getIcon()}</span>
        <span className={`truncate transition-all ${asset.id === 'ai-core-yellow' ? 'font-black tracking-widest uppercase text-earth underline decoration-burgundy/40' : ''} ${isSelected ? 'font-black text-burgundy' : 'group-hover:font-bold'}`}>
          {asset.name}
        </span>
      </div>
      {hasChildren && isOpen && (
        <div className="border-l border-earth/20 ml-4 mt-0.5">
          {asset.children!.map((child, i) => (
            <AssetNode 
              key={child.id} 
              asset={child} 
              level={level + 1} 
              onSelect={onSelect} 
              selectedId={selectedId} 
              index={index + (i + 1) * 0.5} 
              scrollOffset={scrollOffset} 
              isPanelActive={isPanelActive} 
              profile={profile}
            />
          ))}
        </div>
      )}
    </div>
  );
};

interface MotherBrainRepoProps {
  onSelectAsset: (asset: MotherBrainAsset) => void;
  selectedAssetId?: string;
  isPanelActive: boolean;
  profile: HardwareProfile;
}

const MotherBrainRepo: React.FC<MotherBrainRepoProps> = ({ onSelectAsset, selectedAssetId, isPanelActive, profile }) => {
  const [scrollOffset, setScrollOffset] = useState(0);
  const containerRef = useRef<HTMLDivElement>(null);
  const touchStartY = useRef<number | null>(null);

  const handleWheel = (e: React.WheelEvent) => {
    setScrollOffset(prev => prev + (e.deltaY / 100));
  };

  const handleTouchStart = (e: React.TouchEvent) => {
    touchStartY.current = e.touches[0].clientY;
  };

  const handleTouchMove = useCallback((e: React.TouchEvent) => {
    if (touchStartY.current !== null) {
      const deltaY = touchStartY.current - e.touches[0].clientY;
      setScrollOffset(prev => prev + (deltaY / 40));
      touchStartY.current = e.touches[0].clientY;
    }
  }, []);

  const handleTouchEnd = () => {
    touchStartY.current = null;
  };

  return (
    <div 
      className="bg-taupe/5 border-2 border-earth/40 flex flex-col h-full overflow-hidden shadow-inner rolodex-container touch-none"
      onWheel={handleWheel}
      onTouchStart={handleTouchStart}
      onTouchMove={handleTouchMove}
      onTouchEnd={handleTouchEnd}
      ref={containerRef}
    >
      <div className="bg-earth px-3 py-1.5 border-b border-earth flex justify-between items-center z-50 shrink-0">
        <h3 className="text-[9px] font-black text-cream uppercase tracking-widest italic">Wormhole_Assets</h3>
        <div className="flex gap-1 items-center">
          <div className="w-1.5 h-1.5 bg-neonOrange animate-pulse"></div>
        </div>
      </div>

      <div className="flex-grow overflow-hidden relative p-1 flex flex-col perspective-[1000px] transform-style-3d bg-cream/10">
        <div className="absolute top-1/2 left-0 w-full h-8 -translate-y-1/2 bg-earth/5 pointer-events-none border-y border-earth/10"></div>

        <div className="absolute inset-0 flex items-center justify-center transform-style-3d">
          {MOTHER_BRAIN_ASSETS.map((asset, i) => (
            <AssetNode 
              key={asset.id} 
              asset={asset} 
              level={0} 
              onSelect={onSelectAsset} 
              selectedId={selectedAssetId} 
              index={i} 
              scrollOffset={scrollOffset}
              isPanelActive={isPanelActive}
              profile={profile}
            />
          ))}
        </div>
      </div>

      <div className="p-2 bg-earth/10 border-t border-earth text-[7px] font-bold text-earth/40 uppercase flex justify-between z-50 shrink-0">
        <span>ROLODEX_ROLL_v1.2</span>
        <span className="text-burgundy italic">SD_LOCAL_SYNC</span>
      </div>
    </div>
  );
};

