const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.DRIVE_NOMADZ_SYNC:
      return `Implement a Google Drive Sync Manager for the 'NOMADZ-0' folder in Godot 4.3.
      - Logic must support NON-DESTRUCTIVE MERGE. 
      - Use Choice B persistence (Append-only WAL) to ensure local changes are merged with Drive state without overwriting.
      - Function: 'sync_nomadz_vault(folder_id: String)'
      - If 'KEYZ.txt' is found in the folder, parse it for VCN API signatures.\n\n${codeBlock}`;

    case Feature.LOCAL_TERMUX_BRIDGE:
      return `Implement a Local Bridge for Termux/Rclone in Godot 4.3.
      - Logic to trigger shell commands via 'OS.execute' for rclone sync.
      - Seamlessly scan local paths for 'KEYZ' files.
      - Integrate found API keys into the global 'NomadStats' resource as encrypted meta-data.
      - Ensure this is compatible with Android (S23 Ultra) and Legacy (modded) hardware.\n\n${codeBlock}`;

    case Feature.SKILL_TREE_SYNTHESIS:
      return `Implement a Godot 4.3 Skill Tree system using custom Resources.
      - Every node should be a 'SkillNode' Resource with properties for: name, icon_path, cost, and requirements (Array of SkillNodes).
      - Include a 'SkillTreeManager' script that handles 'unlock_skill' logic.
      - Ensure all unlocks emit a WAL event via the persistence layer.\n\n${codeBlock}`;

    case Feature.CHAR_CUSTOMIZATION:
      return `Implement a Nomad Customization system in Godot 4.3 GDScript.
      - Handle 'Evolutionary Molting' (visual mesh swaps).
      - Logic to update Voxel-based equipment parts.
      - Shader parameter controller for neon glow colors (chromatic kinetics).\n\n${codeBlock}`;

    default:
      return `Analyze VCN-3.5 compatibility for NOMADZ-0 integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

