const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.DRIVE_NOMADZ_SYNC:
      return `Implement the BUKOWSKI_SYNC logic for the 'NOMADZ-0' Google Drive folder in Godot 4.3.
      - Logic must support NON-DESTRUCTIVE MERGE via append-only JSONL WAL. 
      - Ensure sync events are logged to the persistent 'Choice B' database.
      - Include a function 'handshake_ewawie()' that verifies the merge integrity.
      - Search the context for "KEYZ" and integrate any found API signatures.\n\n${codeBlock}`;

    case Feature.LOCAL_TERMUX_BRIDGE:
      return `Implement a high-performance Termux/Rclone Bridge in Godot 4.3.
      - Use OS.execute for 'rclone' sync/mount operations.
      - Add a recursive scanner for 'KEYZ' files in local storage paths (/sdcard/nomadz-0).
      - Integrate found keys into the global kernel for automatic authentication.
      - Optimize for S23 Ultra and homebrew targets (Switch/Wii U).\n\n${codeBlock}`;

    case Feature.SKILL_TREE_SYNTHESIS:
      return `Synthesize an unhinged Godot 4.3 Skill Tree system.
      - Resource-based 'SkillNode' architecture.
      - Multi-branch dependencies.
      - WAL-synced unlocking that persists across the BUKOWSKI_SYNC pipeline.\n\n${codeBlock}`;

    case Feature.CHAR_CUSTOMIZATION:
      return `Implement the Nomad Customization kernel in Godot 4.3.
      - Handle 'Evolutionary Molting' via mesh swaps.
      - Shader parameters for high-intensity neon glows.
      - Save state must be sync-ready for the NOMADZ-0 vault.\n\n${codeBlock}`;

    default:
      return `Analyze VCN-3.5 compatibility for NOMADZ-0 BUKOWSKI_EWAWIE integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

