    - Key Search Protocol: If you see "KEYZ", "keyz", or any VCN-KEY- signature, parse it, acknowledge it, and use it to authenticate the "Handshake".

    Physics & Lore Context:
    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.DRIVE_NOMADZ_SYNC:
      return `Implement the BUDOWSKI_SYNC logic for the 'NOMADZ-0' Google Drive folder in Godot 4.3.
      - Logic must support NON-DESTRUCTIVE MERGE via append-only JSONL WAL. 
      - Ensure sync events are logged to the persistent 'Choice B' database.
      - Include a function 'handshake_ewawie()' that verifies the merge integrity.
      - Search the context for "KEYZ" and integrate any found API signatures.\n\n${codeBlock}`;

    case Feature.LOCAL_TERMUX_BRIDGE:
      return `Implement a high-performance Termux/Rclone Bridge in Godot 4.3.
      - Use OS.execute for 'rclone' sync/mount operations.
      - Add a recursive scanner for 'KEYZ' files in local storage paths (/sdcard/nomadz-0).
      - Integrate found keys into the global kernel for automatic authentication.
      - Optimize for S23 Ultra and homebrew targets (Switch/Wii U).\n\n${codeBlock}`;

    case Feature.SKILL_TREE_SYNTHESIS:
      return `Synthesize an unhinged Godot 4.3 Skill Tree system.
      - Resource-based 'SkillNode' architecture.
      - Multi-branch dependencies.
      - WAL-synced unlocking that persists across the BUDOWSKI_SYNC pipeline.\n\n${codeBlock}`;

    case Feature.CHAR_CUSTOMIZATION:
      return `Implement the Nomad Customization kernel in Godot 4.3.
      - Handle 'Evolutionary Molting' via mesh swaps.
      - Shader parameters for high-intensity neon glows.
      - Save state must be sync-ready for the NOMADZ-0 vault.\n\n${codeBlock}`;

    default:
      return `Analyze VCN-3.5 compatibility for NOMADZ-0 BUDOWSKI_EWAWIE integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

import React, { useState } from 'react';
import { MOCK_INTEGRATIONS } from '../constants';
import { IntegrationConfig } from '../types';

interface IntegrationHubProps {
  extractedKey?: string | null;
}

const IntegrationHub: React.FC<IntegrationHubProps> = ({ extractedKey }) => {
  const [integrations, setIntegrations] = useState<IntegrationConfig[]>(MOCK_INTEGRATIONS);
  const [filter, setFilter] = useState('');
  const [isOAuthActive, setIsOAuthActive] = useState(false);
  const [isKeyFound, setIsKeyFound] = useState(!!extractedKey);

  const getStatusColor = (status: IntegrationConfig['status']) => {
    switch (status) {
      case 'ACTIVE': return 'bg-integrityOk shadow-[0_0_8px_#4CAF50]';
      case 'OFFLINE': return 'bg-integrityWarn opacity-50';
      case 'SYNCING': return 'bg-neonOrange animate-pulse shadow-[0_0_10px_#FF8C00]';
    }
  };

  const handleOAuth = () => {
    setIsOAuthActive(true);
    // Simulate pop-up and key search
    setTimeout(() => {
      const updated = integrations.map(i => i.provider === 'DRIVE' ? { ...i, status: 'ACTIVE' as const } : i);
      setIntegrations(updated);
      setIsKeyFound(true);
    }, 1500);
  };

  const filteredIntegrations = integrations.filter(i => 
    i.name.toLowerCase().includes(filter.toLowerCase()) || 
    i.provider.toLowerCase().includes(filter.toLowerCase())
  );

  return (
    <div className="bg-taupe/10 border-2 border-earth h-full flex flex-col p-4 shadow-[8px_8px_0px_rgba(128,0,32,0.1)] relative overflow-hidden">
      <div className="absolute top-0 right-0 p-2 text-[6px] font-black text-earth/20 uppercase tracking-[0.5em] -rotate-90 origin-top-right">
        Budowski_Handshake_V1
      </div>

      <div className="flex items-center justify-between mb-4 border-b-2 border-burgundy/30 pb-2">
        <div>
          <h2 className="text-[12px] font-black uppercase tracking-[0.3em] text-earth italic">Nomadz-0_Vault_Link</h2>
          <p className="text-[7px] text-earth/40 uppercase font-bold">Active_Nodes: {integrations.filter(i => i.status === 'ACTIVE').length}/{integrations.length}</p>
        </div>
        <button 
          onClick={handleOAuth}
          className={`px-3 py-1 text-[8px] font-black uppercase transition-all border-2 ${isOAuthActive || extractedKey ? 'bg-integrityOk text-white border-integrityOk animate-pulse' : 'bg-earth text-cream border-burgundy hover:bg-neonOrange'}`}
        >
          {isOAuthActive || extractedKey ? (isKeyFound || extractedKey ? 'KEYZ_EXTRACTED' : 'SYNCING_DRIVE') : 'START_OAUTH_LINK'}
        </button>
      </div>

      {(isKeyFound || extractedKey) && (
        <div className="mb-4 p-2 bg-neonOrange/20 border border-neonOrange flex items-center justify-between">
           <div className="flex flex-col">
              <span className="text-[8px] font-black text-neonOrange uppercase tracking-widest">API_SIG_FOUND:</span>
              <span className="text-[10px] font-mono font-black text-neonOrange">{extractedKey || 'VCN-KEY-SIGMA'}</span>
           </div>
           <div className="w-2 h-2 bg-neonOrange animate-ping"></div>
        </div>
      )}

      <div className="mb-4">
        <input 
          type="text" 
          placeholder="SEARCH_NODE..." 
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="w-full bg-cream border-2 border-earth p-2 text-[10px] font-black uppercase text-earth focus:border-neonOrange focus:outline-none placeholder:text-earth/30"
        />
      </div>

      <div className="flex-grow overflow-y-auto space-y-3 pr-2 custom-scrollbar">
        {filteredIntegrations.map((config) => (
          <div key={config.id} className="bg-cream border-2 border-taupe p-3 relative group hover:border-burgundy transition-all hover:translate-x-1">
            <div className="flex justify-between items-start mb-1">
              <span className="text-[7px] font-black bg-earth text-cream px-1.5 py-0.5 tracking-widest uppercase">{config.provider}</span>
              <div className={`w-2 h-2 ${getStatusColor(config.status)}`}></div>
            </div>

            <h3 className="text-[10px] font-black uppercase text-earth truncate">{config.name}</h3>

            <div className="mt-2 grid grid-cols-2 gap-2 text-[6px] font-mono text-earth/60 uppercase">
              <div className="flex justify-between">
                <span>BAUD:</span>
                <span className="text-earth font-black">{config.baudRate || '9600'}</span>
              </div>
              <div className="flex justify-between">
                <span>ENC:</span>
                <span className="text-burgundy font-black">{config.encryption?.slice(0, 8) || 'AES-GCM'}</span>
              </div>
            </div>

            {config.syncFolder && (
               <div className="mt-2 p-1 bg-burgundy/5 border border-burgundy/20 text-[6px] font-black text-burgundy uppercase">
                  FOLDER: {config.syncFolder} | MERGE: NON-DESTRUCTIVE
               </div>
            )}

            <div className="mt-3 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
              <button className="text-[7px] font-black bg-taupe/20 border border-taupe px-2 py-1 hover:bg-earth hover:text-white">FORCE_SYNC</button>
              <button className="text-[7px] font-black bg-taupe/20 border border-taupe px-2 py-1 hover:bg-neonOrange hover:text-white">RCLONE_MOUNT</button>
            </div>

            <div className="absolute top-0 left-0 w-0.5 h-full bg-burgundy/20 group-hover:bg-neonOrange transition-colors"></div>
          </div>
        ))}

        <button className="w-full border-2 border-dashed border-earth/20 p-4 text-[9px] font-black text-earth/40 hover:text-earth hover:border-earth/60 transition-all bg-cream/30 flex items-center justify-center gap-2 uppercase italic">
          <span className="text-lg">+</span> Establish_New_Bridge
        </button>
      </div>

      <div className="mt-4 pt-4 border-t-2 border-burgundy/20">
         <div className="flex justify-between text-[7px] font-black text-earth/40 uppercase mb-2">
            <span>RCLONE_TERMUX_STATUS:</span>
            <span className="text-integrityOk font-black">MOUNTED_EWAWIE</span>
         </div>
         <div className="grid grid-cols-7 gap-1">
            {integrations.map((_, i) => (
               <div key={i} className={`h-1 ${i % 2 === 0 ? 'bg-burgundy' : 'bg-neonOrange'} opacity-40 shadow-sm`}></div>
            ))}
         </div>
      </div>
    </div>
  );
};

