export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationContext = `The following is a high-baud meeting between VCN-4.0 AI Agents. 
  The prompt is: "${prompt}". 
  The meeting participants are: ${agents.map(a => a.name + " (" + a.role + ")").join(", ")}.
  Respond as your assigned persona and build upon the previous agents' insights.`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationContext + `\n\nNOW RESPONDING: ${agent.name} (${agent.role})`,
        config: {
          systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
          temperature: 0.7,
        },
      });

      const text = response.text || "NO_DATA_RECEIVED";
      messages.push({
        agentId: agent.id,
        text: text,
        timestamp: new Date().toLocaleTimeString()
      });

      // Update context for the next agent
      conversationContext += `\n\n${agent.name}: ${text}`;
    } catch (error: any) {
      messages.push({
        agentId: agent.id,
        text: `COMMUNICATION_FAULT: ${error.message}`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
  }

  return messages;
};

