import React, { useState, useEffect } from 'react';
import { Feature, StarSystem, MeetingMessage, LoreEntry } from '../types';
import GalaxyMap from './GalaxyMap';
import { MEETING_AGENTS, LORE_DATA } from '../constants';

interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
  featureId: Feature;
  videoUrl?: string;
  requiresApiKey?: boolean;
  onOpenApiKey?: () => void;
  loadingStatus?: string;
  meetingMessages?: MeetingMessage[];
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ 
  output, 
  isLoading, 
  featureTitle, 
  featureId,
  requiresApiKey, 
  onOpenApiKey,
  loadingStatus,
  meetingMessages = []
}) => {
  const [flipKey, setFlipKey] = useState(0);
  const [starData, setStarData] = useState<StarSystem[]>([]);
  const [selectedLore, setSelectedLore] = useState<LoreEntry | null>(LORE_DATA[0]);

  useEffect(() => {
    if (output || isLoading || featureId === Feature.AI_GROUP_MEETING || featureId === Feature.LORE_BIBLE) {
      setFlipKey(prev => prev + 1);
    }

    if (featureId === Feature.GALAXY_MAP_GEN && output && !isLoading) {
      try {
        const parsed = JSON.parse(output);
        if (Array.isArray(parsed)) setStarData(parsed);
      } catch (e) {
        console.error("Failed to parse galaxy data", e);
      }
    }
  }, [output, isLoading, featureId]);

  const renderWarRoom = () => (
    <div className="h-full flex flex-col gap-4 animate-in fade-in zoom-in-95 duration-500 overflow-hidden">
      <div className="flex justify-between items-center bg-burgundy/10 border-2 border-burgundy p-4 shadow-[0_0_15px_var(--accent-burgundy)]">
        <div>
          <h2 className="text-burgundy font-black uppercase text-[12px] tracking-widest italic neon-text-glow-burgundy">Omni_AI_War_Room_v4.5</h2>
          <p className="text-earth/60 text-[8px] font-bold uppercase mt-1">Status: CONFERENCE_ACTIVE | Protocol: BUDOWSKI_SYNC</p>
        </div>
        <div className="flex gap-4 items-center">
           <div className="text-[7px] text-earth font-black uppercase">Refreshments: OLD_BUDOWSKI_BEER</div>
           <div className="w-4 h-4 bg-neonOrange animate-pulse rounded-full border border-burgundy"></div>
        </div>
      </div>

      <div className="grid grid-cols-3 gap-4 shrink-0">
        {MEETING_AGENTS.map(agent => (
          <div key={agent.id} className="bg-earth border-2 p-3 flex flex-col gap-2 relative group overflow-hidden" style={{ borderColor: agent.color }}>
            <div className="flex justify-between items-center z-10">
               <span className="text-[9px] font-black uppercase" style={{ color: agent.color }}>{agent.name}</span>
               <div className="w-1.5 h-1.5 rounded-full animate-ping" style={{ backgroundColor: agent.color }}></div>
            </div>
            <div className="text-[7px] text-cream/60 uppercase font-black z-10">{agent.role}</div>
            <div className="flex-grow flex items-center justify-center py-2 z-10">
               <div className="text-3xl filter brightness-150 drop-shadow-[0_0_8px_currentColor]" style={{ color: agent.color }}>🤖</div>
            </div>
            <div className="absolute inset-0 bg-black/20 opacity-40 pointer-events-none group-hover:bg-transparent transition-all"></div>
            <div className="absolute top-0 left-0 w-full h-px bg-white/10 animate-[scan_2s_linear_infinite]"></div>
          </div>
        ))}
      </div>

      <div className="flex-grow flex flex-col gap-2 overflow-hidden bg-taupe/10 border-2 border-earth p-4 relative brutalist-grid">
         <h3 className="text-[10px] font-black text-earth uppercase italic border-b border-earth/20 pb-1">Meeting_Transcript_Buffer</h3>
         <div className="flex-grow overflow-y-auto space-y-4 pr-2 custom-scrollbar">
            {isLoading && (
              <div className="flex flex-col items-center justify-center h-full opacity-40">
                <div className="w-12 h-12 border-4 border-earth border-t-neonOrange animate-spin rounded-full mb-4"></div>
                <p className="text-[10px] font-black uppercase">Syncing_Agent_Neural_Streams...</p>
              </div>
            )}
            {meetingMessages.map((msg, i) => {
              const agent = MEETING_AGENTS.find(a => a.id === msg.agentId);
              return (
                <div key={i} className="animate-in slide-in-from-left-4 duration-300">
                   <div className="flex items-center gap-2 mb-1">
                      <span className="text-[8px] font-black uppercase px-2 py-0.5" style={{ backgroundColor: agent?.color, color: 'white' }}>{agent?.name}</span>
                      <span className="text-[7px] text-earth/40">{msg.timestamp}</span>
                   </div>
                   <p className="text-[10px] font-mono leading-relaxed text-earth/80 bg-cream/50 p-2 border-l-2" style={{ borderLeftColor: agent?.color }}>
                      {msg.text}
                   </p>
                </div>
              );
            })}
         </div>
      </div>
    </div>
  );

  const renderLoreBible = () => (
    <div className="h-full flex flex-col gap-4 animate-in fade-in slide-in-from-right-10 duration-500 overflow-hidden">
      <div className="flex justify-between items-center bg-burgundy border-2 border-neonOrange p-4 shadow-[0_0_15px_rgba(255,140,0,0.3)]">
        <div>
          <h2 className="text-neonOrange font-black uppercase text-[12px] tracking-[0.3em] italic neon-text-glow-orange">Chronicle_Nexus_v4.5</h2>
          <p className="text-cream/60 text-[8px] font-bold uppercase mt-1">Archive: SIGNAL_SIGMA_BIBLE | Node: VCN_HISTORY</p>
        </div>
        <div className="text-cream font-black text-[10px] italic">NOMADZ_VAULT_OPEN</div>
      </div>

      <div className="flex-grow flex gap-4 overflow-hidden">
        {/* Lore Sidebar */}
        <div className="w-1/3 flex flex-col gap-2 overflow-y-auto custom-scrollbar bg-earth p-2 border-2 border-burgundy">
           {['SIGNAL_SIGMA', 'PROTOCOL', 'MANIFESTO', 'MEMOIRS', 'LOGS'].map(cat => (
             <div key={cat} className="mb-4">
                <h4 className="text-[7px] font-black text-neonOrange/60 uppercase tracking-widest mb-1 border-b border-neonOrange/20">{cat}</h4>
                <div className="flex flex-col gap-1">
                   {LORE_DATA.filter(d => d.category === cat).map(entry => (
                     <button
                        key={entry.id}
                        onClick={() => setSelectedLore(entry)}
                        className={`text-left p-2 text-[8px] font-black uppercase transition-all border-l-2 ${selectedLore?.id === entry.id ? 'bg-burgundy text-neonOrange border-neonOrange shadow-inner' : 'bg-taupe/20 text-cream/40 border-transparent hover:border-cream/20'}`}
                     >
                        {entry.title}
                     </button>
                   ))}
                </div>
             </div>
           ))}
        </div>

        {/* Reader Area */}
        <div className="flex-grow bg-cream border-2 border-earth p-6 relative overflow-y-auto custom-scrollbar brutalist-grid">
           {selectedLore ? (
             <div className="animate-in fade-in zoom-in-95 duration-400">
                <div className="flex justify-between items-start mb-6 border-b-2 border-earth/10 pb-4">
                   <div>
                      <h3 className="text-xl font-black italic uppercase text-earth leading-tight">{selectedLore.title}</h3>
                      <div className="flex gap-4 mt-2">
                         <span className="text-[8px] font-black bg-burgundy text-white px-2 py-0.5 tracking-widest">{selectedLore.category}</span>
                         <span className="text-[8px] font-bold text-earth/40 italic">ID: {selectedLore.id}</span>
                      </div>
                   </div>
                   <div className="text-right">
                      <div className="text-[9px] font-black text-earth/80 uppercase">Auth: {selectedLore.author}</div>
