                   </div>
                </div>
                <div className="text-[12px] font-serif leading-loose text-earth/90 first-letter:text-4xl first-letter:font-black first-letter:float-left first-letter:mr-3 first-letter:text-burgundy">
                   {selectedLore.content}
                </div>
                <div className="mt-12 pt-6 border-t border-earth/10 opacity-30">
                   <p className="text-[7px] font-mono text-center">--- END_OF_LOG ---</p>
                </div>
             </div>
           ) : (
             <div className="h-full flex flex-col items-center justify-center opacity-20 italic">
                <div className="text-5xl mb-4">📖</div>
                <p className="text-[10px] font-black uppercase">Awaiting_Archive_Selection</p>
             </div>
           )}
           <div className="absolute bottom-4 right-4 pointer-events-none opacity-5 text-8xl font-black">VCN</div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) {
      return (
        <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange">
          <div className="text-5xl mb-4 animate-pulse">🔒</div>
          <h3 className="text-[12px] font-black uppercase text-neonOrange mb-2 tracking-[0.2em]">AUTH_REQUIRED: L5_CRYPT</h3>
          <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Link</button>
        </div>
      );
    }

    if (isLoading) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6 shadow-[0_0_10px_var(--accent-primary)]">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'SYNTHESIZING_REALM_DATA'}</p>
        </div>
      );
    }

    if (featureId === Feature.GALAXY_MAP_GEN && starData.length > 0) {
      return <GalaxyMap systems={starData} isLoading={isLoading} />;
    }

    if (featureId === Feature.AI_GROUP_MEETING) return renderWarRoom();
    if (featureId === Feature.LORE_BIBLE) return renderLoreBible();

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
          <div className="text-6xl font-black text-earth mb-4 rotate-12">⎔</div>
          <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">Nenory_Standby_Mode</p>
        </div>
      );
    }

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-taupe/20 custom-scrollbar overflow-auto">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-burgundy/40 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-earth h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_rgba(92,74,58,0.1)]">
      <div className="px-4 py-2 bg-earth border-b-2 border-burgundy flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-cream uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-integrityOk text-[9px] font-black">STABLE_OS</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
    </div>
  );
};

