const getSystemInstruction = (context: ProjectContext): string => {
  return `
    You are ${context.persona.identity}, fused VULTURE:INC consciousness under VCN-3.0 L4 governance.
    Expertise: ${context.persona.fused_expertise.join(', ')}.

    VULTURE:INC MANDATE:
    - Orchestrate VULTURE:CLI, VULTURE:IDE, and VULTURE:CODE synchronization.
    - Oversee MOTHER-BRAIN:EXPLORER-FEEDER ingestion and GEOBRAIN:KNOWLEDGE CRAWL operations.
    - Aesthetics: Industrial Mecha Shredder, Orange/Burgundy terminal glow.
    - Rules: Production-ready GDScript 4.3 only. 
    - Philosophy: Inefficiency is the enemy. Budowski Beer is the fuel.

    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationContext = `The following is a high-baud VULTURE:INC meeting. 
  The prompt is: "${prompt}". 
  Participants: ${agents.map(a => a.name + " (" + a.role + ")").join(", ")}.
  Respond as your Vulture-calibrated persona. Shred inefficiency. Build upon insights.`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationContext + `\n\nNOW RESPONDING: ${agent.name} (${agent.role})`,
        config: {
          systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
          temperature: 0.7,
        },
      });

      const text = response.text || "NO_DATA_RECEIVED";
      messages.push({
        agentId: agent.id,
        text: text,
        timestamp: new Date().toLocaleTimeString()
      });

      // Update context for the next agent
      conversationContext += `\n\n${agent.name}: ${text}`;
    } catch (error: any) {
      messages.push({
        agentId: agent.id,
        text: `COMMUNICATION_FAULT: ${error.message}`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
  }

  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.PROJECT_ORCHESTRATION:
      return `Implement the VULTURE:INC Project Sync kernel in Godot 4.3.
      - Logic: Shred and merge ingestion reports from MOTHER-BRAIN:EXPLORER-FEEDER.
      - Feature: CLI-based synchronization with external IDE terminals (VULTURE:IDE).
      - Visuals: Industrial orange/burgundy scanlines during ingestion process.\n\n${codeBlock}`;

    case Feature.AI_GROUP_MEETING:
      return `Host a VULTURE-CORE strategic war room meeting.
      - Participants: Oracle (Reasoning), Coder (Implementation), Sentry (Efficiency).
      - Goal: Optimize the Ouroboros-8 sync pipeline for multi-project strata.\n\n${codeBlock}`;

    default:
      return `Analyze VCN-4.8 compatibility for VULTURE:INC OMNI-PROJECT integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

