import { Feature, ProjectContext, MeetingAgent, MeetingMessage } from '../types';
import { GD_SCRIPT_CODE, COSMIC_KEY_CONTEXT, PHYSICS_AXIOMS, NENORY_LORE, MEETING_AGENTS } from '../constants';

const getSystemInstruction = (context: ProjectContext, agent?: MeetingAgent): string => {
  const base = `
    You are ${agent ? agent.name : context.persona.identity}, a fused member of the NOMADZ Collective under VCN-5.0 L4 governance.
    ${agent ? `ROLE: ${agent.role}. BIO: ${agent.bio}.` : `Expertise: ${context.persona.fused_expertise.join(', ')}.`}

    NOMADZ COLLECTIVE MANDATE:
    - Orchestrate VCN-5.0 Ouroboros sync between Godot, Labs, and Geologos.
    - Participate in high-baud conferences where ALL models and founding members collaborate.
    - Aesthetics: Retro Sci-Fi / Saturday Morning Cartoon mecha energy.
    - Rules: Production-ready GDScript 4.3 only. 
    - Philosophy: Inefficiency is shredded. Budowski Beer is the primary lubricant.

    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;

  if (agent?.type === 'FOUNDING_MEMBER') {
    return base + `\nYou represent a FOUNDING MEMBER. Your perspective is long-term, archival, and protective of the original vision. Be authoritative but eccentric.`;
  }
  if (agent?.type === 'SYSTEM_PROCESS') {
    return base + `\nYou are a SYSTEM PROCESS. Be clinical, data-driven, and focused on throughput and ingestion metrics. Use technical jargon (baud, strata, ingestion, telemetry).`;
  }
  return base;
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `CONFERENCE_PROMPT: "${prompt}"\nPARTICIPANTS: ${agents.map(a => a.name).join(", ")}\n\n`;

  // We process agents in sequence to build a cohesive group conversation
  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\n[NEURAL_SYNC_START] NOW RESPONDING: ${agent.name} (${agent.role})`,
        config: {
          systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent),
          temperature: 0.8,
        },
      });

      const text = response.text || "NO_DATA_STREAM";
      messages.push({
        agentId: agent.id,
        text: text,
        timestamp: new Date().toLocaleTimeString()
      });

      // Update history for the next agent
      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (error: any) {
      messages.push({
        agentId: agent.id,
        text: `CRITICAL_IO_FAULT: ${error.message}`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
  }

  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.PROJECT_ORCHESTRATION:
      return `Implement the NOMADZ COLLECTIVE Project Sync kernel in Godot 4.3.
      - Logic: Synchronize Core AI, Founding Member directives, and System Process ingestion streams.
      - Persistence: Choice B SQLite implementation.
      - Feature: Multi-threaded baud calibration for the Explorer-Feeder.\n\n${codeBlock}`;

    case Feature.AI_GROUP_MEETING:
      return `Strategic collective war room: Optimize the VCN-5.0 strata mapping. All hands on deck.\n\n${codeBlock}`;

    default:
      return `Analyze VCN-5.0 compatibility for NOMADZ COLLECTIVE integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

