  const [meetingMessages, setMeetingMessages] = useState<MeetingMessage[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [gamepadConnected, setGamepadConnected] = useState(false);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS'>('INTEGRATIONS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [extractedKey, setExtractedKey] = useState<string | null>(null);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0,
    scanlineWeight: 0.25,
    flickerSpeed: 0.1,
    enableSway: true,
    chromaticAberration: true,
    theme: 'cream',
    moltMode: true,
    touchOptimization: false,
    hardwareProfile: 'BALANCED'
  });

  const lastProcessedRef = useRef(0);

  useEffect(() => {
    if (selectedAsset?.name.toLowerCase().includes('keyz')) {
      const code = selectedAsset.code || '';
      const keyMatch = code.match(/VCN-KEY-[A-Z0-9-]+/);
      if (keyMatch) {
        setExtractedKey(keyMatch[0]);
        triggerHandshake();
      }
    }
  }, [selectedAsset]);

  useEffect(() => {
    switch (uiSettings.hardwareProfile) {
      case 'LEGACY':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 0.2, scanlineWeight: 0.1, enableSway: false, chromaticAberration: false, touchOptimization: true }));
        break;
      case 'MOBILE_STARK':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 1.2, touchOptimization: true, enableSway: true }));
        break;
      case 'ULTRA':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 2.5, chromaticAberration: true, enableSway: true }));
        break;
    }
  }, [uiSettings.hardwareProfile]);

  useEffect(() => {
    const root = document.documentElement;
    root.setAttribute('data-theme', uiSettings.theme);
    root.style.setProperty('--glitch-intensity', uiSettings.glitchIntensity.toString());
    root.style.setProperty('--scanline-opacity', uiSettings.scanlineWeight.toString());
    root.style.setProperty('--flicker-duration', `${uiSettings.flickerSpeed}s`);
    root.style.setProperty('--chromatic-shift', uiSettings.chromaticAberration ? '2px' : '0px');
  }, [uiSettings]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: 'cream' | 'void' | 'budowski-dark') => {
    if (uiSettings.moltMode) {
      setIsMolting(true);
      setTimeout(() => {
        setUiSettings(prev => ({ ...prev, theme: newTheme }));
        setTimeout(() => setIsMolting(false), 400);
      }, 300);
    } else {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
    }
  }, [uiSettings.moltMode]);

  const handleOpenApiKey = async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
    }
    setRequiresApiKey(false);
  };

  const handleGenerate = useCallback(async () => {
    triggerHandshake();
    setIsLoading(true);
    setRequiresApiKey(false);
    setError(null);

    let statusText = 'ESTABLISHING_COLLECTIVE_SYNC';
    if (selectedFeature === Feature.AI_GROUP_MEETING) statusText = 'INITIATING_COLLECTIVE_CONFERENCE';
    setLoadingStatus(statusText);

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        setMeetingMessages([]);
        const msgs = await generateMeetingContent("Strategic optimization of VCN-5.0 Collective Sync", MEETING_AGENTS);
        setMeetingMessages(msgs);
      } else {
        const result = await generateContent(selectedFeature, targetCode);
        setOutput(result);
      }
    } catch (err: any) {
      setError(`HANDSHAKE_FAILED: ${err.message}`);
      triggerHandshake();
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  }, [selectedFeature, selectedAsset]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);
  const shouldSway = uiSettings.enableSway && !isLoading && !isUISettingsOpen && !isMolting;

  return (
    <div className={`h-full flex flex-col p-4 md:p-6 gap-4 md:gap-6 bg-cream text-earth selection:bg-burgundy selection:text-white transition-all duration-700 overflow-hidden 
      ${isGlitching ? 'fusion-glitch' : ''} 
      ${shouldSway ? 'tv-glitch-active' : 'no-sway'}`}>

      {isMolting && <div className="molting-shred"></div>}

      <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} />

      <header className="flex shrink-0 flex-col md:flex-row items-start md:items-center justify-between border-b-4 border-earth pb-4 px-2 relative gap-4">
        <div className="flex items-center gap-6 relative">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-[4px_4px_0px_var(--accent-primary)] border-2 border-burgundy relative">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange italic">&lt;V&gt;</span>
             <NeonParticles trigger={particleTrigger} color={uiSettings.theme === 'void' ? 'var(--accent-ok)' : 'var(--accent-primary)'} />
          </div>
          <div className="flex flex-col">
            <h1 className="text-2xl md:text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-burgundy neon-text-glow-burgundy italic text-sm tracking-widest uppercase">{extractedKey ? 'COLLECTIVE_LOADED' : 'V5.0_COLLECTIVE'}</span>
            </h1>
            <p className="text-[9px] md:text-[10px] font-black uppercase text-earth/60 tracking-widest">
              HARDWARE: <span className="text-integrityOk neon-text-glow-green">{(HARDWARE_TARGETS as any)[uiSettings.hardwareProfile].name}</span> | <span className="text-neonOrange">BUDOWSKI_COLLECTIVE</span>
            </p>
          </div>
        </div>

        <div className="flex items-center justify-between w-full md:w-auto gap-4 md:gap-8">
          <button onClick={() => setIsUISettingsOpen(true)} className="flex flex-col items-center justify-center border-2 border-burgundy/40 px-3 py-1 bg-burgundy/10 hover:bg-burgundy/20 transition-all text-burgundy font-black text-[10px] uppercase tracking-tighter">
            AESTHETICS
          </button>
          <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-1 md:grid-cols-12 gap-4 md:gap-8 overflow-hidden">
        <div className="hidden lg:flex lg:col-span-2 flex-col gap-6 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth shadow-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[7px] font-black uppercase">
              <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}>Nomadz_Repo</button>
              <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}>FOSS_Bridges</button>
            </div>
            <div className="flex-grow overflow-hidden p-1 bg-cream/30">
              {activeTab === 'REFS' ? <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={isLoading} profile={uiSettings.hardwareProfile} /> : <IntegrationHub extractedKey={extractedKey} />}
            </div>
          </div>
        </div>

        <div className="col-span-1 md:col-span-4 lg:col-span-3 h-[40vh] md:h-full overflow-hidden order-2 md:order-1">
          <ControlPanel features={FEATURES} selectedFeature={selectedFeature} onSelectFeature={(f) => { setSelectedFeature(f); triggerHandshake(); }} onGenerate={handleGenerate} isLoading={isLoading} touchOptimization={uiSettings.touchOptimization} />
        </div>

        <div className="col-span-1 md:col-span-8 lg:col-span-7 flex flex-col gap-4 md:gap-8 overflow-hidden order-1 md:order-2">
          <div className="h-[25vh] md:h-[35%] lg:h-2/5 overflow-hidden">
