interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
  featureId: Feature;
  videoUrl?: string;
  requiresApiKey?: boolean;
  onOpenApiKey?: () => void;
  loadingStatus?: string;
  meetingMessages?: MeetingMessage[];
}

