          </div>
        </div>
        <div className="flex gap-4 items-center">
           <div className="text-[7px] text-cream font-black uppercase border border-cream/20 px-2 py-0.5">REC ● [ULTRA_BAUD]</div>
           <div className="text-[7px] text-neonOrange font-black">OMNI_GEMINI_ACTIVE</div>
        </div>
      </div>

      {/* Video Grid 4x3 */}
      <div className="flex-grow grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-2 overflow-y-auto p-2 border-2 border-earth/20 relative custom-scrollbar bg-black/60">
        <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-10"></div>
        {MEETING_AGENTS.map(agent => {
          const isSpeaking = activeSpeakerId === agent.id;
          return (
            <div 
              key={agent.id} 
              className={`relative border-2 transition-all duration-300 overflow-hidden group flex flex-col aspect-video ${
                isSpeaking ? 'border-neonOrange shadow-[0_0_15px_rgba(255,140,0,0.4)] scale-[1.02] z-10' : 'border-earth/40 grayscale-[0.6] opacity-80'
              } bg-earth/30`}
