                <div className={`text-3xl filter drop-shadow-[0_0:10px_${agent.color}] ${isSpeaking ? 'animate-bounce' : ''}`}>
                  {agent.icon}
                </div>
                {/* Visual Audio Waveform Overlay */}
                {isSpeaking && (
                  <div className="absolute bottom-0 left-0 w-full h-6 flex items-end justify-center gap-0.5 opacity-60">
