                 <p className="text-[6px] text-cream/80 font-mono leading-tight uppercase italic">{agent.bio}</p>
              </div>

              {/* Scanline / Flicker */}
              <div className="absolute top-0 left-0 w-full h-px bg-white/5 animate-[scan_3s_linear_infinite]"></div>
            </div>
          );
