         <div className="flex-grow overflow-y-auto space-y-2 pr-2 custom-scrollbar">
            {isLoading && meetingMessages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full opacity-40">
                <div className="w-6 h-6 border-2 border-earth border-t-neonOrange animate-spin rounded-full mb-1"></div>
                <p className="text-[7px] font-black uppercase">Ingesting_Drive_Metadata...</p>
              </div>
            )}
            {meetingMessages.map((msg, i) => {
              const agent = MEETING_AGENTS.find(a => a.id === msg.agentId);
              return (
                <div key={i} className="animate-in slide-in-from-bottom-2 duration-300 border-l-2 pl-2 py-0.5" style={{ borderLeftColor: agent?.color }}>
