        <div>
          <h2 className="text-neonOrange font-black uppercase text-[12px] tracking-[0.3em] italic neon-text-glow-orange">OMNI_CHRONICLE_v5.2</h2>
          <p className="text-cream/60 text-[8px] font-bold uppercase mt-1">Archive: DRIVE_RECOVERY_SECTOR | Found: JAX_NORA_GENESIS</p>
        </div>
        <div className="text-cream font-black text-[10px] italic">VAULT_PROTOCOL_STABLE</div>
