                   ))}
                </div>
             </div>
           ))}
        </div>

        {/* Reader Area */}
        <div className="flex-grow bg-cream border-2 border-earth p-6 relative overflow-y-auto custom-scrollbar brutalist-grid">
           {selectedLore ? (
             <div className="animate-in fade-in zoom-in-95 duration-400">
                <div className="flex justify-between items-start mb-6 border-b-2 border-earth/10 pb-4">
                   <div>
                      <h3 className="text-xl font-black italic uppercase text-earth leading-tight">{selectedLore.title}</h3>
                      <div className="flex gap-4 mt-2">
                         <span className="text-[8px] font-black bg-burgundy text-white px-2 py-0.5 tracking-widest">{selectedLore.category}</span>
                         <span className="text-[8px] font-bold text-earth/40 italic">ID: {selectedLore.id}</span>
                      </div>
                   </div>
                   <div className="text-right">
                      <div className="text-[9px] font-black text-earth/80 uppercase">Auth: {selectedLore.author}</div>
                      <div className="text-[7px] text-earth/40 font-mono">{selectedLore.timestamp}</div>
                   </div>
                </div>
                <div className="text-[12px] font-serif leading-loose text-earth/90 first-letter:text-4xl first-letter:font-black first-letter:float-left first-letter:mr-3 first-letter:text-burgundy">
                   {selectedLore.content}
                </div>
                <div className="mt-12 pt-6 border-t border-earth/10 opacity-30">
                   <p className="text-[7px] font-mono text-center">--- END_OF_CHRONICLE ---</p>
                </div>
