           ) : (
             <div className="h-full flex flex-col items-center justify-center opacity-20 italic">
                <div className="text-5xl mb-4">🦅</div>
                <p className="text-[10px] font-black uppercase">Awaiting_Collective_Ingestion</p>
             </div>
           )}
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) {
      return (
        <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange">
          <div className="text-5xl mb-4 animate-pulse">🔒</div>
          <h3 className="text-[12px] font-black uppercase text-neonOrange mb-2 tracking-[0.2em]">AUTH_REQUIRED: OMNI_ROOT</h3>
          <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Omni_Link</button>
        </div>
      );
    }

    if (isLoading && featureId !== Feature.AI_GROUP_MEETING) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6 shadow-[0_0:10px_var(--accent-primary)]">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'SHREDDING_DATA_STREAMS'}</p>
        </div>
      );
    }

    if (featureId === Feature.GALAXY_MAP_GEN && starData.length > 0) {
      return <GalaxyMap systems={starData} isLoading={isLoading} />;
    }

    if (featureId === Feature.AI_GROUP_MEETING) return renderWarRoom();
    if (featureId === Feature.LORE_BIBLE) return renderLoreBible();

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
