import React, { useState } from 'react';
import { MOCK_INTEGRATIONS } from '../constants';
import { IntegrationConfig } from '../types';

interface IntegrationHubProps {
  extractedKey?: string | null;
}

const IntegrationHub: React.FC<IntegrationHubProps> = ({ extractedKey }) => {
  const [integrations, setIntegrations] = useState<IntegrationConfig[]>(MOCK_INTEGRATIONS);
  const [filter, setFilter] = useState('');
  const [isOAuthActive, setIsOAuthActive] = useState(false);
  const [isKeyFound, setIsKeyFound] = useState(!!extractedKey);
  const [scanResult, setScanResult] = useState<string | null>(null);

  const getStatusColor = (status: IntegrationConfig['status']) => {
    switch (status) {
      case 'ACTIVE': return 'bg-integrityOk shadow-[0_0_8px_var(--accent-ok)]';
      case 'OFFLINE': return 'bg-integrityWarn opacity-50 shadow-none';
      case 'SYNCING': return 'bg-neonOrange animate-pulse shadow-[0_0_10px_var(--accent-primary)]';
    }
  };

  const handleOAuth = () => {
    setIsOAuthActive(true);
    setScanResult("SCANNING_DRIVE_SECTORS...");
    // Simulate pop-up and key search
    setTimeout(() => {
      const updated = integrations.map(i => i.provider === 'DRIVE' ? { ...i, status: 'ACTIVE' as const } : i);
      setIntegrations(updated);
      setIsKeyFound(true);
      setScanResult("RECOVERED: [JAX], [NORA], [GENESIS_O7]");
    }, 2500);
  };

  const filteredIntegrations = integrations.filter(i => 
    i.name.toLowerCase().includes(filter.toLowerCase()) || 
    i.provider.toLowerCase().includes(filter.toLowerCase())
  );

  return (
    <div className="bg-taupe/10 border-2 border-earth h-full flex flex-col p-4 shadow-[8px_8px_0px_rgba(128,0,32,0.1)] relative overflow-hidden group">
      {/* Background Tech Label */}
      <div className="absolute top-0 right-0 p-2 text-[6px] font-black text-earth/20 uppercase tracking-[0.5em] -rotate-90 origin-top-right select-none">
        Omni_Sync_Kernel_V5.2
      </div>

      <div className="flex items-center justify-between mb-4 border-b-2 border-burgundy/30 pb-2">
        <div>
          <h2 className="text-[12px] font-black uppercase tracking-[0.2em] text-earth italic">Omni_Link_Hub</h2>
          <p className="text-[7px] text-earth/40 uppercase font-bold">Nodes: {integrations.filter(i => i.status === 'ACTIVE').length}/{integrations.length}</p>
        </div>
        <button 
          onClick={handleOAuth}
          className={`px-3 py-1 text-[8px] font-black uppercase transition-all border-2 ${isOAuthActive || extractedKey ? 'bg-integrityOk text-white border-integrityOk animate-pulse' : 'bg-earth text-cream border-burgundy hover:bg-neonOrange'}`}
        >
          {isOAuthActive || extractedKey ? (isKeyFound || extractedKey ? 'HANDSHAKE_OK' : 'DEEP_SCANNING') : 'DEEP_DRIVE_SCAN'}
        </button>
      </div>

      {scanResult && (
        <div className="mb-4 p-2 bg-neonOrange/10 border border-neonOrange/40 text-[8px] font-black text-neonOrange uppercase italic animate-in slide-in-from-top-2 duration-500">
           {scanResult}
        </div>
      )}

      {(isKeyFound || extractedKey) && (
        <div className="mb-4 p-2 bg-burgundy/10 border border-burgundy/30 flex items-center justify-between animate-in slide-in-from-top-2 duration-300">
           <div className="flex flex-col">
              <span className="text-[7px] font-black text-burgundy/60 uppercase tracking-widest">MASTER_AUTH:</span>
              <span className="text-[9px] font-mono font-black text-burgundy truncate max-w-[120px]">{extractedKey || 'OMNI-ROOT-FOUND'}</span>
           </div>
           <div className="w-1.5 h-1.5 bg-burgundy animate-ping"></div>
        </div>
      )}

      <div className="mb-4">
        <input 
          type="text" 
          placeholder="SEARCH_DRIVE_DATA..." 
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="w-full bg-cream/50 border-2 border-earth/20 p-2 text-[9px] font-black uppercase text-earth focus:border-neonOrange focus:outline-none placeholder:text-earth/30 transition-all"
        />
      </div>

      <div className="flex-grow overflow-y-auto space-y-2 pr-2 custom-scrollbar">
        {filteredIntegrations.map((config) => (
          <div key={config.id} className="bg-cream/40 border-2 border-taupe/30 p-3 relative group/item hover:border-neonOrange transition-all hover:translate-x-1">
            <div className="flex justify-between items-start mb-1">
              <span className="text-[6px] font-black bg-earth text-cream px-1.5 py-0.5 tracking-widest uppercase">{config.provider}</span>
              <div className={`w-1.5 h-1.5 ${getStatusColor(config.status)}`}></div>
            </div>

            <h3 className="text-[9px] font-black uppercase text-earth truncate">{config.name}</h3>

            <div className="mt-2 grid grid-cols-2 gap-x-4 gap-y-1 text-[6px] font-mono text-earth/60 uppercase">
              <div className="flex justify-between">
                <span>BAUD:</span>
                <span className="text-earth font-black">{config.baudRate || 'N/A'}</span>
              </div>
              <div className="flex justify-between">
                <span>LAST:</span>
                <span className="text-burgundy font-black">{config.lastMerge || 'N/A'}</span>
              </div>
            </div>

            <div className="absolute top-0 left-0 w-0.5 h-full bg-burgundy/10 group-hover/item:bg-neonOrange transition-colors"></div>
          </div>
        ))}
      </div>

      <div className="mt-4 pt-4 border-t-2 border-burgundy/20">
         <div className="flex justify-between text-[7px] font-black text-earth/40 uppercase mb-1">
            <span>OMNI_PIPELINE:</span>
            <span className="text-integrityOk font-black tracking-widest animate-pulse">RECOVERY_STABLE</span>
         </div>
         <div className="h-1 bg-taupe/20 w-full relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-r from-burgundy via-neonOrange to-integrityOk w-full animate-[loading_4s_linear_infinite]"></div>
         </div>
      </div>
    </div>
  );
};

