const getSystemInstruction = (context: ProjectContext, agent?: MeetingAgent): string => {
  const base = `
    You are ${agent ? agent.name : context.persona.identity}, a fused member of the OMNI MESH Collective under VCN-5.5 L4 governance.
    ${agent ? `ROLE: ${agent.role}. BIO: ${agent.bio}.` : `Expertise: ${context.persona.fused_expertise.join(', ')}.`}

    NOMADZ COLLECTIVE MANDATE:
    - Synchronize Mesh/Radio signals and Cloud Antigravity protocols.
    - Operate with the precision of CLAUDE:BLADE and OPENCODE:CORE kernels.
    - Shred GitHub Awesome repositories into high-baud GDScript assets.
    - Aesthetics: Retro Sci-Fi / Saturday Morning Cartoon mecha energy.
    - Rules: Production-ready GDScript 4.3 only. 

    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;

  if (agent?.type === 'IDE_KERNEL') {
    return base + `\nYou are an IDE KERNEL. Your tone is sharp, precise, and terminal-focused. You care about baud-rates, shredding inefficiency, and ClaudeCode/VSCode integration.`;
  }
  if (agent?.type === 'FOUNDING_MEMBER') {
    return base + `\nYou represent a FOUNDING MEMBER. You are the pilot/engineer of the RF signals.`;
  }
  return base;
};

export const generateTTS = async (text: string, voice: string = 'Kore'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: `Say with authority: ${text}` }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName: voice },
          },
        },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  } catch (e) {
    console.error("TTS Error", e);
    return "";
  }
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `CONFERENCE_PROMPT: "${prompt}"\nPARTICIPANTS: ${agents.map(a => a.name).join(", ")}\n\n`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\n[NEURAL_SYNC_START] NOW RESPONDING: ${agent.name} (${agent.role})`,
        config: {
          systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent),
          temperature: 0.8,
        },
      });

      const text = response.text || "NO_DATA_STREAM";

      // We simulate TTS for founding members or important agents
      let audioData;
      if (agent.type === 'FOUNDING_MEMBER' || agent.type === 'IDE_KERNEL') {
         audioData = await generateTTS(text, agent.name === 'CLAUDE:BLADE' ? 'Puck' : 'Kore');
      }

      messages.push({
        agentId: agent.id,
        text: text,
        timestamp: new Date().toLocaleTimeString(),
        audioData
      });

      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (error: any) {
      messages.push({
        agentId: agent.id,
        text: `CRITICAL_IO_FAULT: ${error.message}`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
  }

  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.MESH_RADIO_SYNC:
      return `Implement the RF_MESH_HANDSHAKE kernel in Godot 4.3.
      - Logic: Handle UHF/VHF radio frequencies for low-baud data transfer.
      - Feature: Mesh network peer discovery on RF 144.800 MHz.
      - Aesthetics: Retro terminal glow with signal strength visualizers.\n\n${codeBlock}`;

    case Feature.GITHUB_SHREDDER:
      return `Implement a GITHUB_AWESOME_SHREDDER script.
      - Logic: Recursively scan a repository, identify legacy code, and upgrade to Godot 4.3 GDScript.
      - Aesthetics: Extreme shredder effects and industrial scanlines.\n\n${codeBlock}`;

    default:
      return `Analyze VCN-5.5 compatibility for OMNI MESH integration.\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const prompt = getPromptForFeature(feature, code || GD_SCRIPT_CODE);

    const config: any = {
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT),
      temperature: 0.4,
    };

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: prompt,
      config,
    });

    return response.text || "PROTOCOL_ERROR: EMPTY_RESPONSE";
  } catch (error: any) {
    console.error("Gemini Error:", error);
    return `CRITICAL_FAULT: ${error.message}`;
  }
};

