        </div>
      </div>

      <div className="flex-grow grid grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-2 overflow-y-auto p-2 border-2 border-earth/20 relative custom-scrollbar bg-black/60">
        <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-10"></div>
        {MEETING_AGENTS.map(agent => {
          const isSpeaking = activeSpeakerId === agent.id;
          return (
            <div 
              key={agent.id} 
              className={`relative border-2 transition-all duration-300 overflow-hidden group flex flex-col aspect-video ${
                isSpeaking ? 'border-neonOrange shadow-[0_0_15px_rgba(255,140,0,0.4)] scale-[1.02] z-10' : 'border-earth/40 grayscale-[0.6] opacity-80'
              } bg-earth/30`}
            >
              <div className="flex-grow flex items-center justify-center relative bg-taupe/10 overflow-hidden">
                <div className={`text-3xl filter drop-shadow-[0_0:10px_${agent.color}] ${isSpeaking ? 'animate-bounce' : ''}`}>
                  {agent.icon}
                </div>
                {isSpeaking && (
                  <div className="absolute bottom-0 left-0 w-full h-6 flex items-end justify-center gap-0.5 opacity-60">
                    {[1,2,3,4,5].map(i => (
                      <div key={i} className="w-1 bg-neonOrange animate-[pulse_0.4s_infinite_alternate]" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
                    ))}
                  </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
              </div>
              <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5">
                 <span className="text-[7px] font-black uppercase bg-black/60 px-1 border-l-2" style={{ borderLeftColor: agent.color, color: agent.color }}>
                   {agent.name}
                 </span>
              </div>
              <div className="absolute top-0 left-0 w-full h-px bg-white/5 animate-[scan_3s_linear_infinite]"></div>
            </div>
          );
        })}
      </div>

      <div className="h-1/4 flex flex-col gap-2 overflow-hidden bg-cream border-2 border-earth p-2 relative shadow-inner">
         <div className="flex justify-between items-center border-b border-earth/10 pb-1">
            <h3 className="text-[9px] font-black text-earth uppercase italic">Neural_Sync_Buffer</h3>
            <span className="text-[6px] font-mono text-earth/40 animate-pulse">TTS_STT_ACTIVE</span>
         </div>
         <div className="flex-grow overflow-y-auto space-y-2 pr-2 custom-scrollbar">
            {isLoading && meetingMessages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full opacity-40">
                <div className="w-6 h-6 border-2 border-earth border-t-neonOrange animate-spin rounded-full mb-1"></div>
                <p className="text-[7px] font-black uppercase">Establishing_Mesh_Handshake...</p>
              </div>
            )}
            {meetingMessages.map((msg, i) => {
              const agent = MEETING_AGENTS.find(a => a.id === msg.agentId);
              return (
                <div key={i} className="animate-in slide-in-from-bottom-2 duration-300 border-l-2 pl-2 py-0.5" style={{ borderLeftColor: agent?.color }}>
                   <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-lg">{agent?.icon}</span>
                      <span className="text-[8px] font-black uppercase" style={{ color: agent?.color }}>{agent?.name}</span>
                   </div>
                   <p className="text-[10px] font-mono leading-relaxed text-earth italic">
                      {msg.text}
                   </p>
                </div>
              );
            })}
         </div>
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return null; // Logic handled in renderContent original
    if (isLoading && featureId !== Feature.AI_GROUP_MEETING && featureId !== Feature.MESH_RADIO_SYNC) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6 shadow-[0_0:10px_var(--accent-primary)]">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'SHREDDING_DATA_STREAMS'}</p>
        </div>
      );
    }

    if (featureId === Feature.MESH_RADIO_SYNC) return renderMeshMonitor();
    if (featureId === Feature.AI_GROUP_MEETING) return renderWarRoom();

    if (featureId === Feature.GALAXY_MAP_GEN && starData.length > 0) {
      return <GalaxyMap systems={starData} isLoading={isLoading} />;
    }

    if (!output) {
      return (
        <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
          <div className="text-6xl font-black text-earth mb-4 rotate-12">🦅</div>
          <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">Mesh_Standby</p>
        </div>
      );
    }

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-taupe/20 custom-scrollbar overflow-auto">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-burgundy/40 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-earth h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_rgba(92,74,58,0.1)]">
      <div className="px-4 py-2 bg-earth border-b-2 border-burgundy flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-cream uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-integrityOk text-[9px] font-black">OMNI_OS_v5.5_STABLE</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
    </div>
  );
};

export default OutputDisplay;

import React, { useState } from 'react';
import { MOCK_INTEGRATIONS } from '../constants';
import { IntegrationConfig } from '../types';

interface IntegrationHubProps {
  extractedKey?: string | null;
}

const IntegrationHub: React.FC<IntegrationHubProps> = ({ extractedKey }) => {
  const [integrations, setIntegrations] = useState<IntegrationConfig[]>(MOCK_INTEGRATIONS);
  const [filter, setFilter] = useState('');
  const [isOAuthActive, setIsOAuthActive] = useState(false);
  const [isKeyFound, setIsKeyFound] = useState(!!extractedKey);
  const [scanResult, setScanResult] = useState<string | null>(null);

  const getStatusColor = (status: IntegrationConfig['status']) => {
    switch (status) {
      case 'ACTIVE': return 'bg-integrityOk shadow-[0_0_8px_var(--accent-ok)]';
      case 'OFFLINE': return 'bg-integrityWarn opacity-50 shadow-none';
      case 'SYNCING': return 'bg-neonOrange animate-pulse shadow-[0_0_10px_var(--accent-primary)]';
    }
  };

  const handleOAuth = () => {
    setIsOAuthActive(true);
    setScanResult("SCANNING_DRIVE_SECTORS...");
    // Simulate pop-up and key search
    setTimeout(() => {
      const updated = integrations.map(i => (i.provider === 'DRIVE' || i.provider === 'MESH_NET') ? { ...i, status: 'ACTIVE' as const } : i);
      setIntegrations(updated);
      setIsKeyFound(true);
      setScanResult("RECOVERED: [JAX], [NORA], [GENESIS_O7], [RF_SYNC]");
    }, 2500);
  };

  const filteredIntegrations = integrations.filter(i => 
    i.name.toLowerCase().includes(filter.toLowerCase()) || 
    i.provider.toLowerCase().includes(filter.toLowerCase())
  );

  return (
    <div className="bg-taupe/10 border-2 border-earth h-full flex flex-col p-4 shadow-[8px_8px_0px_rgba(128,0,32,0.1)] relative overflow-hidden group">
      <div className="absolute top-0 right-0 p-2 text-[6px] font-black text-earth/20 uppercase tracking-[0.5em] -rotate-90 origin-top-right select-none">
        Mesh_Kernel_V5.5
      </div>

      <div className="flex items-center justify-between mb-4 border-b-2 border-burgundy/30 pb-2">
        <div>
          <h2 className="text-[12px] font-black uppercase tracking-[0.2em] text-earth italic">Collective_Link</h2>
          <p className="text-[7px] text-earth/40 uppercase font-bold">RF_Bridges: {integrations.filter(i => i.status === 'ACTIVE').length}/{integrations.length}</p>
        </div>
        <button 
          onClick={handleOAuth}
          className={`px-3 py-1 text-[8px] font-black uppercase transition-all border-2 ${isOAuthActive || extractedKey ? 'bg-integrityOk text-white border-integrityOk animate-pulse' : 'bg-earth text-cream border-burgundy hover:bg-neonOrange'}`}
        >
          {isOAuthActive || extractedKey ? (isKeyFound || extractedKey ? 'RF_HANDSHAKE_OK' : 'MESH_SCANNING') : 'INIT_RF_SCAN'}
        </button>
      </div>

      {scanResult && (
        <div className="mb-4 p-2 bg-neonOrange/10 border border-neonOrange/40 text-[8px] font-black text-neonOrange uppercase italic animate-in slide-in-from-top-2 duration-500">
           {scanResult}
        </div>
      )}

      <div className="mb-4">
        <input 
          type="text" 
          placeholder="SEARCH_MESH_NODES..." 
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="w-full bg-cream/50 border-2 border-earth/20 p-2 text-[9px] font-black uppercase text-earth focus:border-neonOrange focus:outline-none placeholder:text-earth/30 transition-all"
        />
      </div>

      <div className="flex-grow overflow-y-auto space-y-2 pr-2 custom-scrollbar">
        {filteredIntegrations.map((config) => (
          <div key={config.id} className="bg-cream/40 border-2 border-taupe/30 p-3 relative group/item hover:border-neonOrange transition-all hover:translate-x-1">
            <div className="flex justify-between items-start mb-1">
              <span className="text-[6px] font-black bg-earth text-cream px-1.5 py-0.5 tracking-widest uppercase">{config.provider}</span>
              <div className={`w-1.5 h-1.5 ${getStatusColor(config.status)}`}></div>
            </div>

            <h3 className="text-[9px] font-black uppercase text-earth truncate">{config.name}</h3>

            <div className="mt-2 grid grid-cols-2 gap-x-4 gap-y-1 text-[6px] font-mono text-earth/60 uppercase">
              <div className="flex justify-between">
                <span>BAUD:</span>
                <span className="text-earth font-black">{config.baudRate || 'N/A'}</span>
              </div>
              <div className="flex justify-between">
                <span>FREQ:</span>
                <span className="text-burgundy font-black">{config.provider === 'RADIO_RF' ? '144.8MHz' : '2.4GHz'}</span>
              </div>
            </div>

            <div className="absolute top-0 left-0 w-0.5 h-full bg-burgundy/10 group-hover/item:bg-neonOrange transition-colors"></div>
          </div>
        ))}
      </div>

      <div className="mt-4 pt-4 border-t-2 border-burgundy/20">
         <div className="flex justify-between text-[7px] font-black text-earth/40 uppercase mb-1">
            <span>ANTIGRAVITY_CLOUD:</span>
            <span className="text-integrityOk font-black tracking-widest animate-pulse">STABILIZED</span>
         </div>
         <div className="h-1 bg-taupe/20 w-full relative overflow-hidden">
            <div className="absolute inset-0 bg-gradient-to-r from-burgundy via-neonOrange to-integrityOk w-full animate-[loading_4s_linear_infinite]"></div>
         </div>
      </div>
    </div>
  );
};

export default IntegrationHub;

import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import UISettingsPanel from './components/UISettingsPanel';
import NeonParticles from './components/NeonParticles';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT, HARDWARE_TARGETS, MEETING_AGENTS } from './constants';
import { Feature, CameraSettings, MotherBrainAsset, UISettings, MeetingMessage } from './types';
import { generateContent, generateMeetingContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.PROTOCOL_SYNC);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [meetingMessages, setMeetingMessages] = useState<MeetingMessage[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [loadingStatus, setLoadingStatus] = useState<string | undefined>(undefined);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS'>('INTEGRATIONS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [extractedKey, setExtractedKey] = useState<string | null>(null);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120,
    contrast: 140,
    saturation: 20,
    grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0,
    scanlineWeight: 0.25,
    flickerSpeed: 0.1,
    enableSway: true,
    chromaticAberration: true,
    theme: 'cream',
    moltMode: true,
    touchOptimization: false,
    hardwareProfile: 'BALANCED',
    audioActive: true
  });

  // Speech Recognition (STT) setup
  const recognitionRef = useRef<any>(null);
  useEffect(() => {
    const SpeechRecognition = (window as any).SpeechRecognition || (window as any).webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognitionRef.current = new SpeechRecognition();
      recognitionRef.current.continuous = false;
      recognitionRef.current.interimResults = false;
      recognitionRef.current.onresult = (event: any) => {
        const transcript = event.results[0][0].transcript;
        console.log("Voice Command:", transcript);
        handleVoiceCommand(transcript);
      };
    }
  }, []);

  const handleVoiceCommand = (cmd: string) => {
    setLoadingStatus(`VOICE_CMD_DETECTED: ${cmd.toUpperCase()}`);
    handleGenerate(cmd);
  };

  const startVoiceListen = () => {
    if (recognitionRef.current) {
      triggerHandshake();
      recognitionRef.current.start();
    }
  };

  useEffect(() => {
    if (selectedAsset?.name.toLowerCase().includes('keyz')) {
      const code = selectedAsset.code || '';
      const keyMatch = code.match(/VCN-KEY-[A-Z0-9-]+/);
      if (keyMatch) {
        setExtractedKey(keyMatch[0]);
        triggerHandshake();
      }
    }
  }, [selectedAsset]);

  useEffect(() => {
    switch (uiSettings.hardwareProfile) {
      case 'LEGACY':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 0.2, scanlineWeight: 0.1, enableSway: false, chromaticAberration: false, touchOptimization: true }));
        break;
      case 'MOBILE_STARK':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 1.2, touchOptimization: true, enableSway: true }));
        break;
      case 'ULTRA':
        setUiSettings(prev => ({ ...prev, glitchIntensity: 2.5, chromaticAberration: true, enableSway: true }));
        break;
    }
  }, [uiSettings.hardwareProfile]);

  useEffect(() => {
    const root = document.documentElement;
    root.setAttribute('data-theme', uiSettings.theme);
    root.style.setProperty('--glitch-intensity', uiSettings.glitchIntensity.toString());
    root.style.setProperty('--scanline-opacity', uiSettings.scanlineWeight.toString());
    root.style.setProperty('--flicker-duration', `${uiSettings.flickerSpeed}s`);
    root.style.setProperty('--chromatic-shift', uiSettings.chromaticAberration ? '2px' : '0px');
  }, [uiSettings]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: 'cream' | 'void' | 'budowski-dark') => {
    if (uiSettings.moltMode) {
      setIsMolting(true);
      setTimeout(() => {
        setUiSettings(prev => ({ ...prev, theme: newTheme }));
        setTimeout(() => setIsMolting(false), 400);
      }, 300);
    } else {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
    }
  }, [uiSettings.moltMode]);

  const handleOpenApiKey = async () => {
    if (window.aistudio && typeof window.aistudio.openSelectKey === 'function') {
      await window.aistudio.openSelectKey();
    }
    setRequiresApiKey(false);
  };

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    triggerHandshake();
    setIsLoading(true);
    setRequiresApiKey(false);
    setError(null);

    let statusText = 'ESTABLISHING_COLLECTIVE_SYNC';
    if (selectedFeature === Feature.AI_GROUP_MEETING) statusText = 'INITIATING_COLLECTIVE_CONFERENCE';
    if (selectedFeature === Feature.MESH_RADIO_SYNC) statusText = 'TUNING_RF_FREQUENCY...';
    setLoadingStatus(statusText);

    const targetCode = selectedAsset?.code || GD_SCRIPT_CODE;
    const promptToUse = customPrompt || "Strategic optimization of VCN-5.5 Collective Sync";

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        setMeetingMessages([]);
        const msgs = await generateMeetingContent(promptToUse, MEETING_AGENTS);
        setMeetingMessages(msgs);
      } else {
        const result = await generateContent(selectedFeature, targetCode);
        setOutput(result);
      }
    } catch (err: any) {
      setError(`HANDSHAKE_FAILED: ${err.message}`);
      triggerHandshake();
    } finally {
      setIsLoading(false);
      setLoadingStatus(undefined);
    }
  }, [selectedFeature, selectedAsset]);

  const selectedFeatureInfo = FEATURES.find(f => f.id === selectedFeature);
  const shouldSway = uiSettings.enableSway && !isLoading && !isUISettingsOpen && !isMolting;

  return (
    <div className={`h-full flex flex-col p-4 md:p-6 gap-4 md:gap-6 bg-cream text-earth selection:bg-burgundy selection:text-white transition-all duration-700 overflow-hidden 
      ${isGlitching ? 'fusion-glitch' : ''} 
      ${shouldSway ? 'tv-glitch-active' : 'no-sway'}`}>

      {isMolting && <div className="molting-shred"></div>}

      <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} />

      <header className="flex shrink-0 flex-col md:flex-row items-start md:items-center justify-between border-b-4 border-earth pb-4 px-2 relative gap-4">
        <div className="flex items-center gap-6 relative">
          <div className="w-12 h-12 bg-earth flex items-center justify-center shadow-[4px_4px_0px_var(--accent-primary)] border-2 border-burgundy relative">
             <span className="text-neonOrange text-3xl font-black neon-text-glow-orange italic">&lt;V&gt;</span>
             <NeonParticles trigger={particleTrigger} color={uiSettings.theme === 'void' ? 'var(--accent-ok)' : 'var(--accent-primary)'} />
          </div>
          <div className="flex flex-col">
            <h1 className="text-2xl md:text-3xl font-black uppercase tracking-[-0.08em] text-earth">
              &lt;V&gt; <span className="text-burgundy neon-text-glow-burgundy italic text-sm tracking-widest uppercase">{extractedKey ? 'MESH_LINKED' : 'V5.5_SHREDDER'}</span>
            </h1>
            <p className="text-[9px] md:text-[10px] font-black uppercase text-earth/60 tracking-widest">
              HARDWARE: <span className="text-integrityOk neon-text-glow-green">{(HARDWARE_TARGETS as any)[uiSettings.hardwareProfile].name}</span> | <span className="text-neonOrange">RF_COLLECTIVE</span>
            </p>
          </div>
        </div>

        <div className="flex items-center justify-between w-full md:w-auto gap-4 md:gap-8">
          <button 
            onClick={startVoiceListen}
            className="group flex flex-col items-center justify-center border-2 border-neonOrange/40 px-3 py-1 bg-neonOrange/10 hover:bg-neonOrange/20 transition-all text-neonOrange font-black text-[10px] uppercase tracking-tighter"
          >
            <span className="group-active:animate-ping">VOICE_HANDSHAKE</span>
          </button>
          <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-1 md:grid-cols-12 gap-4 md:gap-8 overflow-hidden">
        <div className="hidden lg:flex lg:col-span-2 flex-col gap-6 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth shadow-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[7px] font-black uppercase">
              <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}>Shredder_Repo</button>
              <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream shadow-inner' : 'text-earth/40 hover:bg-taupe/10'}`}>RF_Bridges</button>
            </div>
            <div className="flex-grow overflow-hidden p-1 bg-cream/30">
              {activeTab === 'REFS' ? <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={isLoading} profile={uiSettings.hardwareProfile} /> : <IntegrationHub extractedKey={extractedKey} />}
            </div>
          </div>
        </div>

        <div className="col-span-1 md:col-span-4 lg:col-span-3 h-[40vh] md:h-full overflow-hidden order-2 md:order-1">
          <ControlPanel features={FEATURES} selectedFeature={selectedFeature} onSelectFeature={(f) => { setSelectedFeature(f); triggerHandshake(); }} onGenerate={handleGenerate} isLoading={isLoading} touchOptimization={uiSettings.touchOptimization} />
        </div>

        <div className="col-span-1 md:col-span-8 lg:col-span-7 flex flex-col gap-4 md:gap-8 overflow-hidden order-1 md:order-2">
          <div className="h-[25vh] md:h-[35%] lg:h-2/5 overflow-hidden">
            <CodeEditor code={selectedAsset?.code || GD_SCRIPT_CODE} fileName={selectedAsset?.name || 'shredder_kernel.gd'} />
          </div>
          <div className="h-[35vh] md:h-[65%] lg:h-3/5 overflow-hidden">
            <OutputDisplay 
              output={output} 
              isLoading={isLoading} 
              featureTitle={selectedFeatureInfo?.title || 'Mesh_Execution_Buffer'}
              featureId={selectedFeature}
              requiresApiKey={requiresApiKey}
              onOpenApiKey={handleOpenApiKey}
              loadingStatus={loadingStatus}
              meetingMessages={meetingMessages}
            />
          </div>
        </div>
      </main>

      <footer className="shrink-0 hidden md:flex justify-between items-center text-[10px] font-black uppercase text-earth/60 border-t-2 border-earth pt-4">
        <div className="flex gap-8">
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-integrityOk shadow-neon-green"></div> RF_MESH: SYNCED</span>
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-burgundy shadow-neon-burgundy"></div> CLOUD_ANTI_G: STABLE</span>
          <span className="flex items-center gap-2 font-bold"><div className="w-2 h-2 bg-neonOrange shadow-neon-orange"></div> PHI_INDEX: {COSMIC_KEY_CONTEXT.v_header.phi_index}</span>
        </div>
      </footer>
    </div>
  );
};

export default App;

export enum Feature {
  EXPLAIN_CODE = 'EXPLAIN_CODE',
  IMAGE_GENERATION = 'IMAGE_GENERATION',
  VIDEO_GENERATION = 'VIDEO_GENERATION',
  LIVE_API_INTEGRATION = 'LIVE_API_INTEGRATION',
  IMAGE_EDITING = 'IMAGE_EDITING',
  COMPLEX_QUERY = 'COMPLEX_QUERY',
  WAL_LOGIC = 'WAL_LOGIC',
