interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
  featureId: Feature;
  videoUrl?: string;
  requiresApiKey?: boolean;
  onOpenApiKey?: () => void;
  loadingStatus?: string;
  meetingMessages?: MeetingMessage[];
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ 
  output, 
  isLoading, 
  featureTitle, 
  featureId,
  requiresApiKey, 
  onOpenApiKey,
  loadingStatus,
  meetingMessages = []
}) => {
  const [flipKey, setFlipKey] = useState(0);
  const [starData, setStarData] = useState<StarSystem[]>([]);
  const [selectedLore, setSelectedLore] = useState<LoreEntry | null>(LORE_DATA[0]);
  const [activeSpeakerId, setActiveSpeakerId] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (output || isLoading || featureId === Feature.AI_GROUP_MEETING || featureId === Feature.LORE_BIBLE) {
      setFlipKey(prev => prev + 1);
    }

    if (meetingMessages.length > 0) {
      const lastMsg = meetingMessages[meetingMessages.length - 1];
      setActiveSpeakerId(lastMsg.agentId);
      if (lastMsg.audioData) {
         playAudio(lastMsg.audioData);
      }
    }
  }, [output, isLoading, featureId, meetingMessages]);

  const playAudio = async (base64: string) => {
    if (!audioContextRef.current) {
      audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
    }
    const ctx = audioContextRef.current;
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);

    const dataInt16 = new Int16Array(bytes.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) {
      channelData[i] = dataInt16[i] / 32768.0;
    }

    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(ctx.destination);
    source.start();
  };

  const renderOmniMeet = () => (
    <div className="h-full flex flex-col gap-3 animate-in fade-in zoom-in-95 duration-500 overflow-hidden bg-black p-1 relative">
      {/* Background Security Label */}
      <div className="absolute inset-0 pointer-events-none opacity-5 brutalist-grid"></div>

      {/* Conference HUD Header */}
      <div className="flex justify-between items-center bg-burgundy border-b-2 border-neonOrange px-4 py-2 shadow-neon-orange relative z-20">
        <div className="flex items-center gap-3">
          <div className="w-3 h-3 bg-neonOrange animate-ping rounded-full"></div>
          <div>
            <h2 className="text-neonOrange font-black uppercase text-[11px] tracking-[0.2em] italic neon-text-glow-orange">OMNI_MEET_v5.8_SECURE</h2>
            <p className="text-cream/50 text-[7px] font-bold uppercase">Hybrid_E2EE_Stream | Signal_Synced</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
           <div className="flex items-center gap-1.5 px-2 py-0.5 border border-integrityOk/40 bg-integrityOk/10">
              <span className="text-[7px] text-integrityOk font-black uppercase">E2EE SECURE</span>
              <div className="w-2 h-2 bg-integrityOk rounded-sm"></div>
           </div>
           <div className="text-[7px] text-neonOrange font-black uppercase border border-neonOrange/20 px-2 py-0.5">REC ● [ULTRA_BAUD]</div>
        </div>
      </div>

      {/* Hybrid Video Grid 4x3 */}
      <div className="flex-grow grid grid-cols-2 md:grid-cols-4 gap-2 overflow-y-auto p-2 border-2 border-earth/20 relative custom-scrollbar bg-black/40 z-10">
        {MEETING_AGENTS.map(agent => {
          const isSpeaking = activeSpeakerId === agent.id;
          const isHuman = agent.type === 'HUMAN_OPERATOR';
          return (
            <div 
              key={agent.id} 
              className={`relative border-2 transition-all duration-300 overflow-hidden group flex flex-col aspect-video ${
                isSpeaking ? 'border-neonOrange shadow-[0_0_15px_rgba(255,140,0,0.4)] scale-[1.02] z-20' : 'border-earth/40 grayscale-[0.6] opacity-80'
              } ${isHuman ? 'bg-integrityOk/5' : 'bg-earth/30'}`}
            >
              <div className="flex-grow flex items-center justify-center relative bg-taupe/10 overflow-hidden">
                <div className={`text-4xl filter drop-shadow-[0_0:10px_${agent.color}] ${isSpeaking ? 'animate-bounce' : ''}`}>
                  {agent.icon}
                </div>
                {isSpeaking && (
                  <div className="absolute bottom-0 left-0 w-full h-8 flex items-end justify-center gap-0.5 opacity-60">
                    {[1,2,3,4,5,6,7,8].map(i => (
                      <div key={i} className="w-1 bg-neonOrange animate-[pulse_0.4s_infinite_alternate]" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
