            {isLoading && meetingMessages.length === 0 && (
              <div className="flex flex-col items-center justify-center h-full opacity-40">
                <div className="w-6 h-6 border-2 border-earth border-t-neonOrange animate-spin rounded-full mb-1"></div>
                <p className="text-[7px] font-black uppercase">Establish_E2EE_Handshake...</p>
              </div>
