            {meetingMessages.map((msg, i) => {
              const agent = MEETING_AGENTS.find(a => a.id === msg.agentId);
              return (
                <div key={i} className="animate-in slide-in-from-bottom-2 duration-300 border-l-2 pl-2 py-0.5" style={{ borderLeftColor: agent?.color }}>
                   <div className="flex items-center gap-2 mb-0.5">
                      <span className="text-lg">{agent?.icon}</span>
