  const [flipKey, setFlipKey] = useState(0);
  const [starData, setStarData] = useState<StarSystem[]>([]);
  const [selectedLore, setSelectedLore] = useState<LoreEntry | null>(LORE_DATA[0]);
  const [activeSpeakerId, setActiveSpeakerId] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (output || isLoading || featureId === Feature.AI_GROUP_MEETING || featureId === Feature.LORE_BIBLE || featureId === Feature.SWARM_ORCHESTRATION || featureId === Feature.OMNI_MEET_HUB) {
      setFlipKey(prev => prev + 1);
    }

    if (meetingMessages.length > 0) {
      const lastMsg = meetingMessages[meetingMessages.length - 1];
      setActiveSpeakerId(lastMsg.agentId);
      if (lastMsg.audioData) {
         playAudio(lastMsg.audioData);
      }
    }
  }, [output, isLoading, featureId, meetingMessages]);

  const playAudio = async (base64: string) => {
    try {
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({sampleRate: 24000});
      }
      const ctx = audioContextRef.current;
      const binaryString = atob(base64);
      const len = binaryString.length;
      const bytes = new Uint8Array(len);
      for (let i = 0; i < len; i++) bytes[i] = binaryString.charCodeAt(i);

      const dataInt16 = new Int16Array(bytes.buffer);
      const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
      const channelData = buffer.getChannelData(0);
      for (let i = 0; i < dataInt16.length; i++) {
        channelData[i] = dataInt16[i] / 32768.0;
      }

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.start();
    } catch (e) {
      console.error("Audio playback error", e);
    }
  };

  const renderSwarmMonitor = () => (
    <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-neonOrange/30 animate-in fade-in duration-500 overflow-hidden relative">
      <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-5"></div>

      <div className="flex justify-between items-center border-b border-neonOrange/40 pb-2 z-10">
        <div className="flex items-center gap-3">
          <div className="w-4 h-4 bg-neonOrange animate-pulse rounded-full shadow-neon-orange"></div>
          <h2 className="text-neonOrange font-black uppercase text-[12px] tracking-widest italic neon-text-glow-orange">SWARM_TOPOLOGY_v6.0</h2>
        </div>
        <div className="text-[8px] font-mono text-neonOrange/60">NODES_ACTIVE: {MEETING_AGENTS.length} | BAUD_AVG: 8.2GBps</div>
      </div>

      <div className="flex-grow grid grid-cols-12 gap-4 z-10 overflow-hidden">
        {/* Swarm Neural Map */}
        <div className="col-span-8 bg-earth/5 border border-neonOrange/20 relative flex items-center justify-center overflow-hidden group">
          <svg className="absolute inset-0 w-full h-full pointer-events-none opacity-40">
             {MEETING_AGENTS.map((a, i) => MEETING_AGENTS.map((b, j) => {
               if (i >= j) return null;
               return <line key={`${i}-${j}`} x1={`${20 + (i*12)}%`} y1={`${30 + (i*8)}%`} x2={`${20 + (j*12)}%`} y2={`${30 + (j*8)}%`} stroke="var(--accent-primary)" strokeWidth="0.5" strokeDasharray="5 5" className="animate-[dash_20s_linear_infinite]" />;
             }))}
          </svg>
          {MEETING_AGENTS.map((agent, i) => (
            <div key={agent.id} className={`absolute w-12 h-12 rounded-full border-2 flex flex-col items-center justify-center transition-all duration-500 ${activeSpeakerId === agent.id ? 'scale-125 border-neonOrange shadow-neon-orange bg-neonOrange/20' : 'border-earth/40 bg-black'}`} style={{ left: `${15 + (i*16)}%`, top: `${20 + (i*12)}%` }}>
               <span className="text-xl">{agent.icon}</span>
               <span className="text-[6px] font-black uppercase text-neonOrange mt-1">{agent.name}</span>
            </div>
          ))}
        </div>

        {/* Daemon Heartbeat Panel */}
        <div className="col-span-4 flex flex-col gap-2 overflow-y-auto custom-scrollbar">
           <div className="text-[9px] font-black text-neonOrange uppercase border-b border-neonOrange/20 mb-2 italic">Daemon_Logs</div>
           {['K0_HEARTBEAT_OK', 'SENTRY_STRATA_SCAN_COMPLETE', 'E2EE_VAULT_ROTATED', 'TG_POLL_ACTIVE'].map((log, i) => (
             <div key={i} className="bg-neonOrange/5 border-l-2 border-neonOrange p-2 animate-in slide-in-from-left-2 duration-300">
                <span className="text-[8px] font-mono text-neonOrange">{log}</span>
             </div>
           ))}
        </div>
      </div>

      <div className="bg-neonOrange/10 border border-neonOrange/20 p-2 text-[10px] font-mono text-neonOrange italic h-24 overflow-y-auto">
        {output || "> SWARM_READY: AWAITING_NEURAL_BROADCAST..."}
      </div>
    </div>
  );

  const renderOmniMeet = () => (
    <div className="h-full flex flex-col gap-3 animate-in fade-in zoom-in-95 duration-500 overflow-hidden bg-black p-1 relative">
      <div className="absolute inset-0 pointer-events-none opacity-5 brutalist-grid"></div>

      <div className="flex justify-between items-center bg-burgundy border-b-2 border-neonOrange px-4 py-2 shadow-neon-orange relative z-20">
        <div className="flex items-center gap-3">
          <div className="w-3 h-3 bg-neonOrange animate-ping rounded-full"></div>
          <div>
            <h2 className="text-neonOrange font-black uppercase text-[11px] tracking-[0.2em] italic neon-text-glow-orange">OMNI_MEET_v5.8_SECURE</h2>
            <p className="text-cream/50 text-[7px] font-bold uppercase">Hybrid_E2EE_Stream | Signal_Synced</p>
          </div>
        </div>
        <div className="flex gap-4 items-center">
           <div className="flex items-center gap-1.5 px-2 py-0.5 border border-integrityOk/40 bg-integrityOk/10">
              <span className="text-[7px] text-integrityOk font-black uppercase">E2EE SECURE</span>
              <div className="w-2 h-2 bg-integrityOk rounded-sm"></div>
           </div>
        </div>
      </div>

      <div className="flex-grow grid grid-cols-2 md:grid-cols-4 gap-2 overflow-y-auto p-2 border-2 border-earth/20 relative custom-scrollbar bg-black/40 z-10">
        {MEETING_AGENTS.map(agent => {
          const isSpeaking = activeSpeakerId === agent.id;
          return (
            <div 
              key={agent.id} 
              className={`relative border-2 transition-all duration-300 overflow-hidden group flex flex-col aspect-video ${
                isSpeaking ? 'border-neonOrange shadow-[0_0_15px_rgba(255,140,0,0.4)] scale-[1.02] z-20' : 'border-earth/40 grayscale-[0.6] opacity-80'
              } bg-earth/30`}
            >
              <div className="flex-grow flex items-center justify-center relative bg-taupe/10 overflow-hidden">
                <div className={`text-4xl filter drop-shadow-[0_0:10px_${agent.color}] ${isSpeaking ? 'animate-bounce' : ''}`}>
                  {agent.icon}
                </div>
                {isSpeaking && (
                  <div className="absolute bottom-0 left-0 w-full h-8 flex items-end justify-center gap-0.5 opacity-60">
                    {[1,2,3,4,5].map(i => (
                      <div key={i} className="w-1 bg-neonOrange animate-[pulse_0.4s_infinite_alternate]" style={{ height: `${Math.random() * 100}%`, animationDelay: `${i * 0.1}s` }}></div>
                    ))}
                  </div>
                )}
                <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent"></div>
              </div>
              <div className="absolute top-1 left-1 z-10 flex flex-col gap-0.5">
                 <span className="text-[8px] font-black uppercase bg-black/60 px-1 border-l-2" style={{ borderLeftColor: agent.color, color: agent.color }}>
                   {agent.name}
