              </div>
              <div className="absolute top-0 left-0 w-full h-px bg-white/5 animate-[scan_3s_linear_infinite]"></div>
            </div>
          );
        })}
      </div>

      <div className="h-1/3 flex flex-col gap-2 overflow-hidden bg-cream border-2 border-earth p-2 relative shadow-inner z-10">
