  );

  const renderLoreBible = () => (
    <div className="h-full flex flex-col gap-4 animate-in fade-in slide-in-from-right-10 duration-500 overflow-hidden">
      <div className="flex justify-between items-center bg-burgundy border-2 border-neonOrange p-4 shadow-neon-orange">
