          <p className="text-cream/60 text-[8px] font-bold uppercase mt-1">Archive: SWARM_CORE | Protocol: SIGMA_VAULT</p>
        </div>
      </div>

      <div className="flex-grow flex gap-4 overflow-hidden">
        <div className="w-1/3 flex flex-col gap-2 overflow-y-auto custom-scrollbar bg-earth p-2 border-2 border-burgundy">
