export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `CONFERENCE_PROMPT: "${prompt}"\nPARTICIPANTS: ${agents.map(a => a.name).join(", ")}\n\n`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\n[NEURAL_SYNC_START] NOW RESPONDING: ${agent.name} (${agent.role})`,
        config: {
          systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent),
          temperature: 0.8,
        },
      });

      const text = response.text || "NO_DATA_STREAM";

      // We simulate TTS for founding members or important agents
      let audioData;
      if (agent.type === 'FOUNDING_MEMBER' || agent.type === 'IDE_KERNEL' || agent.type === 'SWARM_DAEMON') {
         audioData = await generateTTS(text, agent.name === 'CLAUDE:BLADE' ? 'Puck' : 'Kore');
      }

      messages.push({
        agentId: agent.id,
        text: text,
        timestamp: new Date().toLocaleTimeString(),
        audioData
      });

      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (error: any) {
      messages.push({
        agentId: agent.id,
        text: `CRITICAL_IO_FAULT: ${error.message}`,
        timestamp: new Date().toLocaleTimeString()
      });
    }
  }

  return messages;
};

