  const [discoveredAssets, setDiscoveredAssets] = useState<MotherBrainAsset[]>([]);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120, contrast: 140, saturation: 20, grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0, scanlineWeight: 0.25, flickerSpeed: 0.1, enableSway: true,
    chromaticAberration: true, theme: 'cream', moltMode: true, touchOptimization: false,
    hardwareProfile: 'BALANCED', audioActive: true, showSwarmTopology: false
  });

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: 'cream' | 'void' | 'budowski-dark') => {
    setIsMolting(true);
    setTimeout(() => {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
      setTimeout(() => setIsMolting(false), 400);
    }, 300);
  }, []);

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    triggerHandshake();
    setIsLoading(true);

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        const msgs = await generateMeetingContent(customPrompt || "Discuss Smart Filing Strategy", MEETING_AGENTS);
        setMeetingMessages(msgs);
      } else {
        const result = await generateContent(selectedFeature, selectedAsset?.code || GD_SCRIPT_CODE, customPrompt);
        setOutput(result);

        if (selectedFeature === Feature.DRIVE_FILE_SEARCH && result.toLowerCase().includes('enterpriseomni')) {
           const found: MotherBrainAsset = {
              id: 'omni-mech-schematic',
              name: 'enterpriseomni.gd',
              type: 'script',
              path: '/synced/drive/enterpriseomni.gd',
              code: result
           };
           setDiscoveredAssets(prev => [found, ...prev]);
           setSelectedAsset(found);
           setActiveTab('REFS');
        }
      }
    } catch (err: any) {
      setOutput(`SYNC_FAULT: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  }, [selectedFeature, selectedAsset]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', uiSettings.theme);
  }, [uiSettings.theme]);

  const combinedAssets = [...discoveredAssets, ...MOTHER_BRAIN_ASSETS];

  return (
    <div className={`h-full flex flex-col p-4 md:p-6 gap-4 bg-cream text-earth overflow-hidden ${isGlitching ? 'fusion-glitch' : ''} ${uiSettings.enableSway && !isLoading ? 'tv-glitch-active' : 'no-sway'}`}>
      {isMolting && <div className="molting-shred"></div>}
      <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} />

      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2 relative">
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-earth flex items-center justify-center border-2 border-burgundy relative">
             <span className="text-neonOrange text-3xl font-black italic">&lt;V&gt;</span>
             <NeonParticles trigger={particleTrigger} />
          </div>
          <div>
            <h1 className="text-2xl font-black uppercase tracking-tighter">VCN-6.0_SWARM_COMM</h1>
            <p className="text-[9px] font-black uppercase text-earth/60">BAUD: <span className="text-integrityOk">10.2 GBps</span> | SMART_FILER_ACTIVE</p>
          </div>
        </div>
        <div className="flex gap-4">
           <button onClick={() => setIsUISettingsOpen(true)} className="text-[10px] font-black uppercase underline decoration-neonOrange/40">UI_CONFIG</button>
           <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-12 gap-6 overflow-hidden">
        <div className="col-span-3 flex flex-col gap-4 overflow-hidden">
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth bg-taupe/5">
            <div className="flex border-b border-earth text-[8px] font-black uppercase">
               <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream' : ''}`}>Strata</button>
               <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream' : ''}`}>Nodes</button>
            </div>
            <div className="flex-grow overflow-hidden p-1">
               {activeTab === 'REFS' ? (
                 <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={true} profile={uiSettings.hardwareProfile} assets={combinedAssets} />
               ) : (
                 <IntegrationHub />
               )}
            </div>
          </div>
        </div>

        <div className="col-span-6 flex flex-col gap-4 overflow-hidden">
          <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} />
        </div>

        <div className="col-span-3 overflow-hidden">
          <ControlPanel features={FEATURES} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} />
        </div>
      </main>
    </div>
  );
};

