    if (featureId === Feature.MASTER_SYNC_ORCHESTRATION) return renderSyncMonitor();
    if (featureId === Feature.SWARM_ORCHESTRATION) return renderSwarmMonitor();
    if (featureId === Feature.AI_GROUP_MEETING || featureId === Feature.OMNI_MEET_HUB) return renderOmniMeet();
