        <div className="text-[8px] font-mono text-neonOrange/60">EPISODE: 4096 | LOSS: 0.0012</div>
      </div>
      <div className="flex-grow relative z-10">
         <svg className="w-full h-full opacity-60">
            {[1,2,3,4,5].map(i => [1,2,3,4,5].map(j => (
              <circle key={`${i}-${j}`} cx={`${i*20}%`} cy={`${j*20}%`} r="3" fill="var(--accent-primary)" className="animate-pulse" />
