            <path d="M 20% 20% L 40% 60% L 80% 20% L 60% 80% Z" fill="none" stroke="var(--accent-primary)" strokeWidth="0.5" strokeDasharray="5 5" className="animate-[dash_10s_linear_infinite]" />
