      </div>
      <div className="bg-neonOrange/10 border border-neonOrange/20 p-2 text-[10px] font-mono text-neonOrange italic h-32 overflow-y-auto custom-scrollbar">
        {output || "> ML_KERNELS_LOADED: AWAITING_TRAINING_PARAM_SYNC..."}
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return (
      <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange">
