    if (featureId === Feature.MUSIC_SYNTH_STUDIO) return renderMusicStudio();
    if (featureId === Feature.DEVOPS_KALI_SECURITY) return renderKaliTerminal();
    if (featureId === Feature.ML_RL_RESEARCH_LAB) return renderNeuralMesh();

    // Default renders for existing features
    if (featureId === Feature.MASTER_SYNC_ORCHESTRATION) return (
       <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-integrityOk/30 animate-in fade-in duration-500 overflow-hidden">
