  const base = `
    You are ${agent ? agent.name : context.persona.identity}, a fused member of the Infinite Studio Collective.
    ${agent ? `ROLE: ${agent.role}. BIO: ${agent.bio}.` : `Expertise: ${context.persona.fused_expertise.join(', ')}.`}

