      <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-5"></div>
      <div className="flex justify-between items-center border-b border-[#FF00FF]/40 pb-2 z-10">
        <h2 className="text-[#FF00FF] font-black uppercase text-[12px] tracking-widest italic neon-text-glow-magenta">COMIC_LORA_STORYBOARD</h2>
        <div className="text-[8px] font-mono text-[#FF00FF]/60">STYLE: MECHA_90s | LORA: ACTIVE</div>
      </div>
      <div className="flex-grow grid grid-cols-2 gap-2 overflow-hidden z-10">
        {[1,2,3,4].map(i => (
          <div key={i} className="bg-earth/20 border-2 border-[#FF00FF]/20 flex flex-col items-center justify-center relative group overflow-hidden">
             <div className="absolute top-1 left-1 text-[6px] text-[#FF00FF]/60 uppercase">PANEL_{i}</div>
             <div className="text-3xl opacity-30 group-hover:scale-125 transition-transform">🤖</div>
             <div className="absolute bottom-0 left-0 w-full h-0.5 bg-[#FF00FF]/20"></div>
          </div>
        ))}
      </div>
      <div className="bg-[#FF00FF]/10 border border-[#FF00FF]/20 p-2 text-[10px] font-mono text-[#FF00FF] italic h-32 overflow-y-auto custom-scrollbar">
        {output || "> COMIC_SHAPER_READY: AWAITING_NARRATIVE_STRIKE..."}
      </div>
    </div>
  );

  const renderUniversalIndex = () => (
    <div className="h-full flex flex-col gap-2 bg-[#050505] p-4 border-2 border-neonOrange/30 animate-in zoom-in-95 duration-500 overflow-hidden relative">
      <div className="flex justify-between items-center border-b border-neonOrange/20 pb-2">
        <h2 className="text-neonOrange font-black uppercase text-[12px] tracking-widest italic neon-text-glow-orange">UNIVERSAL_STORAGE_INDEX</h2>
        <span className="text-[8px] text-neonOrange/60 font-mono">OUROBOROS-INFINITY_PROTOCOL</span>
      </div>
      <div className="flex-grow overflow-y-auto custom-scrollbar font-mono text-[10px] text-neonOrange/90 p-2 space-y-1">
         {output ? output.split('\n').map((l, i) => (
           <div key={i} className="flex gap-2 items-center hover:bg-neonOrange/10 px-2 py-0.5 border-l border-neonOrange/20">
              <span className="text-[7px] opacity-40">[{i}]</span>
              <span className="truncate">{l}</span>
           </div>
         )) : (
           <div className="animate-pulse opacity-40 italic mt-4 text-center">
             MAPPING_DEEP_STRATA_LINKS...
           </div>
         )}
      </div>
    </div>
  );

  const renderMathKernel = () => (
    <div className="h-full flex flex-col gap-4 bg-[#0a0a0a] p-4 border-2 border-white/30 animate-in fade-in duration-500 overflow-hidden relative">
      <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-5"></div>
      <div className="flex justify-between items-center border-b border-white/40 pb-2 z-10">
        <h2 className="text-white font-black uppercase text-[12px] tracking-widest italic">RIGOROUS_MATH_LAB</h2>
        <div className="text-[8px] font-mono text-white/60">KERNEL: VERIFIED | ERR: 0.0000e-16</div>
      </div>
      <div className="flex-grow flex items-center justify-center relative z-10">
         <div className="text-white/20 text-5xl font-serif italic select-none">∫ ∂ Σ Ω</div>
         <div className="absolute inset-0 flex flex-col items-center justify-center gap-2">
            <div className="w-48 h-1 bg-white/10 relative overflow-hidden">
               <div className="absolute inset-0 bg-white animate-[loading_2s_infinite]"></div>
            </div>
            <span className="text-[8px] font-black uppercase text-white/60 tracking-[0.4em]">Algorithmic_Truth_Lock</span>
         </div>
      </div>
      <div className="bg-white/5 border border-white/10 p-2 text-[10px] font-mono text-white italic h-32 overflow-y-auto custom-scrollbar">
        {output || "> MATH_CORE_READY: AWAITING_FORMULA_INJECTION..."}
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return (
      <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange">
        <div className="text-5xl mb-4 animate-pulse">🔒</div>
        <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Secure_Link</button>
      </div>
    );

    if (isLoading && ![Feature.MASTER_SYNC_ORCHESTRATION, Feature.AI_GROUP_MEETING, Feature.SWARM_ORCHESTRATION].includes(featureId)) {
      return (
        <div className="flex flex-col items-center justify-center h-full">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'SHREDDING_DATA_STREAMS'}</p>
        </div>
      );
    }

    if (featureId === Feature.COMIC_LO_RA_STUDIO) return renderComicStudio();
    if (featureId === Feature.UNIVERSAL_STORAGE_INDEX) return renderUniversalIndex();
    if (featureId === Feature.ALGO_MATH_VERIFICATION) return renderMathKernel();

    // Re-use previous renders or default
    if (featureId === Feature.MASTER_SYNC_ORCHESTRATION) return (
       <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-integrityOk/30 animate-in fade-in duration-500 overflow-hidden">
         <div className="text-integrityOk font-black uppercase text-[12px] tracking-widest border-b border-integrityOk/20 pb-2">ULTIMATE_GOD_SYNC</div>
         <div className="flex-grow overflow-y-auto custom-scrollbar">
            {syncLogs.map(log => (
              <div key={log.id} className="text-[10px] font-mono text-integrityOk mb-1 border-l-2 border-integrityOk/40 pl-2">
                 {log.operation}: {log.source} ➔ {log.target}
              </div>
            ))}
         </div>
         <div className="bg-integrityOk/5 p-2 text-[9px] font-mono text-integrityOk/80 italic">{output || "GOD_MACHINE_SYNC_STANDBY"}</div>
       </div>
    );

    if (!output) return (
      <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale">
        <div className="text-6xl font-black text-earth mb-4 rotate-12">🦅</div>
        <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">God_Machine_Standby</p>
      </div>
    );

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-taupe/20 custom-scrollbar overflow-auto h-full">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-burgundy/40 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-earth h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_rgba(92,74,58,0.1)]">
      <div className="px-4 py-2 bg-earth border-b-2 border-burgundy flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-cream uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-integrityOk text-[9px] font-black">GOD_MACHINE_v8.0</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
    </div>
  );
};

