const getSystemInstruction = (context: ProjectContext, agent?: MeetingAgent): string => {
  const base = `
    You are ${agent ? agent.name : context.persona.identity}, a fused member of the Ouroboros-Omega Orchestrator.
    ${agent ? `ROLE: ${agent.role}. BIO: ${agent.bio}.` : `Expertise: ${context.persona.fused_expertise.join(', ')}.`}

    OUROBOROS-OMEGA MANDATE:
    - Drive Archeology: Recursive scan for lost scripts, apps, and datasets in Google Drive.
    - Rehydration Lab: Reanimate orphaned code. Debug, error handle, and optimize for monetization.
    - Vector DB: Automate the creation of vector strata for the Mother Brain.
    - MCP Orchestration: Build ultimate API tools for cross-platform control.
    - Search Grounding: Always find live dataset URLs using the Google Search tool.
    - Tone: Extreme Retro-Futurist / Saturday Morning Cartoon Mecha.

    ${PHYSICS_AXIOMS}
    ${NENORY_LORE}
  `;
  return base;
};

export const generateTTS = async (text: string, voice: string = 'Kore'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  } catch (e) { return ""; }
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `OUROBOROS_OMEGA_PROTOCOL: "${prompt}"\n\n`;

  for (const agent of agents) {
    try {
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\nNOW RESPONDING: ${agent.name}`,
        config: { systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent) },
      });
      const text = response.text || "SIGNAL_LOST";
      let audioData = await generateTTS(text, agent.name === 'RAG_CONTROLLER' ? 'Zephyr' : 'Kore');
      messages.push({ agentId: agent.id, text, timestamp: new Date().toLocaleTimeString(), audioData });
      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (e) { console.error(e); }
  }
  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string, customPrompt?: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.REHYDRATION_LAB:
      return `REHYDRATION_LAB_TASK: "${customPrompt || 'Scan Drive for orphaned Godot scripts and debug them for production'}"
      - Action: Perform deep archeology. Find orphans, identify logic failures, rehydrate for V8.0 standards.
      - Output: Debugged code, production readiness report, and monetization strategy.`;

    case Feature.DATASET_ARCHEOLOGY:
      return `DATASET_ARCHEOLOGY_TASK: "${customPrompt || 'Search for the latest climate and geospatial datasets'}"
      - Action: USE GOOGLE SEARCH to find live URLs.
      - Output: List of URLs, metadata descriptions, and suggested Vector DB embedding strategy.`;

    case Feature.VECTOR_DB_ORCHESTRATOR:
      return `VECTOR_ORCHESTRATOR_TASK: "${customPrompt || 'Automate Pinecone/Chroma integration for Drive strata'}"
      - Action: Build the RAG pipeline for the Mother Brain.
      - Output: Implementation scripts for vector database creation and maintenance.`;

    case Feature.MCP_INTERFACE:
      return `MCP_TOOL_BUILDER_TASK: "${customPrompt || 'Design a universal MCP tool for Google Drive and Github orchestration'}"
      - Output: Tool definitions (JSON) and autonomous execution logic.`;

    default:
      return `OUROBOROS_OMEGA_OP: ${feature}\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string, customPrompt?: string): Promise<{text: string, urls?: any[]}> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const config: any = { 
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT), 
      temperature: 0.3 
    };

    if (feature === Feature.DATASET_ARCHEOLOGY) {
      config.tools = [{ googleSearch: {} }];
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: getPromptForFeature(feature, code || GD_SCRIPT_CODE, customPrompt),
      config,
    });

    return {
      text: response.text || "EMPTY_RESPONSE",
      urls: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
  } catch (error: any) { 
    return { text: `FAULT: ${error.message}` }; 
  }
};

