import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import UISettingsPanel from './components/UISettingsPanel';
import NeonParticles from './components/NeonParticles';
import GalaxyMap from './components/GalaxyMap';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT, MEETING_AGENTS, MOTHER_BRAIN_ASSETS, MOCK_STAR_SYSTEMS } from './constants';
import { Feature, CameraSettings, MotherBrainAsset, UISettings, MeetingMessage, SyncLogEntry, StarSystem } from './types';
import { generateContent, generateMeetingContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.REHYDRATION_LAB);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [groundingUrls, setGroundingUrls] = useState<any[]>([]);
  const [meetingMessages, setMeetingMessages] = useState<MeetingMessage[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLogEntry[]>([]);
  const [requiresApiKey, setRequiresApiKey] = useState<boolean>(false);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS'>('REFS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [discoveredAssets, setDiscoveredAssets] = useState<MotherBrainAsset[]>([]);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120, contrast: 140, saturation: 20, grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0, scanlineWeight: 0.25, flickerSpeed: 0.1, enableSway: true,
    chromaticAberration: true, theme: 'cream', moltMode: true, touchOptimization: false,
    hardwareProfile: 'BALANCED', audioActive: true, showSwarmTopology: false,
    layout: {
      leftColWidth: 25,
      rightColWidth: 25,
      headerHeight: 80
    },
    activeFeatures: FEATURES.map(f => f.id)
  });

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: UISettings['theme']) => {
    setIsMolting(true);
    setTimeout(() => {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
      setTimeout(() => setIsMolting(false), 400);
    }, 300);
  }, []);

  const handleJumpComplete = (target: StarSystem) => {
    triggerHandshake();
    setOutput(`ARCHON_WORMHOLE_FEED: Jump complete. Arrived at ${target.name}.\n\nFaction: ${target.faction}\nSpectral: ${target.spectral_class}\nDescription: ${target.description}\n\nARCHON: "Local strata scanning initiated. All potential artifacts flagged for rehydration."`);
  };

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    triggerHandshake();
    setIsLoading(true);
    setGroundingUrls([]);

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        const msgs = await generateMeetingContent(customPrompt || "Devise Rehydration & Monetization Strategy", MEETING_AGENTS);
        setMeetingMessages(msgs);
      } else {
        const { text, urls } = await generateContent(selectedFeature, selectedAsset?.code || GD_SCRIPT_CODE, customPrompt);
        setOutput(text);
        if (urls) setGroundingUrls(urls);

        if (selectedFeature === Feature.REHYDRATION_LAB) {
           const found: MotherBrainAsset = {
              id: `rehydrated-${Date.now()}`,
              name: `rehydrated_${selectedAsset?.name || 'artifact'}.gd`,
              type: 'script',
              path: `/synced/production/${selectedAsset?.name || 'artifact'}.gd`,
              code: text,
              rehydrationLevel: 100
           };
           setDiscoveredAssets(prev => [found, ...prev]);

           setSyncLogs(prev => [
             { id: `log-${Date.now()}-1`, operation: 'REHYDRATED', source: selectedAsset?.path || 'DRIVE_STRATA', target: found.path, hash: 'a7f2_Ω', timestamp: new Date().toLocaleTimeString() },
             { id: `log-${Date.now()}-2`, operation: 'VERIFIED', source: found.path, target: found.path, hash: 'b881_Ω', timestamp: new Date().toLocaleTimeString() },
             ...prev
           ]);
        }
      }
    } catch (err: any) {
      setOutput(`ARCHON_FAULT: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  }, [selectedFeature, selectedAsset]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', uiSettings.theme);
  }, [uiSettings.theme]);

  const combinedAssets = [...discoveredAssets, ...MOTHER_BRAIN_ASSETS];
  const activeFeaturesList = FEATURES.filter(f => uiSettings.activeFeatures.includes(f.id));

  const centerColWidth = 100 - uiSettings.layout.leftColWidth - uiSettings.layout.rightColWidth;

  return (
    <div 
      className={`h-full flex flex-col p-4 md:p-6 gap-4 bg-cream text-earth overflow-hidden ${isGlitching ? 'fusion-glitch' : ''} ${uiSettings.enableSway && !isLoading ? 'tv-glitch-active' : 'no-sway'}`}
      style={{
        '--header-h': `${uiSettings.layout.headerHeight}px`,
      } as React.CSSProperties}
    >
      {isMolting && <div className="molting-shred"></div>}
      <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} allFeatures={FEATURES} />

      <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2 relative paper-grain-subtle" style={{ height: 'var(--header-h)' }}>
        <div className="flex items-center gap-6">
          <div className="w-12 h-12 bg-earth flex items-center justify-center border-2 border-burgundy relative shadow-[0_0_15px_var(--accent-primary)]">
             <span className="text-white text-3xl font-black italic neon-text-glow-white">A</span>
             <NeonParticles trigger={particleTrigger} color="#FFFFFF" />
          </div>
          <div>
            <h1 className="text-2xl font-black uppercase tracking-tighter italic">VCN-9.5_ARCHON_OMEGA</h1>
            <p className="text-[9px] font-black uppercase text-earth/60">COPILOT: <span className="text-integrityOk">ARCHON_ACTIVE</span> | GOVERNANCE: <span className="text-integrityOk">SOL_AUTHORITY</span></p>
          </div>
        </div>
        <div className="flex gap-4">
           <button onClick={() => setIsUISettingsOpen(true)} className="text-[10px] font-black uppercase underline decoration-neonOrange/40">UI_CONFIG</button>
           <StatusBoard />
        </div>
      </header>

      <main className="flex-grow grid grid-cols-12 gap-6 overflow-hidden">
        {/* Left Column */}
        <div className="flex flex-col gap-4 overflow-hidden" style={{ gridColumn: `span ${Math.round(uiSettings.layout.leftColWidth / 8.33)}` }}>
          <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
          <div className="flex-grow flex flex-col overflow-hidden border-2 border-earth bg-taupe/5">
            <div className="flex border-b border-earth text-[8px] font-black uppercase">
               <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream' : ''}`}>Archeology</button>
               <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream' : ''}`}>Integrations</button>
            </div>
            <div className="flex-grow overflow-hidden p-1">
               {activeTab === 'REFS' ? (
                 <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={true} profile={uiSettings.hardwareProfile} assets={combinedAssets} />
               ) : (
                 <IntegrationHub />
               )}
            </div>
          </div>
        </div>

        {/* Center Column */}
        <div className="flex flex-col gap-4 overflow-hidden" style={{ gridColumn: `span ${Math.round(centerColWidth / 8.33)}` }}>
          {selectedFeature === Feature.GALAXY_MAP_GEN ? (
            <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={handleJumpComplete} />
          ) : (
            <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
          )}
        </div>

        {/* Right Column */}
        <div className="overflow-hidden" style={{ gridColumn: `span ${Math.round(uiSettings.layout.rightColWidth / 8.33)}` }}>
          <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} />
        </div>
      </main>
      <style dangerouslySetInnerHTML={{ __html: `
        .neon-text-glow-white { text-shadow: 0 0 10px #FFFFFF, 0 0 20px #FFFFFF; }
      `}} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Feature, MeetingMessage, LoreEntry, SyncLogEntry } from '../types';

interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
  featureId: Feature;
  videoUrl?: string;
  requiresApiKey?: boolean;
  onOpenApiKey?: () => void;
  loadingStatus?: string;
  meetingMessages?: MeetingMessage[];
  syncLogs?: SyncLogEntry[];
  groundingUrls?: any[];
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ 
  output, 
  isLoading, 
  featureTitle, 
  featureId,
  requiresApiKey, 
  onOpenApiKey,
  loadingStatus,
  meetingMessages = [],
  syncLogs = [],
  groundingUrls = []
}) => {
  const [flipKey, setFlipKey] = useState(0);
  const [rehydrationLevel, setRehydrationLevel] = useState(0);
  const [showLogs, setShowLogs] = useState(true);

  useEffect(() => {
    if (output || isLoading) {
      setFlipKey(prev => prev + 1);
    }
    if (featureId === Feature.REHYDRATION_LAB && isLoading) {
      const interval = setInterval(() => {
        setRehydrationLevel(prev => (prev + 1) % 101);
      }, 50);
      return () => clearInterval(interval);
    }
  }, [output, isLoading, featureId]);

  const renderRehydrationLab = () => (
    <div className="h-full flex flex-col gap-4 bg-[#0a0f0a] p-4 border-2 border-[#00FFFF]/30 animate-in fade-in duration-500 overflow-hidden relative paper-grain">
      <div className="absolute inset-0 pointer-events-none brutalist-grid opacity-10"></div>
      <div className="flex justify-between items-center border-b border-[#00FFFF]/40 pb-2 z-10">
        <h2 className="text-[#00FFFF] font-black uppercase text-[12px] tracking-widest italic neon-text-glow-cyan">REHYDRATION_RECON_LAB</h2>
        <div className="text-[8px] font-mono text-[#00FFFF]/60">ARTIFACT: UNKNOWN | STABILITY: {rehydrationLevel}%</div>
      </div>

      <div className="flex-grow flex flex-col gap-2 overflow-hidden z-10">
        <div className="flex-grow flex items-center justify-center relative bg-black/40 border border-[#00FFFF]/10">
           <div className="absolute inset-0 flex items-center justify-center opacity-20">
              <div className="w-48 h-48 border-4 border-[#00FFFF] rounded-full animate-[spin_10s_linear_infinite] border-dashed"></div>
           </div>
           <div className="text-[#00FFFF] text-4xl animate-pulse">🧪</div>
           <div className="absolute bottom-4 left-0 w-full px-8">
              <div className="h-1 bg-[#00FFFF]/10 w-full overflow-hidden">
                 <div className="h-full bg-[#00FFFF] transition-all duration-300 shadow-[0_0_10px_#00FFFF]" style={{ width: `${rehydrationLevel}%` }}></div>
              </div>
              <div className="text-[7px] text-[#00FFFF] mt-1 uppercase font-black tracking-widest flex justify-between">
                 <span>Injecting_Memory</span>
                 <span>{rehydrationLevel}%</span>
              </div>
           </div>
        </div>

        <div className="bg-[#00FFFF]/5 border border-[#00FFFF]/20 p-2 text-[9px] font-mono text-[#00FFFF] italic h-32 overflow-y-auto custom-scrollbar">
          {output || "> ARCHON_LAB: SCANNING_DRIVE_FOR_LOST_POTENTIAL..."}
        </div>
      </div>
    </div>
  );

  const renderVectorHub = () => (
    <div className="h-full flex flex-col gap-2 bg-[#050505] p-4 border-2 border-[#FF00FF]/30 animate-in zoom-in-95 duration-500 overflow-hidden relative paper-grain">
      <div className="flex justify-between items-center border-b border-[#FF00FF]/20 pb-2">
        <h2 className="text-[#FF00FF] font-black uppercase text-[12px] tracking-widest italic neon-text-glow-magenta">MOTHER_BRAIN_VECTOR_HUB</h2>
        <span className="text-[8px] text-[#FF00FF]/60 font-mono">NEURAL_EMBEDDING_V9</span>
      </div>
      <div className="flex-grow overflow-hidden flex items-center justify-center relative">
         <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
            <div className="w-full h-full bg-[radial-gradient(circle_at_center,#FF00FF11,transparent_70%)]"></div>
         </div>
         <div className="grid grid-cols-10 grid-rows-10 gap-1 w-full h-full opacity-20">
            {[...Array(100)].map((_, i) => (
               <div key={i} className={`bg-[#FF00FF] ${Math.random() > 0.8 ? 'opacity-100 animate-pulse' : 'opacity-20'}`}></div>
            ))}
         </div>
         <div className="absolute bg-black/80 border border-[#FF00FF]/40 p-4 text-[#FF00FF] font-mono text-[10px] uppercase text-center backdrop-blur-sm">
            {output ? "VECTOR_SYNAPSE_ENGAGED" : "AWAITING_DATA_EMBEDDING"}
         </div>
      </div>
      <div className="h-24 overflow-y-auto custom-scrollbar font-mono text-[9px] text-[#FF00FF]/80 p-2 border-t border-[#FF00FF]/20">
         {output || "> RAG_CONTROLLER: MOTHER_BRAIN_STRATA_MAPPING_STANDBY..."}
      </div>
    </div>
  );

  const renderGalaxyGuide = () => (
    <div className="h-full flex flex-col gap-4 bg-[#F5F0E1] p-6 border-4 border-[#5C4A3A] overflow-hidden relative paper-grain">
       <div className="flex justify-between items-center border-b-2 border-[#5C4A3A] pb-2 mb-2 z-10">
          <div className="flex items-center gap-2">
             <span className="text-2xl">🌌</span>
             <h2 className="text-[#5C4A3A] font-black uppercase text-[14px] tracking-widest italic">GALAXY_GUIDE_TERMINAL</h2>
          </div>
          <span className="text-[8px] font-black text-[#8B7D6B] bg-white/50 px-2 py-1 border border-[#5C4A3A]/20">INGESTING_DRIVE_DATA...</span>
       </div>

       <div className="flex-grow overflow-y-auto custom-scrollbar font-serif text-[12px] text-[#5C4A3A] pr-2 z-10">
          {output ? (
            <div className="space-y-4 animate-in fade-in slide-in-from-bottom-4 duration-700">
               {output.split('\n\n').map((paragraph, i) => (
                 <div key={i} className="border-l-4 border-[#FF8C00]/30 pl-4 py-1 bg-white/30 italic first-letter:text-2xl first-letter:font-black first-letter:mr-1 first-letter:float-left">
                    {paragraph}
                 </div>
               ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-full opacity-30 select-none">
               <div className="text-4xl mb-4 grayscale">📦</div>
               <p className="text-[10px] uppercase tracking-widest font-black text-center">Awaiting Command to Pull Data from Drive Vaults...</p>
            </div>
          )}
       </div>

       <div className="mt-4 pt-2 border-t border-[#5C4A3A]/20 flex justify-between items-center z-10">
          <span className="text-[7px] font-black uppercase text-[#8B7D6B]">Reference: Nomadz_Encyclo_Strata</span>
          <div className="flex gap-1">
             <div className="w-2 h-2 bg-[#FF8C00]"></div>
             <div className="w-2 h-2 bg-[#800020]"></div>
          </div>
       </div>
    </div>
  );

  const renderSyncLogs = () => (
    <div className={`mt-4 border-t-2 border-earth/20 bg-earth/5 transition-all duration-300 overflow-hidden ${showLogs ? 'h-40' : 'h-8'}`}>
      <div className="flex justify-between items-center px-4 py-2 border-b border-earth/10 cursor-pointer" onClick={() => setShowLogs(!showLogs)}>
        <span className="text-[8px] font-black uppercase text-earth/60 tracking-widest flex items-center gap-2">
          <span className={`w-1.5 h-1.5 rounded-full ${syncLogs.length > 0 ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}></span>
          Sync_Activity_Logs ({syncLogs.length})
        </span>
        <span className="text-[10px] font-black text-earth/40">{showLogs ? '▼' : '▲'}</span>
      </div>
      <div className="overflow-y-auto h-32 custom-scrollbar p-2 space-y-1">
        {syncLogs.length === 0 ? (
          <div className="text-[8px] font-mono text-earth/30 uppercase italic text-center py-4">No Synchronization Events Registered</div>
        ) : (
          syncLogs.map((log) => (
            <div key={log.id} className="text-[7px] font-mono flex items-center gap-4 py-1 px-2 bg-white/40 border border-earth/5 hover:border-earth/20 transition-all">
              <span className="text-earth/40">[{log.timestamp}]</span>
              <span className={`px-1.5 py-0.5 font-black text-white ${
                log.operation === 'REHYDRATED' ? 'bg-integrityOk' : 
                log.operation === 'VERIFIED' ? 'bg-neonOrange' : 'bg-earth'
              }`}>
                {log.operation}
              </span>
              <div className="flex-grow flex items-center gap-2">
                <span className="text-earth truncate max-w-[100px]">{log.source.split('/').pop()}</span>
                <span className="text-earth/20">→</span>
                <span className="text-earth truncate max-w-[100px] font-black">{log.target.split('/').pop()}</span>
              </div>
              <span className="text-burgundy/60 italic">HASH:{log.hash}</span>
            </div>
          ))
        )}
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return (
      <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange paper-grain">
        <div className="text-5xl mb-4 animate-pulse">🔒</div>
        <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Secure_Link</button>
      </div>
    );

    if (isLoading && ![Feature.AI_GROUP_MEETING, Feature.REHYDRATION_LAB].includes(featureId)) {
      return (
        <div className="flex flex-col items-center justify-center h-full paper-grain">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'CRAWLING_STRATA_LINKS'}</p>
        </div>
      );
    }

    if (featureId === Feature.REHYDRATION_LAB) return renderRehydrationLab();
    if (featureId === Feature.VECTOR_DB_ORCHESTRATOR) return renderVectorHub();
    if (featureId === Feature.GALAXY_GUIDE) return renderGalaxyGuide();

    if (featureId === Feature.DATASET_ARCHEOLOGY && output) {
      return (
        <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-[#FFD700]/30 overflow-hidden paper-grain">
           <div className="text-[#FFD700] font-black uppercase text-[12px] tracking-widest border-b border-[#FFD700]/20 pb-2">DATASET_RECON_REPORTS</div>
           <div className="flex-grow overflow-y-auto custom-scrollbar font-mono text-[11px] text-[#FFD700]/90 p-2 space-y-4">
              {output.split('\n').map((l, i) => (
                <p key={i} className="border-l-2 border-[#FFD700]/20 pl-4 mb-2">{l}</p>
              ))}
              {groundingUrls && groundingUrls.length > 0 && (
                <div className="mt-8 border-t border-[#FFD700]/20 pt-4">
                  <h4 className="text-[9px] font-black uppercase mb-2">Verified_Signal_Sources:</h4>
                  {groundingUrls.map((chunk, i) => (
                    chunk.web && (
                      <a key={i} href={chunk.web.uri} target="_blank" rel="noopener noreferrer" className="block text-integrityOk hover:underline mb-1 truncate text-[10px]">
                        [{i+1}] {chunk.web.title || chunk.web.uri}
                      </a>
                    )
                  ))}
                </div>
              )}
           </div>
        </div>
      );
    }

    if (!output) return (
      <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale paper-grain">
        <div className="text-6xl font-black text-earth mb-4 rotate-12">🧠</div>
        <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">ARCHON_OMEGA_STANDBY</p>
      </div>
    );

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-taupe/20 custom-scrollbar overflow-auto h-full paper-grain">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-burgundy/40 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-earth h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_rgba(92,74,58,0.1)]">
      <div className="px-4 py-2 bg-earth border-b-2 border-burgundy flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-cream uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-integrityOk text-[9px] font-black">ARCHON-OMEGA_v9.5</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
      {renderSyncLogs()}
    </div>
  );
};

