import React, { useState, useEffect, useRef } from 'react';
import { Feature, MeetingMessage, LoreEntry, SyncLogEntry } from '../types';

interface OutputDisplayProps {
  output: string;
  isLoading: boolean;
  featureTitle: string;
  featureId: Feature;
  videoUrl?: string;
  requiresApiKey?: boolean;
  onOpenApiKey?: () => void;
  loadingStatus?: string;
  meetingMessages?: MeetingMessage[];
  syncLogs?: SyncLogEntry[];
  groundingUrls?: any[];
}

const OutputDisplay: React.FC<OutputDisplayProps> = ({ 
  output, 
  isLoading, 
  featureTitle, 
  featureId,
  requiresApiKey, 
  onOpenApiKey,
  loadingStatus,
  meetingMessages = [],
  syncLogs = [],
  groundingUrls = []
}) => {
  const [flipKey, setFlipKey] = useState(0);
  const [rehydrationLevel, setRehydrationLevel] = useState(0);
  const [showLogs, setShowLogs] = useState(true);
  const [cliInput, setCliInput] = useState('');
  const [cliHistory, setCliHistory] = useState<string[]>([]);

  useEffect(() => {
    if (output || isLoading) {
      setFlipKey(prev => prev + 1);
    }
    if (featureId === Feature.REHYDRATION_LAB && isLoading) {
      const interval = setInterval(() => {
        setRehydrationLevel(prev => (prev + 1) % 101);
      }, 50);
      return () => clearInterval(interval);
    }
  }, [output, isLoading, featureId]);

  const handleCliSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!cliInput.trim()) return;
    setCliHistory(prev => [...prev, `> ${cliInput}`, `ARCHON_SH: Command '${cliInput.split(' ')[0]}' executing in simulated kernel...`]);
    setCliInput('');
  };

  const renderCliWorkspace = () => (
    <div className="h-full flex flex-col bg-[#050505] p-4 border-2 border-[#FFFFFF]/20 animate-in fade-in duration-500 overflow-hidden relative paper-grain">
       <div className="flex justify-between items-center border-b border-[#FFFFFF]/10 pb-2 mb-4">
          <h2 className="text-[#FFFFFF] font-black uppercase text-[12px] tracking-widest italic">ARCHON_CLI_WORKSPACE</h2>
          <div className="flex gap-2 text-[7px] font-mono text-integrityOk">
             <span>PSH</span><span>PY</span><span>RS</span><span>LUA</span><span>CPP</span><span>JAVA</span>
          </div>
       </div>
       <div className="flex-grow overflow-y-auto custom-scrollbar font-mono text-[10px] text-[#00FF00] p-2 bg-black/40 mb-2 space-y-1">
          {cliHistory.map((line, i) => <div key={i}>{line}</div>)}
          {output && <div className="text-white mt-4">{output}</div>}
       </div>
       <form onSubmit={handleCliSubmit} className="flex gap-2 border-t border-[#FFFFFF]/10 pt-2">
          <span className="text-neonOrange font-black italic">ROOT@ARCHON:~#</span>
          <input 
             type="text" 
             value={cliInput}
             onChange={(e) => setCliInput(e.target.value)}
             className="bg-transparent border-none outline-none text-[#00FF00] flex-grow text-[10px] font-mono"
             placeholder="Enter command..."
             autoFocus
          />
       </form>
    </div>
  );

  const renderKaliSandbox = () => (
    <div className="h-full flex flex-col bg-[#110011] p-4 border-2 border-burgundy/50 animate-in fade-in duration-500 overflow-hidden relative paper-grain">
       <div className="absolute inset-0 brutalist-grid opacity-5 pointer-events-none"></div>
       <div className="flex justify-between items-center border-b border-burgundy/30 pb-2 mb-4 z-10">
          <h2 className="text-burgundy font-black uppercase text-[12px] tracking-widest italic neon-text-glow-burgundy">KALI_NETHUNTER_SANDBOX</h2>
          <span className="text-[8px] font-black text-integrityWarn bg-burgundy/10 px-2 animate-pulse">E2EE_ACTIVE</span>
       </div>
       <div className="flex-grow grid grid-cols-2 gap-4 z-10">
          <div className="bg-black/60 border border-burgundy/20 p-3 flex flex-col">
             <div className="text-[7px] font-black text-burgundy uppercase mb-2">Network_Recon_Live</div>
             <div className="flex-grow overflow-hidden relative opacity-40">
                <div className="absolute inset-0 flex items-center justify-center">
                   <div className="w-24 h-24 border border-burgundy rounded-full animate-ping"></div>
                </div>
                <div className="absolute top-2 left-2 text-[6px] text-integrityOk font-mono">SCANNING_SUBNET...</div>
             </div>
          </div>
          <div className="bg-black/60 border border-burgundy/20 p-3 font-mono text-[8px] text-integrityWarn flex flex-col overflow-y-auto custom-scrollbar">
             {output ? output : "> KALI_SENTRY: Awaiting instruction for security audit...\n\n- SHREDDER_V3: READY\n- WATCHDOG: ACTIVE\n- PEN_TEST: STANDBY"}
          </div>
       </div>
    </div>
  );

  const renderPhetLab = () => (
    <div className="h-full flex flex-col bg-[#e0e7ff] p-4 border-2 border-blue-600/30 animate-in zoom-in-95 duration-500 overflow-hidden relative paper-grain">
       <div className="flex justify-between items-center border-b border-blue-600/20 pb-2 mb-4">
          <h2 className="text-blue-900 font-black uppercase text-[12px] tracking-widest italic flex items-center gap-2">
             <span className="text-xl">🔬</span> PHET_SIM_BRIDGE
          </h2>
          <span className="text-[8px] font-black text-blue-900/60 uppercase tracking-widest">Physics_Engine_L4</span>
       </div>
       <div className="flex-grow flex flex-col items-center justify-center relative border border-blue-600/10 bg-white/40">
          <div className="absolute top-4 left-4 text-[9px] font-black text-blue-900 uppercase">SIM_BOOT: {isLoading ? 'INITIALIZING' : 'STABLE'}</div>
          <div className="w-64 h-64 border-2 border-blue-600/20 rounded-full relative animate-[spin_20s_linear_infinite]">
             <div className="absolute top-0 left-1/2 -translate-x-1/2 w-4 h-4 bg-blue-600 rounded-full shadow-lg"></div>
          </div>
          <div className="mt-8 text-blue-900 font-serif italic text-center px-12">
             {output || "Map an artifact from the Strata View to begin physical simulation analysis."}
          </div>
       </div>
    </div>
  );

  const renderSyncLogs = () => (
    <div className={`mt-4 border-t-2 border-earth/20 bg-earth/5 transition-all duration-300 overflow-hidden ${showLogs ? 'h-40' : 'h-8'}`}>
      <div className="flex justify-between items-center px-4 py-2 border-b border-earth/10 cursor-pointer" onClick={() => setShowLogs(!showLogs)}>
        <span className="text-[8px] font-black uppercase text-earth/60 tracking-widest flex items-center gap-2">
          <span className={`w-1.5 h-1.5 rounded-full ${syncLogs.length > 0 ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}></span>
          Sync_Activity_Logs ({syncLogs.length})
        </span>
        <span className="text-[10px] font-black text-earth/40">{showLogs ? '▼' : '▲'}</span>
      </div>
      <div className="overflow-y-auto h-32 custom-scrollbar p-2 space-y-1">
        {syncLogs.length === 0 ? (
          <div className="text-[8px] font-mono text-earth/30 uppercase italic text-center py-4">No Synchronization Events Registered</div>
        ) : (
          syncLogs.map((log) => (
            <div key={log.id} className="text-[7px] font-mono flex items-center gap-4 py-1 px-2 bg-white/40 border border-earth/5 hover:border-earth/20 transition-all">
              <span className="text-earth/40">[{log.timestamp}]</span>
              <span className={`px-1.5 py-0.5 font-black text-white ${
                log.operation === 'REHYDRATED' ? 'bg-integrityOk' : 
                log.operation === 'VERIFIED' ? 'bg-neonOrange' : 'bg-earth'
              }`}>
                {log.operation}
              </span>
              <div className="flex-grow flex items-center gap-2">
                <span className="text-earth truncate max-w-[100px]">{log.source.split('/').pop()}</span>
                <span className="text-earth/20">→</span>
                <span className="text-earth truncate max-w-[100px] font-black">{log.target.split('/').pop()}</span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return (
      <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange paper-grain">
        <div className="text-5xl mb-4 animate-pulse">🔒</div>
        <button onClick={onOpenApiKey} className="bg-neonOrange text-white font-black px-10 py-4 uppercase text-[11px] tracking-widest shadow-neon-orange">Establish_Secure_Link</button>
      </div>
    );

    if (isLoading && ![Feature.AI_GROUP_MEETING, Feature.REHYDRATION_LAB, Feature.CLI_WORKSPACE].includes(featureId)) {
      return (
        <div className="flex flex-col items-center justify-center h-full paper-grain">
          <div className="w-48 h-1 bg-taupe relative overflow-hidden mb-6">
            <div className="absolute inset-0 bg-neonOrange animate-[loading_1s_infinite]"></div>
          </div>
          <p className="text-[12px] font-black uppercase tracking-[0.5em] text-neonOrange animate-pulse">{loadingStatus || 'CRAWLING_STRATA_LINKS'}</p>
        </div>
      );
    }

    if (featureId === Feature.REHYDRATION_LAB) return renderRehydrationLab();
    if (featureId === Feature.VECTOR_DB_ORCHESTRATOR) return renderVectorHub();
    if (featureId === Feature.GALAXY_GUIDE) return renderGalaxyGuide();
    if (featureId === Feature.CLI_WORKSPACE) return renderCliWorkspace();
    if (featureId === Feature.KALI_SANDBOX) return renderKaliSandbox();
    if (featureId === Feature.PHET_LAB_SIM) return renderPhetLab();

    if (featureId === Feature.DATASET_ARCHEOLOGY && output) {
      return (
        <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-[#FFD700]/30 overflow-hidden paper-grain">
           <div className="text-[#FFD700] font-black uppercase text-[12px] tracking-widest border-b border-[#FFD700]/20 pb-2">DATASET_RECON_REPORTS</div>
           <div className="flex-grow overflow-y-auto custom-scrollbar font-mono text-[11px] text-[#FFD700]/90 p-2 space-y-4">
              {output.split('\n').map((l, i) => (
                <p key={i} className="border-l-2 border-[#FFD700]/20 pl-4 mb-2">{l}</p>
              ))}
              {groundingUrls && groundingUrls.length > 0 && (
                <div className="mt-8 border-t border-[#FFD700]/20 pt-4">
                  <h4 className="text-[9px] font-black uppercase mb-2">Verified_Signal_Sources:</h4>
                  {groundingUrls.map((chunk, i) => (
                    chunk.web && (
                      <a key={i} href={chunk.web.uri} target="_blank" rel="noopener noreferrer" className="block text-integrityOk hover:underline mb-1 truncate text-[10px]">
                        [{i+1}] {chunk.web.title || chunk.web.uri}
                      </a>
                    )
                  ))}
                </div>
              )}
           </div>
        </div>
      );
    }

    if (!output) return (
      <div className="flex flex-col items-center justify-center h-full opacity-40 select-none grayscale paper-grain">
        <div className="text-6xl font-black text-earth mb-4 rotate-12">🧠</div>
        <p className="text-[11px] uppercase tracking-[0.4em] font-black text-earth">ARCHON_OMEGA_STANDBY</p>
      </div>
    );

    return (
      <div key={flipKey} className="book-flip p-6 bg-white/40 border border-taupe/20 custom-scrollbar overflow-auto h-full paper-grain">
        {output.split('\n').map((line, i) => (
          <p key={i} className="text-[11px] text-earth font-mono leading-relaxed mb-2 border-l-2 border-burgundy/40 pl-4">{line}</p>
        ))}
      </div>
    );
  };

  return (
    <div className="bg-cream border-2 border-earth h-full flex flex-col relative overflow-hidden shadow-[10px_10px_0px_rgba(92,74,58,0.1)]">
      <div className="px-4 py-2 bg-earth border-b-2 border-burgundy flex justify-between items-center z-20 shrink-0">
        <h2 className="text-[10px] font-black text-cream uppercase tracking-[0.2em]">{featureTitle}</h2>
        <span className="text-integrityOk text-[9px] font-black">ARCHON-OMEGA_v9.5</span>
      </div>
      <div className="flex-grow overflow-hidden z-10 p-2 brutalist-grid">
        {renderContent()}
      </div>
      {renderSyncLogs()}
    </div>
  );
};

