    </div>
  );

  const renderContent = () => {
    if (requiresApiKey) return (
      <div className="flex flex-col items-center justify-center h-full border-2 border-neonOrange p-8 bg-cream/20 shadow-neon-orange paper-grain">
        <div className="text-5xl mb-4 animate-pulse">🔒</div>
