        </div>
      );
    }

    if (featureId === Feature.REHYDRATION_LAB) return renderRehydrationLab();
    if (featureId === Feature.VECTOR_DB_ORCHESTRATOR) return renderVectorHub();
    if (featureId === Feature.GALAXY_GUIDE) return renderGalaxyGuide();
    if (featureId === Feature.CLI_WORKSPACE) return renderCliWorkspace();
    if (featureId === Feature.KALI_SANDBOX) return renderKaliSandbox();
    if (featureId === Feature.PHET_LAB_SIM) return renderPhetLab();

    if (featureId === Feature.DATASET_ARCHEOLOGY && output) {
      return (
        <div className="h-full flex flex-col gap-4 bg-black p-4 border-2 border-neonOrange/30 overflow-hidden paper-grain">
           <div className="text-neonOrange font-black uppercase text-[12px] tracking-widest border-b border-neonOrange/20 pb-2 neon-text-glow-orange">DATASET_RECON_REPORTS</div>
           <div className="flex-grow overflow-y-auto custom-scrollbar font-mono text-[11px] text-neonOrange/90 p-2 space-y-4">
              {output.split('\n').map((l, i) => (
                <p key={i} className="border-l-2 border-neonOrange/20 pl-4 mb-2">{l}</p>
              ))}
              {groundingUrls && groundingUrls.length > 0 && (
                <div className="mt-8 border-t border-neonOrange/20 pt-4">
                  <h4 className="text-[9px] font-black uppercase mb-2 neon-text-glow-orange">Verified_Signal_Sources:</h4>
                  {groundingUrls.map((chunk, i) => (
                    chunk.web && (
                      <a key={i} href={chunk.web.uri} target="_blank" rel="noopener noreferrer" className="block text-integrityOk hover:underline mb-1 truncate text-[10px]">
