import React, { useState, useRef, useEffect } from 'react';

interface FloatingWindowProps {
  title: string;
  onClose?: () => void;
  children: React.ReactNode;
  initialPos?: { x: number, y: number };
  width?: string;
}

const FloatingWindow: React.FC<FloatingWindowProps> = ({ title, onClose, children, initialPos = { x: 100, y: 100 }, width = "400px" }) => {
  const [pos, setPos] = useState(initialPos);
  const [isDragging, setIsDragging] = useState(false);
  const dragStartRef = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent) => {
    setIsDragging(true);
    dragStartRef.current = { x: e.clientX - pos.x, y: e.clientY - pos.y };
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging) {
        setPos({
          x: e.clientX - dragStartRef.current.x,
          y: e.clientY - dragStartRef.current.y,
        });
      }
    };
    const handleMouseUp = () => setIsDragging(false);

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  return (
    <div 
      className="floating-window paper-grain flex flex-col border-2 border-neonOrange overflow-hidden shadow-neon-orange"
      style={{ left: pos.x, top: pos.y, width: width, transition: isDragging ? 'none' : 'transform 0.1s' }}
    >
      <div 
        className="bg-earth p-2 cursor-grab active:cursor-grabbing flex justify-between items-center z-10 border-b border-neonOrange/30"
        onMouseDown={handleMouseDown}
      >
        <span className="text-[9px] font-black text-cream uppercase italic tracking-widest neon-text-glow-orange">{title}</span>
        {onClose && (
          <button onClick={onClose} className="text-neonOrange font-black text-[10px] hover:scale-110 transition-transform neon-text-glow-orange">
            [X]
          </button>
        )}
      </div>
      <div className="flex-grow p-4 brutalist-grid">
        {children}
      </div>
    </div>
  );
};

export default FloatingWindow;

import React, { useState, useRef, useCallback } from 'react';
import { MotherBrainAsset, HardwareProfile } from '../types';

interface AssetNodeProps {
  asset: MotherBrainAsset;
  level: number;
  onSelect: (asset: MotherBrainAsset) => void;
  selectedId?: string;
  index: number;
  scrollOffset: number;
  isPanelActive: boolean;
  profile: HardwareProfile;
}

const AssetNode: React.FC<AssetNodeProps> = ({ asset, level, onSelect, selectedId, index, scrollOffset, isPanelActive, profile }) => {
  const [isOpen, setIsOpen] = useState(level < 1);
  const hasChildren = asset.children && asset.children.length > 0;
  const isSelected = selectedId === asset.id;

  const getIcon = () => {
    if (asset.type === 'folder') return isOpen ? '📂' : '📁';
    if (asset.type === 'headless_daemon') return '⚙️';
    return '📜';
  };

  const handleClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (hasChildren) setIsOpen(!isOpen);
    else onSelect(asset);
  };

  const itemsVisible = 12;
  const anglePerItem = 18;
  const relativeIndex = index - scrollOffset;
  const rotation = relativeIndex * anglePerItem;
  const opacity = Math.max(0, 1 - Math.abs(relativeIndex) / (itemsVisible / 2));

  return (
    <div 
      className={`rolodex-item absolute w-full font-mono text-[9px] select-none transition-all duration-300 z-10`}
      style={{
        transform: `translateY(${relativeIndex * 25}px)`,
        opacity: opacity,
        zIndex: Math.round(opacity * 100)
      }}
    >
      <div 
        className={`flex items-center gap-2 py-1.5 px-3 cursor-pointer border-l-2 ${isSelected ? 'bg-neonOrange/20 border-neonOrange' : 'border-transparent hover:bg-white/40 hover:border-neonOrange'}`}
        style={{ paddingLeft: `${level * 10 + 12}px` }}
        onClick={handleClick}
      >
        <span className={isSelected ? 'neon-text-glow-orange' : ''}>{getIcon()}</span>
        <span className={`truncate ${isSelected ? 'text-neonOrange font-black italic underline' : ''}`}>{asset.name}</span>
      </div>
      {hasChildren && isOpen && (
        <div className="ml-2">
          {asset.children!.map((child, i) => (
            <AssetNode key={child.id} asset={child} level={level + 1} onSelect={onSelect} selectedId={selectedId} index={index + (i + 1) * 0.5} scrollOffset={scrollOffset} isPanelActive={isPanelActive} profile={profile} />
          ))}
        </div>
      )}
    </div>
  );
};

