  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS' | 'DEBUG'>('REFS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [discoveredAssets, setDiscoveredAssets] = useState<MotherBrainAsset[]>([]);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [mobileView, setMobileView] = useState<'NAV' | 'MAIN' | 'CONTROLS'>('MAIN');

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120, contrast: 140, saturation: 20, grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0, scanlineWeight: 0.25, flickerSpeed: 0.1, enableSway: true,
    chromaticAberration: true, theme: 'cream', moltMode: true, touchOptimization: window.innerWidth < 1024,
    hardwareProfile: 'BALANCED', audioActive: true, showSwarmTopology: false,
    layout: {
      leftColWidth: 25,
      rightColWidth: 25,
      headerHeight: 80
    },
    activeFeatures: FEATURES.map(f => f.id),
    crtWarp: 5,
    neonIntensity: 1.0,
    terminalBrightness: 1.0,
    floatingWindows: false,
    dualScreenMode: false,
    handsFreeVoice: false,
    reducedMotion: false,
    highContrast: false,
    fontSize: 11,
    logRetention: 100
  });

  const addLog = useCallback((level: LogEntry['level'], module: string, message: string, data?: any) => {
    const entry: LogEntry = {
      id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      level,
      module,
      message,
      timestamp: new Date().toLocaleTimeString(),
      data
    };
    setLogs(prev => [entry, ...prev].slice(0, uiSettings.logRetention));
    if (level === 'ERROR' || level === 'FATAL') console.error(`[${module}] ${message}`, data);
  }, [uiSettings.logRetention]);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      setUiSettings(prev => ({ ...prev, touchOptimization: mobile }));
    };
    window.addEventListener('resize', handleResize);
    addLog('INFO', 'KERNEL', 'ARCHON_OMEGA system initialized. Protocol: Sol X.');
    return () => window.removeEventListener('resize', handleResize);
  }, [addLog]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    addLog('INFO', 'UI', 'Visual handshake triggered.');
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: UISettings['theme']) => {
    setIsMolting(true);
    addLog('INFO', 'THEME', `Theme switching to ${newTheme}.`);
    setTimeout(() => {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
      setTimeout(() => setIsMolting(false), 400);
    }, 300);
  }, [addLog]);

  const handleJumpComplete = (target: StarSystem) => {
    triggerHandshake();
    addLog('INFO', 'NAVIGATION', `Wormhole jump to ${target.name} complete.`);
    setOutput(`ARCHON_WORMHOLE_FEED: Jump complete. Arrived at ${target.name}.\n\nFaction: ${target.faction}\nSpectral: ${target.spectral_class}\nDescription: ${target.description}\n\nARCHON: "Local strata scanning initiated. All potential artifacts flagged for rehydration."`);
  };

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    triggerHandshake();
    setIsLoading(true);
    setGroundingUrls([]);
    addLog('INFO', 'AI_ENGINE', `Requesting content for feature: ${selectedFeature}`);

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        const msgs = await generateMeetingContent(customPrompt || "Devise Rehydration & Monetization Strategy", MEETING_AGENTS);
        setMeetingMessages(msgs);
        addLog('INFO', 'AI_ENGINE', `Meeting simulation complete. ${msgs.length} messages received.`);
      } else {
        const { text, urls } = await generateContent(selectedFeature, selectedAsset?.code || GD_SCRIPT_CODE, customPrompt);
        setOutput(text);
        if (urls) setGroundingUrls(urls);

        if (selectedFeature === Feature.REHYDRATION_LAB) {
           const found: MotherBrainAsset = {
              id: `rehydrated-${Date.now()}`,
              name: `rehydrated_${selectedAsset?.name || 'artifact'}.gd`,
              type: 'script',
              path: `/synced/production/${selectedAsset?.name || 'artifact'}.gd`,
              code: text,
              rehydrationLevel: 100
           };
           setDiscoveredAssets(prev => [found, ...prev]);
           addLog('INFO', 'ARCHEOLOGY', `Artifact rehydrated successfully: ${found.name}`);

           setSyncLogs(prev => [
             { id: `log-${Date.now()}-1`, operation: 'REHYDRATED', source: selectedAsset?.path || 'DRIVE_STRATA', target: found.path, hash: 'a7f2_Ω', timestamp: new Date().toLocaleTimeString() },
             { id: `log-${Date.now()}-2`, operation: 'VERIFIED', source: found.path, target: found.path, hash: 'b881_Ω', timestamp: new Date().toLocaleTimeString() },
             ...prev
           ]);
        }
      }
    } catch (err: any) {
      addLog('ERROR', 'AI_ENGINE', `Generation failed: ${err.message}`, err);
      setOutput(`ARCHON_FAULT: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  }, [selectedFeature, selectedAsset, addLog]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', uiSettings.theme);
    document.documentElement.style.setProperty('--neon-intensity', uiSettings.neonIntensity.toString());
    document.documentElement.style.setProperty('--term-brightness', uiSettings.terminalBrightness.toString());
    const filter = document.getElementById('crt-warp-filter');
    if (filter) {
        const displacement = filter.querySelector('feDisplacementMap');
        if (displacement) displacement.setAttribute('scale', uiSettings.crtWarp.toString());
    }
  }, [uiSettings]);

  const combinedAssets = [...discoveredAssets, ...MOTHER_BRAIN_ASSETS];
  const activeFeaturesList = FEATURES.filter(f => uiSettings.activeFeatures.includes(f.id));

  const centerColWidth = isMobile ? 100 : (100 - uiSettings.layout.leftColWidth - uiSettings.layout.rightColWidth);

  const renderLeftCol = () => (
    <div className="flex flex-col gap-4 h-full">
        <CameraMonitor settings={cameraSettings} onUpdateSettings={setCameraSettings} />
        {!uiSettings.floatingWindows && <MediaCenter />}
        <div className="flex-grow flex flex-col overflow-hidden border-2 border-neonOrange shadow-neon-orange-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[8px] font-black uppercase">
                <button onClick={() => setActiveTab('REFS')} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream' : ''}`}>Archeology</button>
                <button onClick={() => setActiveTab('INTEGRATIONS')} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream' : ''}`}>Integrations</button>
                <button onClick={() => setActiveTab('DEBUG')} className={`flex-1 py-2 ${activeTab === 'DEBUG' ? 'bg-earth text-cream' : ''}`}>System</button>
            </div>
            <div className="flex-grow overflow-hidden p-1">
                {activeTab === 'REFS' ? (
                <MotherBrainRepo onSelectAsset={setSelectedAsset} selectedAssetId={selectedAsset?.id} isPanelActive={true} profile={uiSettings.hardwareProfile} assets={combinedAssets} />
                ) : activeTab === 'INTEGRATIONS' ? (
                <IntegrationHub />
                ) : (
                <SystemDebugger logs={logs} isActive={true} onClear={() => setLogs([])} />
                )}
            </div>
        </div>
    </div>
  );

  return (
    <ErrorBoundary>
      <div 
        className={`h-full flex flex-col p-4 md:p-6 gap-4 bg-cream text-earth overflow-hidden ${isGlitching ? 'fusion-glitch' : ''} ${uiSettings.enableSway && !isLoading && !uiSettings.reducedMotion ? 'tv-glitch-active' : 'no-sway'}`}
        style={{
          '--header-h': `${uiSettings.layout.headerHeight}px`,
        } as React.CSSProperties}
      >
        {isMolting && <div className="molting-shred"></div>}
        <UISettingsPanel settings={uiSettings} onUpdate={setUiSettings} onThemeChange={handleMolt} onClose={() => setIsUISettingsOpen(false)} isActive={isUISettingsOpen} allFeatures={FEATURES} />

        <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2 relative paper-grain-subtle" style={{ height: 'var(--header-h)' }}>
          <div className="flex items-center gap-6">
            <div className="w-12 h-12 bg-earth flex items-center justify-center border-2 border-neonOrange relative shadow-neon-orange">
               <span className="text-white text-3xl font-black italic neon-text-glow-white">Ω</span>
               {!uiSettings.reducedMotion && <NeonParticles trigger={particleTrigger} color="#FFFFFF" />}
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-black uppercase tracking-tighter italic">&lt;V&gt;-9.5_ARCHON_OMEGA</h1>
              {!isMobile && <p className="text-[9px] font-black uppercase text-earth/60">COPILOT: <span className="text-integrityOk">ARCHON_ACTIVE</span> | GOVERNANCE: <span className="text-integrityOk">SOL_X</span></p>}
            </div>
          </div>
          <div className="flex gap-4">
             {uiSettings.handsFreeVoice && (
                <div className="flex items-center gap-2 px-2 md:px-4 bg-integrityOk/20 border border-integrityOk animate-pulse rounded-full">
                   <span className="text-[10px] font-black text-integrityOk">🎤 <span className="hidden md:inline">LIVE_LINK</span></span>
                </div>
             )}
             <button onClick={() => setIsUISettingsOpen(true)} className="text-[10px] font-black uppercase underline decoration-neonOrange/40">CONFIG</button>
             {!isMobile && <StatusBoard />}
          </div>
        </header>

        <main className="flex-grow grid grid-cols-12 gap-6 overflow-hidden relative">
          {/* Layout logic for Mobile vs Desktop */}
          {isMobile ? (
            <div className="col-span-12 flex flex-col h-full overflow-hidden">
               {mobileView === 'NAV' && <div className="h-full">{renderLeftCol()}</div>}
               {mobileView === 'MAIN' && (
                  <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden">
                    {selectedFeature === Feature.GALAXY_MAP_GEN ? (
                        <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={handleJumpComplete} />
                    ) : (
                        <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
                    )}
                  </div>
               )}
               {mobileView === 'CONTROLS' && (
                  <div className="h-full border-2 border-neonOrange shadow-neon-orange-sm overflow-hidden">
                    <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} />
                  </div>
               )}

               {/* Mobile Tab Bar */}
               <nav className="flex shrink-0 border-t-2 border-earth/20 mt-4 bg-cream z-50">
                  <button onClick={() => setMobileView('NAV')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'NAV' ? 'bg-earth text-cream' : ''}`}>Silo</button>
                  <button onClick={() => setMobileView('MAIN')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'MAIN' ? 'bg-earth text-cream' : ''}`}>Main</button>
                  <button onClick={() => setMobileView('CONTROLS')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'CONTROLS' ? 'bg-earth text-cream' : ''}`}>Cmd</button>
               </nav>
            </div>
          ) : (
            <>
              {/* Desktop Three Column Layout */}
              <div className="overflow-hidden h-full" style={{ gridColumn: `span ${Math.round(uiSettings.layout.leftColWidth / 8.33)}` }}>
                {!uiSettings.floatingWindows ? renderLeftCol() : (
                    <div className="h-full border-2 border-dashed border-neonOrange/30 flex items-center justify-center italic text-[10px] text-earth/40 uppercase">
                      Floating_Silo_Active
                    </div>
                )}
              </div>

              <div className="flex flex-col gap-4 overflow-hidden h-full" style={{ gridColumn: `span ${Math.round(centerColWidth / 8.33)}` }}>
                {uiSettings.dualScreenMode ? (
                  <div className="grid grid-rows-2 h-full gap-4">
                      <div className="border-2 border-neonOrange shadow-neon-orange-sm overflow-hidden">
                        <LiveVoiceChat isActive={true} handsFree={uiSettings.handsFreeVoice} />
                      </div>
                      <div className="border-2 border-neonOrange shadow-neon-orange-sm overflow-hidden">
                        {selectedFeature === Feature.GALAXY_MAP_GEN ? (
                            <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={handleJumpComplete} />
                        ) : (
                            <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
                        )}
                      </div>
                  </div>
                ) : (
                  <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden">
                    {selectedFeature === Feature.GALAXY_MAP_GEN ? (
                        <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={handleJumpComplete} />
                    ) : (
                        <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
                    )}
                  </div>
                )}
              </div>

              <div className="overflow-hidden h-full border-2 border-neonOrange shadow-neon-orange-sm" style={{ gridColumn: `span ${Math.round(uiSettings.layout.rightColWidth / 8.33)}` }}>
                <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} />
              </div>
            </>
          )}

          {/* Floating Windows Layer */}
          {uiSettings.floatingWindows && !isMobile && (
            <>
                <FloatingWindow title="OMNI_MEDIA" initialPos={{x: 50, y: 50}} width="320px">
                  <MediaCenter />
                </FloatingWindow>
                <FloatingWindow title="SYNC_ACTIVITY" initialPos={{x: 400, y: 150}} width="350px">
                  <div className="bg-cream/40 p-4 font-mono text-[8px] h-40 overflow-auto">
                      {syncLogs.length > 0 ? syncLogs.map(l => (
                        <div key={l.id} className="mb-1 border-b border-earth/10">{l.timestamp} - {l.operation} - {l.target}</div>
                      )) : "Awaiting sync activity..."}
                  </div>
                </FloatingWindow>
                {uiSettings.handsFreeVoice && !uiSettings.dualScreenMode && (
                  <FloatingWindow title="VOICE_UPLINK" initialPos={{x: 800, y: 300}} width="450px">
                      <LiveVoiceChat isActive={true} handsFree={uiSettings.handsFreeVoice} />
                  </FloatingWindow>
                )}
            </>
          )}
        </main>

        <style dangerouslySetInnerHTML={{ __html: `
          .neon-text-glow-white { text-shadow: 0 0 calc(10px * var(--neon-intensity)) #FFFFFF, 0 0 calc(20px * var(--neon-intensity)) #FFFFFF; }
          @keyframes dash { to { stroke-dashoffset: -20; } }
          .font-size-custom { font-size: ${uiSettings.fontSize}px; }
        `}} />
      </div>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState } from 'react';
import { UISettings, HardwareProfile, Feature, FeatureInfo } from '../types';
import { HARDWARE_TARGETS, ARCHON_MANUAL } from '../constants';

interface UISettingsPanelProps {
  settings: UISettings;
  onUpdate: (settings: UISettings) => void;
  onThemeChange: (theme: UISettings['theme']) => void;
  onClose: () => void;
  isActive: boolean;
  allFeatures: FeatureInfo[];
}

const UISettingsPanel: React.FC<UISettingsPanelProps> = ({ settings, onUpdate, onThemeChange, onClose, isActive, allFeatures }) => {
  const [activeTab, setActiveTab] = useState<'VISUAL' | 'MOBILE' | 'FEATURES' | 'MANUAL'>('VISUAL');
  const [manualSection, setManualSection] = useState(ARCHON_MANUAL.sections[0].id);

  if (!isActive) return null;

  const handleChange = (key: keyof UISettings, value: any) => {
    onUpdate({ ...settings, [key]: value });
  };

  const handleLayoutChange = (key: keyof UISettings['layout'], value: number) => {
    onUpdate({
      ...settings,
      layout: { ...settings.layout, [key]: value }
    });
  };

  const toggleFeature = (fid: Feature) => {
    const next = settings.activeFeatures.includes(fid)
      ? settings.activeFeatures.filter(id => id !== fid)
      : [...settings.activeFeatures, fid];
    handleChange('activeFeatures', next);
  };

  const Slider = ({ label, value, min, max, step = 1, unit = "", onChange }: { label: string, value: number, min: number, max: number, step?: number, unit?: string, onChange: (val: number) => void }) => (
    <div className="mb-4">
      <div className="flex justify-between items-center mb-1">
        <label className="text-[9px] text-earth font-black uppercase italic">{label}</label>
        <span className="text-[9px] text-neonOrange font-mono">{value}{unit}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(parseFloat(e.target.value))}
        className="w-full h-1 bg-taupe/30 border border-taupe/50 rounded-none appearance-none cursor-pointer accent-neonOrange"
      />
    </div>
  );

  const Toggle = ({ label, active, onClick }: { label: string, active: boolean, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className={`p-3 border-2 font-black text-[9px] uppercase transition-all flex items-center justify-between gap-4 ${active ? 'bg-earth text-cream border-earth' : 'bg-cream text-earth border-taupe/40'}`}
    >
      <span>{label}</span>
      <div className={`w-8 h-4 border ${active ? 'bg-neonOrange border-neonOrange' : 'bg-taupe/20 border-taupe/40'} relative`}>
        <div className={`absolute top-0.5 w-3 h-2.5 bg-white transition-all ${active ? 'right-0.5' : 'left-0.5'}`}></div>
      </div>
    </button>
  );

  const hardwareProfiles: HardwareProfile[] = ['LEGACY', 'BALANCED', 'MOBILE_STARK', 'ULTRA'];

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
      <div className="bg-cream border-4 border-earth w-full max-w-2xl p-6 shadow-[15px_15px_0px_var(--accent-burgundy)] flex flex-col gap-6 relative max-h-[95vh] overflow-hidden paper-grain">
        <div className="absolute top-0 right-0 p-2 text-[6px] font-black text-earth/20 uppercase tracking-widest z-20">
          ARCHON_UI_KERNEL_CONFIG_V9.5
        </div>

        <div className="flex justify-between items-center border-b-2 border-earth pb-2 z-10 shrink-0">
          <h3 className="text-[12px] font-black text-earth uppercase tracking-widest italic">ARCHON_SYS_CALIBRATION</h3>
          <button 
            onClick={onClose}
            className="text-burgundy hover:text-neonOrange transition-colors text-[10px] font-black underline"
          >
            [COMMIT_CHANGES]
          </button>
        </div>

        {/* Tabs */}
        <div className="flex gap-2 border-b border-earth/20 shrink-0 z-10 overflow-x-auto no-scrollbar">
          {['VISUAL', 'MOBILE', 'FEATURES', 'MANUAL'].map(tab => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab as any)}
              className={`px-4 py-2 text-[10px] font-black tracking-widest transition-all whitespace-nowrap ${activeTab === tab ? 'bg-earth text-cream' : 'text-earth/40 hover:text-earth'}`}
            >
              {tab}
            </button>
          ))}
        </div>

        <div className="flex-grow overflow-y-auto custom-scrollbar z-10 pr-2">
          {activeTab === 'VISUAL' && (
            <div className="space-y-6">
              <div className="flex flex-col gap-2">
                <label className="text-[9px] text-earth font-black uppercase italic">Hardware_Target</label>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-2">
                    {hardwareProfiles.map(profile => (
                      <button 
                          key={profile}
                          onClick={() => handleChange('hardwareProfile', profile)}
                          className={`p-2 text-[8px] font-black border-2 transition-all flex flex-col items-center gap-1 ${settings.hardwareProfile === profile ? 'bg-earth text-cream border-earth shadow-inner' : 'bg-cream text-earth border-taupe/40 hover:border-neonOrange'}`}
                      >
                          <span className="text-[9px]">{(HARDWARE_TARGETS as any)[profile].name}</span>
                          <span className="opacity-40 italic">{(HARDWARE_TARGETS as any)[profile].fps}FPS</span>
                      </button>
                    ))}
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <Slider label="Glitch_Intensity" value={settings.glitchIntensity} min={0} max={5} step={0.1} onChange={(v) => handleChange('glitchIntensity', v)} />
                  <Slider label="Scanline_Weight" value={settings.scanlineWeight} min={0} max={1} step={0.05} onChange={(v) => handleChange('scanlineWeight', v)} />
                  <Slider label="CRT_Warp" value={settings.crtWarp} min={0} max={50} step={1} onChange={(v) => handleChange('crtWarp', v)} />
                </div>
                <div className="space-y-4">
                   <Slider label="Neon_Intensity" value={settings.neonIntensity} min={0} max={3} step={0.1} onChange={(v) => handleChange('neonIntensity', v)} />
                   <Slider label="Terminal_Brightness" value={settings.terminalBrightness} min={0.2} max={1.5} step={0.05} onChange={(v) => handleChange('terminalBrightness', v)} />
                   <Toggle label="Reduced_Motion" active={settings.reducedMotion} onClick={() => handleChange('reducedMotion', !settings.reducedMotion)} />
                </div>
              </div>
              <div className="flex flex-col gap-2">
                <label className="text-[9px] text-earth font-black uppercase italic">Active_Theme</label>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-2">
                  {['cream', 'void', 'budowski-dark', 'neon-vulture', 'paper-sepia'].map(theme => (
                    <button 
                      key={theme}
                      onClick={() => onThemeChange(theme as any)}
                      className={`py-2 text-[8px] font-black border-2 transition-all uppercase ${settings.theme === theme ? 'bg-earth text-cream border-earth shadow-inner' : 'bg-cream text-earth border-taupe/40'}`}
                    >
                      {theme.split('-')[0]}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {activeTab === 'MOBILE' && (
            <div className="space-y-6">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <Toggle label="Touch_Optimization" active={settings.touchOptimization} onClick={() => handleChange('touchOptimization', !settings.touchOptimization)} />
                <Toggle label="High_Contrast" active={settings.highContrast} onClick={() => handleChange('highContrast', !settings.highContrast)} />
                <Toggle label="Floating_Windows" active={settings.floatingWindows} onClick={() => handleChange('floatingWindows', !settings.floatingWindows)} />
                <Toggle label="Dual_Screen_Mode" active={settings.dualScreenMode} onClick={() => handleChange('dualScreenMode', !settings.dualScreenMode)} />
              </div>
              <Slider label="Global_Font_Size" value={settings.fontSize} min={8} max={18} unit="px" onChange={(v) => handleChange('fontSize', v)} />
              <Slider label="Log_Retention" value={settings.logRetention} min={10} max={500} onChange={(v) => handleChange('logRetention', v)} />

              <div className="grid grid-cols-1 md:grid-cols-3 gap-2">
                <Slider label="Left_Col" value={settings.layout.leftColWidth} min={15} max={40} unit="%" onChange={(v) => handleLayoutChange('leftColWidth', v)} />
                <Slider label="Right_Col" value={settings.layout.rightColWidth} min={15} max={40} unit="%" onChange={(v) => handleLayoutChange('rightColWidth', v)} />
                <Slider label="Header_H" value={settings.layout.headerHeight} min={60} max={120} unit="px" onChange={(v) => handleLayoutChange('headerHeight', v)} />
              </div>
            </div>
          )}

          {activeTab === 'FEATURES' && (
            <div className="space-y-4">
