export const generateTTS = async (text: string, voice: string = 'Kore'): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    logToKernel('INFO', `Requesting TTS for voice: ${voice}`);
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: text }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } },
      },
    });
    return response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data || "";
  } catch (e) { 
    logToKernel('ERROR', 'TTS generation failed', e);
    return ""; 
  }
};

export const generateMeetingContent = async (prompt: string, agents: MeetingAgent[]): Promise<MeetingMessage[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const messages: MeetingMessage[] = [];
  let conversationHistory = `ARCHON_SYNC_PROTOCOL: "${prompt}"\n\n`;

  logToKernel('INFO', `Starting meeting orchestration with ${agents.length} agents`);

  for (const agent of agents) {
    try {
      logToKernel('INFO', `Agent ${agent.name} is thinking...`);
      const response = await ai.models.generateContent({
        model: agent.model as any,
        contents: conversationHistory + `\n\nNOW RESPONDING: ${agent.name}`,
        config: { systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT, agent) },
      });
      const text = response.text || "SIGNAL_LOST";
      let audioData = await generateTTS(text, agent.name === 'RAG_CONTROLLER' ? 'Zephyr' : (agent.name === 'ARCHON_CORE' ? 'Puck' : 'Kore'));
      messages.push({ agentId: agent.id, text, timestamp: new Date().toLocaleTimeString(), audioData });
      conversationHistory += `\n${agent.name}: ${text}\n`;
    } catch (e) { 
      logToKernel('ERROR', `Agent ${agent.name} encountered an uplink error`, e);
    }
  }
  return messages;
};

const getPromptForFeature = (feature: Feature, currentCode: string, customPrompt?: string): string => {
  const codeBlock = `\`\`\`gdscript\n${currentCode}\n\`\`\``;

  switch (feature) {
    case Feature.REHYDRATION_LAB:
      return `ARCHON_REHYDRATION_OP: "${customPrompt || 'Scan Drive for orphaned Godot scripts and debug them for production'}"
      - Action: Perform deep archeology. Find orphans, identify logic failures, rehydrate for ARCHON-V9.5 standards.
      - Output: Debugged code, production readiness report, and monetization strategy.`;

    case Feature.GALAXY_GUIDE:
      return `ARCHON_GALAXY_GUIDE_TERMINAL: "${customPrompt || 'Access the Guide to the Galaxy for current coordinates'}"
      - Action: Ingest data from drive strata (JSON, MD, TXT). Format as an 80s encyclopedia entry with a humorous, "Guide-like" voice.
      - Output: Lore, navigation tips, faction status, and a warning about the local Vulture Reavers.`;

    case Feature.DATASET_ARCHEOLOGY:
      return `ARCHON_ARCHEOLOGY_SCAN: "${customPrompt || 'Search for the latest climate and geospatial datasets'}"
      - Action: USE GOOGLE SEARCH to find live URLs.
      - Output: List of URLs, metadata descriptions, and suggested Vector DB embedding strategy.`;

    case Feature.VECTOR_DB_ORCHESTRATOR:
      return `ARCHON_VECTOR_ORCHESTRATOR: "${customPrompt || 'Automate Pinecone/Chroma integration for Drive strata'}"
      - Action: Build the RAG pipeline for the Mother Brain.
      - Output: Implementation scripts for vector database creation and maintenance.`;

    case Feature.MCP_INTERFACE:
      return `ARCHON_MCP_TOOL_BUILDER: "${customPrompt || 'Design a universal MCP tool for Google Drive and Github orchestration'}"
      - Output: Tool definitions (JSON) and autonomous execution logic.`;

    default:
      return `ARCHON_OMEGA_OP: ${feature}\n\n${codeBlock}`;
  }
};

export const generateContent = async (feature: Feature, code?: string, customPrompt?: string): Promise<{text: string, urls?: any[]}> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const config: any = { 
      systemInstruction: getSystemInstruction(COSMIC_KEY_CONTEXT), 
      temperature: 0.3 
    };

    if (feature === Feature.DATASET_ARCHEOLOGY) {
      config.tools = [{ googleSearch: {} }];
    }

    logToKernel('INFO', `Initiating content generation for feature: ${feature}`);
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: getPromptForFeature(feature, code || GD_SCRIPT_CODE, customPrompt),
      config,
    });

    logToKernel('INFO', `Response received from AI Kernel.`);
    return {
      text: response.text || "EMPTY_RESPONSE",
      urls: response.candidates?.[0]?.groundingMetadata?.groundingChunks
    };
  } catch (error: any) { 
    logToKernel('ERROR', `Content generation critical failure`, error);
    return { text: `ARCHON_FAULT: ${error.message}` }; 
  }
};

