  const [transcription, setTranscription] = useState('');
  const [lastCommand, setLastCommand] = useState<string | null>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const sessionRef = useRef<any>(null);

  const encode = (bytes: Uint8Array) => {
    let binary = '';
    for (let i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  };
  const decode = (base64: string) => {
    const binaryString = atob(base64);
    const bytes = new Uint8Array(binaryString.length);
    for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
    return bytes;
  };
  const decodeAudioData = async (data: Uint8Array, ctx: AudioContext) => {
    const dataInt16 = new Int16Array(data.buffer);
    const buffer = ctx.createBuffer(1, dataInt16.length, 24000);
    const channelData = buffer.getChannelData(0);
    for (let i = 0; i < dataInt16.length; i++) channelData[i] = dataInt16[i] / 32768.0;
    return buffer;
  };

  useEffect(() => {
    if (!isActive) {
      if (sessionRef.current) sessionRef.current.close();
      return;
    }

    const startSession = async () => {
      setIsConnecting(true);
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const inputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputCtx = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputCtx;

      let nextStartTime = 0;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: async () => {
            setIsConnecting(false);
            const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
            const source = inputCtx.createMediaStreamSource(stream);
            const processor = inputCtx.createScriptProcessor(4096, 1, 1);
            processor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const int16 = new Int16Array(inputData.length);
              for (let i = 0; i < inputData.length; i++) int16[i] = inputData[i] * 32768;
              const pcmBlob: Blob = {
                data: encode(new Uint8Array(int16.buffer)),
                mimeType: 'audio/pcm;rate=16000',
              };
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(processor);
            processor.connect(inputCtx.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Handle Tool Calls
            if (msg.toolCall) {
              for (const fc of msg.toolCall.functionCalls) {
                setLastCommand(`${fc.name.toUpperCase()}(${JSON.stringify(fc.args)})`);
                if (onAction) onAction(fc.name, fc.args);

                // Respond to tool call to maintain context
                sessionPromise.then(s => s.sendToolResponse({
                  functionResponses: [{
                    id: fc.id,
                    name: fc.name,
                    response: { result: "ok" }
                  }]
                }));

                // Clear feedback after delay
                setTimeout(() => setLastCommand(null), 3000);
              }
            }

            // Handle Audio
            if (msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data) {
              setIsTalking(true);
              const audioStr = msg.serverContent.modelTurn.parts[0].inlineData.data;
              const buffer = await decodeAudioData(decode(audioStr), outputCtx);
              const source = outputCtx.createBufferSource();
              source.buffer = buffer;
              source.connect(outputCtx.destination);
              nextStartTime = Math.max(nextStartTime, outputCtx.currentTime);
              source.start(nextStartTime);
              nextStartTime += buffer.duration;
              source.onended = () => setIsTalking(false);
            }
            if (msg.serverContent?.outputTranscription) {
              setTranscription(prev => prev + msg.serverContent.outputTranscription.text);
            }
            if (msg.serverContent?.turnComplete) {
              setTranscription('');
            }
          },
          onerror: (e) => console.error('Live Voice Error:', e),
          onclose: () => setIsConnecting(false),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are ARCHON, a helpful mecha copilot. Keep responses brief.
          You can control the application using available tools. 
          If the user wants to navigate, switch features, start a scan, or control music, use the tools.
          Always acknowledge commands with a brief mecha-style confirmation like "Affirmative, command acknowledged." or "Executing sequence."`,
          outputAudioTranscription: {},
          tools: [{ functionDeclarations: APP_ACTIONS }]
        }
      });

      sessionRef.current = await sessionPromise;
    };

    startSession();
    return () => {
      if (sessionRef.current) sessionRef.current.close();
    };
  }, [isActive, onAction]);

  if (!isActive) return null;

  return (
    <div className="p-6 bg-earth border-4 border-neonOrange flex flex-col gap-4 paper-grain relative overflow-hidden">
      <div className="absolute top-0 right-0 p-1 text-[6px] font-black text-neonOrange/40 uppercase">VOICE_COMM_SYNC</div>
      <div className="flex items-center gap-4">
        <div className={`w-12 h-12 rounded-full border-4 flex items-center justify-center text-2xl transition-all ${isTalking ? 'bg-neonOrange border-white animate-pulse' : 'bg-taupe border-earth'}`}>
          🤖
        </div>
        <div className="flex-grow">
           <div className="text-[10px] font-black text-cream uppercase tracking-widest italic">ARCHON_LIVE_FEED</div>
           <div className="text-[8px] font-black text-integrityOk">STATUS: {isConnecting ? 'ESTABLISHING_LINK...' : 'COMM_READY'}</div>
        </div>
        {lastCommand && (
          <div className="bg-integrityOk/20 border border-integrityOk px-2 py-1 animate-bounce">
            <span className="text-[8px] font-black text-integrityOk uppercase">EXEC_CMD: {lastCommand.split('(')[0]}</span>
          </div>
        )}
      </div>

      <div className="flex-grow bg-black/40 border-2 border-neonOrange/20 p-4 min-h-[100px] flex flex-col">
         <div className="text-[7px] font-black text-neonOrange/40 uppercase mb-2">Incoming_Transmission:</div>
         <div className="text-[11px] font-mono text-integrityOk italic whitespace-pre-wrap">
            {transcription || (isConnecting ? 'Establishing secure uplink...' : 'Awaiting signal...')}
         </div>
      </div>

      <div className="flex justify-between items-center text-[8px] font-black text-cream/40 uppercase">
         <div className="flex gap-1 items-center">
            <div className={`w-2 h-2 rounded-full ${handsFree ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}></div>
            HANDS_FREE_ENABLED
         </div>
         <div>Baud: 24000Hz</div>
      </div>
    </div>
  );
};

