#!/usr/bin/env python3
# nomadz_mcp_core.py
# Entity: VOLTRON (VCN-1.1-RATIFIED)
# Status: v1.0 (MCP implementation)
# Purpose: Model Context Protocol server for Mother-Brain integration.

import sys
import os
import json
import asyncio
import shutil
import hashlib
from typing import Dict, Any, List

# --- VCN CONFIGURATION ---
DEPLOYMENT_ROOT = os.path.expanduser("~/nomadz")
LOGS_DIR = os.path.join(DEPLOYMENT_ROOT, "logs")
AUTOMATION_DIR = os.path.join(DEPLOYMENT_ROOT, "automation")

class NomadzMCPServer:
    def __init__(self):
        self.version = "1.0.0"
        self.name = "nomadz-mcp-core"

    async def read_input(self):
        """Reads MCP JSON-RPC requests from stdin."""
        loop = asyncio.get_event_loop()
        reader = asyncio.StreamReader()
        protocol = asyncio.StreamReaderProtocol(reader)
        await loop.connect_read_pipe(lambda: protocol, sys.stdin)

        while True:
            line = await reader.readline()
            if not line:
                break
            yield json.loads(line.decode())

    def write_output(self, response: Dict[str, Any]):
        """Writes MCP JSON-RPC responses to stdout."""
        sys.stdout.write(json.dumps(response) + "\n")
        sys.stdout.flush()

    # --- TOOLS IMPLEMENTATION ---
    def get_system_health(self) -> Dict[str, Any]:
        """Tool: Inspects the health of the NOMADZ daemons."""
        daemons = ["shadow_proxy_git_daemon.py", "cosmic_key_ai_node.py"]
        health = {}
        for d in daemons:
            # Simple process check using pgrep
            is_active = os.system(f"pgrep -f {d} > /dev/null") == 0
            health[d] = "ACTIVE" if is_active else "STOPPED"
        return {"status": "success", "data": health}

    def read_mother_brain_log(self, lines: int = 50) -> Dict[str, Any]:
        """Tool: Retrieves the latest entries from the master deployment log."""
        log_path = os.path.join(LOGS_DIR, "deployment_master.log")
        if not os.path.exists(log_path):
            return {"status": "error", "message": "Log file not found."}

        with open(log_path, 'r') as f:
            content = f.readlines()[-lines:]
        return {"status": "success", "data": "".join(content)}

    def calculate_vcn_hash(self, filename: str) -> Dict[str, Any]:
        """Tool: Returns the SHA256 hash of a file for integrity verification."""
        path = os.path.join(AUTOMATION_DIR, filename)
        if not os.path.exists(path):
            return {"status": "error", "message": "File not found."}

        sha256_hash = hashlib.sha256()
        with open(path, "rb") as f:
            for byte_block in iter(lambda: f.read(4096), b""):
                sha256_hash.update(byte_block)
        return {"status": "success", "hash": sha256_hash.hexdigest()}

    # --- CORE DISPATCHER ---
    async def run(self):
        """Main loop for the MCP Server."""
        async for request in self.read_input():
            req_id = request.get("id")
            method = request.get("method")
            params = request.get("params", {})

            result = {"status": "error", "message": "Method not found"}

            if method == "initialize":
                result = {
                    "protocolVersion": "2024-11-05",
                    "capabilities": {"tools": {}},
                    "serverInfo": {"name": self.name, "version": self.version}
                }
            elif method == "tools/list":
                result = {
                    "tools": [
                        {"name": "get_system_health", "description": "Check status of VCN daemons."},
                        {"name": "read_log", "description": "Read deployment master log."},
                        {"name": "verify_integrity", "description": "Get SHA256 of automation scripts."}
                    ]
                }
            elif method == "tools/call":
                tool_name = params.get("name")
                args = params.get("arguments", {})

                if tool_name == "get_system_health":
                    result = self.get_system_health()
                elif tool_name == "read_log":
                    result = self.read_mother_brain_log(args.get("lines", 50))
                elif tool_name == "verify_integrity":
                    result = self.calculate_vcn_hash(args.get("filename", ""))

            # MCP standard response wrap
            self.write_output({
                "jsonrpc": "2.0",
                "id": req_id,
                "result": result
            })

if __name__ == "__main__":
    server = NomadzMCPServer()
    try:
        asyncio.run(server.run())
    except KeyboardInterrupt:
        pass

