  // NEW VISUAL EFFECTS
  crtWarp: number;
  neonIntensity: number;
  terminalBrightness: number;
  floatingWindows: boolean;
  dualScreenMode: boolean;
  handsFreeVoice: boolean;
  // MOBILE / PROD
  reducedMotion: boolean;
  highContrast: boolean;
  fontSize: number;
  logRetention: number;
  // NEW CRT PARAMS
  vignetteIntensity: number;
  tintColor: { r: number, g: number, b: number };
}

export interface IntegrationConfig {
  id: string;
  provider: IntegrationProvider;
  name: string;
  endpoint?: string;
  apiKey?: string;
  status: 'ACTIVE' | 'OFFLINE' | 'SYNCING';
  baudRate?: string;
  encryption?: string;
  syncFolder?: string;
  lastMerge?: string;
}

export interface FeatureInfo {
  id: Feature;
  title: string;
  description: string;
  model: string;
}

export interface StarSystem {
  id: string;
  name: string;
  coords: [number, number];
  spectral_class: string;
  faction: string;
  planets: number;
  description: string;
  connections: string[]; // List of IDs for wormhole navigation
}

import React, { useState, useCallback, useEffect, useRef } from 'react';
import CodeEditor from './components/CodeEditor';
import ControlPanel from './components/ControlPanel';
import OutputDisplay from './components/OutputDisplay';
import StatusBoard from './components/StatusBoard';
import CameraMonitor from './components/CameraMonitor';
import MotherBrainRepo from './components/MotherBrainRepo';
import IntegrationHub from './components/IntegrationHub';
import UISettingsPanel from './components/UISettingsPanel';
import NeonParticles from './components/NeonParticles';
import GalaxyMap from './components/GalaxyMap';
import MediaCenter from './components/MediaCenter';
import FloatingWindow from './components/FloatingWindow';
import LiveVoiceChat from './components/LiveVoiceChat';
import SystemDebugger from './components/SystemDebugger';
import ErrorBoundary from './components/ErrorBoundary';
import { GD_SCRIPT_CODE, FEATURES, COSMIC_KEY_CONTEXT, MEETING_AGENTS, MOTHER_BRAIN_ASSETS, MOCK_STAR_SYSTEMS } from './constants';
import { Feature, CameraSettings, MotherBrainAsset, UISettings, MeetingMessage, SyncLogEntry, StarSystem, LogEntry } from './types';
import { generateContent, generateMeetingContent } from './services/geminiService';

const App: React.FC = () => {
  const [selectedFeature, setSelectedFeature] = useState<Feature>(Feature.REHYDRATION_LAB);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [output, setOutput] = useState<string>('');
  const [groundingUrls, setGroundingUrls] = useState<any[]>([]);
  const [meetingMessages, setMeetingMessages] = useState<MeetingMessage[]>([]);
  const [syncLogs, setSyncLogs] = useState<SyncLogEntry[]>([]);
  const [logs, setLogs] = useState<LogEntry[]>([]);
  const [selectedAsset, setSelectedAsset] = useState<MotherBrainAsset | null>(null);
  const [isGlitching, setIsGlitching] = useState(false);
  const [isMolting, setIsMolting] = useState(false);
  const [activeTab, setActiveTab] = useState<'REFS' | 'INTEGRATIONS' | 'DEBUG'>('REFS');
  const [isUISettingsOpen, setIsUISettingsOpen] = useState(false);
  const [particleTrigger, setParticleTrigger] = useState(0);
  const [discoveredAssets, setDiscoveredAssets] = useState<MotherBrainAsset[]>([]);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [mobileView, setMobileView] = useState<'NAV' | 'MAIN' | 'CONTROLS'>('MAIN');
  const [voiceStatus, setVoiceStatus] = useState<'IDLE' | 'LISTENING' | 'TALKING'>('IDLE');
  const [voiceCommandToast, setVoiceCommandToast] = useState<string | null>(null);

  const [cameraSettings, setCameraSettings] = useState<CameraSettings>({
    brightness: 120, contrast: 140, saturation: 20, grayscale: true
  });

  const [uiSettings, setUiSettings] = useState<UISettings>({
    glitchIntensity: 1.0, scanlineWeight: 0.55, flickerSpeed: 0.1, enableSway: true,
    chromaticAberration: true, theme: 'cream', moltMode: true, touchOptimization: window.innerWidth < 1024,
    hardwareProfile: 'BALANCED', audioActive: true, showSwarmTopology: false,
    layout: {
      leftColWidth: 25,
      rightColWidth: 25,
      headerHeight: 80
    },
    activeFeatures: FEATURES.map(f => f.id),
    crtWarp: 5,
    neonIntensity: 1.0,
    terminalBrightness: 1.0,
    floatingWindows: false,
    dualScreenMode: false,
    handsFreeVoice: false,
    reducedMotion: false,
    highContrast: false,
    fontSize: 11,
    logRetention: 100,
    vignetteIntensity: 0.6,
    tintColor: { r: 0.55, g: 0.49, b: 0.42 }
  });

  const addLog = useCallback((level: LogEntry['level'], module: string, message: string, data?: any) => {
    const entry: LogEntry = {
      id: `log-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`,
      level,
      module,
      message,
      timestamp: new Date().toLocaleTimeString(),
      data
    };
    setLogs(prev => [entry, ...prev].slice(0, uiSettings.logRetention));
  }, [uiSettings.logRetention]);

  useEffect(() => {
    const handleResize = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      setUiSettings(prev => ({ ...prev, touchOptimization: mobile }));
    };
    window.addEventListener('resize', handleResize);
    addLog('INFO', 'KERNEL', 'ARCHON_OMEGA Final Production Kernel initialized.');
    return () => window.removeEventListener('resize', handleResize);
  }, [addLog]);

  const triggerHandshake = () => {
    setIsGlitching(true);
    setParticleTrigger(prev => prev + 1);
    addLog('INFO', 'UI', 'Visual Handshake Sequence Start.');
    setTimeout(() => setIsGlitching(false), 300);
  };

  const handleMolt = useCallback((newTheme: UISettings['theme']) => {
    setIsMolting(true);
    addLog('INFO', 'THEME', `Theme Molt triggered: ${newTheme}.`);
    setTimeout(() => {
      setUiSettings(prev => ({ ...prev, theme: newTheme }));
      setTimeout(() => setIsMolting(false), 400);
    }, 300);
  }, [addLog]);

  const handleGenerate = useCallback(async (customPrompt?: string) => {
    if (isLoading) return;
    triggerHandshake();
    setIsLoading(true);
    setGroundingUrls([]);
    addLog('INFO', 'AI_ENGINE', `Requesting Content [Feature: ${selectedFeature}]`);

    try {
      if (selectedFeature === Feature.AI_GROUP_MEETING) {
        const msgs = await generateMeetingContent(customPrompt || "Devise Rehydration & External Sync Strategy", MEETING_AGENTS);
        setMeetingMessages(msgs);
        addLog('INFO', 'AI_ENGINE', 'Meeting Simulation complete.');
      } else {
        const { text, urls } = await generateContent(selectedFeature, selectedAsset?.code || GD_SCRIPT_CODE, customPrompt);
        setOutput(text);
        if (urls) setGroundingUrls(urls);

        if (selectedFeature === Feature.REHYDRATION_LAB) {
           const found: MotherBrainAsset = {
              id: `rehydrated-${Date.now()}`,
              name: `rehydrated_${selectedAsset?.name || 'artifact'}.gd`,
              type: 'script',
              path: `/synced/production/${selectedAsset?.name || 'artifact'}.gd`,
              code: text,
              rehydrationLevel: 100
           };
           setDiscoveredAssets(prev => [found, ...prev]);
           addLog('INFO', 'REHYDRATION', `Asset Rehydrated: ${found.name}`);

           setSyncLogs(prev => [
             { id: `log-${Date.now()}-1`, operation: 'REHYDRATED', source: selectedAsset?.path || 'EXTERNAL_BRIDGE', target: found.path, hash: 'a7f2_Ω', timestamp: new Date().toLocaleTimeString() },
             { id: `log-${Date.now()}-2`, operation: 'VERIFIED', source: found.path, target: found.path, hash: 'b881_Ω', timestamp: new Date().toLocaleTimeString() },
             ...prev
           ]);
        }
      }
    } catch (err: any) {
      addLog('ERROR', 'AI_ENGINE', `Generation Failure: ${err.message}`);
      setOutput(`ARCHON_FAULT: ${err.message}`);
    } finally {
      setIsLoading(false);
    }
  }, [selectedFeature, selectedAsset, addLog, isLoading]);

  const handleVoiceAction = useCallback((action: string, params?: any) => {
    setVoiceCommandToast(`${action.toUpperCase()}${params ? `(${JSON.stringify(params)})` : ''}`);
    addLog('INFO', 'VOICE_COMMAND', `Executed: ${action}`, params);

    setTimeout(() => setVoiceCommandToast(null), 3000);

    switch (action) {
      case 'switch_feature':
        const f = params.feature;
        const foundFeature = FEATURES.find(feat => 
          feat.id === f || 
          feat.title.toUpperCase().includes(String(f).toUpperCase()) ||
          feat.id.toUpperCase().includes(String(f).toUpperCase())
        );
        if (foundFeature) {
          setSelectedFeature(foundFeature.id);
          if (isMobile) setMobileView('MAIN');
        }
        break;
      case 'trigger_scan':
        handleGenerate();
        break;
      case 'media_control':
        window.dispatchEvent(new CustomEvent('archon-media', { detail: params }));
        break;
      case 'switch_theme':
        if (params.theme) handleMolt(params.theme as UISettings['theme']);
        break;
      case 'toggle_settings':
        setIsUISettingsOpen(prev => !prev);
        break;
    }
  }, [addLog, handleGenerate, isMobile, handleMolt]);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', uiSettings.theme);
    document.documentElement.style.setProperty('--neon-intensity', uiSettings.neonIntensity.toString());
    document.documentElement.style.setProperty('--term-brightness', uiSettings.terminalBrightness.toString());
    document.documentElement.style.setProperty('--scanline-opacity', uiSettings.scanlineWeight.toString());
    document.documentElement.style.setProperty('--vignette-intensity', uiSettings.vignetteIntensity.toString());
    document.documentElement.style.setProperty('--tint-r', uiSettings.tintColor.r.toString());
    document.documentElement.style.setProperty('--tint-g', uiSettings.tintColor.g.toString());
    document.documentElement.style.setProperty('--tint-b', uiSettings.tintColor.b.toString());

    const filter = document.getElementById('crt-warp-filter');
    if (filter) {
        const displacement = filter.querySelector('feDisplacementMap');
        if (displacement) displacement.setAttribute('scale', uiSettings.crtWarp.toString());
    }
  }, [uiSettings]);

  const combinedAssets = [...discoveredAssets, ...MOTHER_BRAIN_ASSETS];
  const activeFeaturesList = FEATURES.filter(f => uiSettings.activeFeatures.includes(f.id));

  const renderLeftCol = () => (
    <div className="flex flex-col gap-4 h-full">
        <CameraMonitor settings={cameraSettings} onUpdateSettings={(s) => {
            setCameraSettings(s);
            addLog('INFO', 'OPTICS', 'Camera calibration updated.');
        }} />
        {!uiSettings.floatingWindows && <MediaCenter />}
        <div className="flex-grow flex flex-col overflow-hidden border-2 border-neonOrange shadow-neon-orange-sm bg-taupe/5">
            <div className="flex border-b border-earth text-[8px] font-black uppercase">
                <button onClick={() => { setActiveTab('REFS'); addLog('INFO', 'UI', 'Navigated to Archeology tab.'); }} className={`flex-1 py-2 ${activeTab === 'REFS' ? 'bg-earth text-cream' : ''}`}>Archeology</button>
                <button onClick={() => { setActiveTab('INTEGRATIONS'); addLog('INFO', 'UI', 'Navigated to Integrations tab.'); }} className={`flex-1 py-2 ${activeTab === 'INTEGRATIONS' ? 'bg-earth text-cream' : ''}`}>Integrations</button>
                <button onClick={() => { setActiveTab('DEBUG'); addLog('INFO', 'UI', 'Navigated to System tab.'); }} className={`flex-1 py-2 ${activeTab === 'DEBUG' ? 'bg-earth text-cream' : ''}`}>System</button>
            </div>
            <div className="flex-grow overflow-hidden p-1">
                {activeTab === 'REFS' ? (
                <MotherBrainRepo onSelectAsset={(a) => { setSelectedAsset(a); addLog('INFO', 'STRATA', `Selected asset: ${a.name}`); }} selectedAssetId={selectedAsset?.id} isPanelActive={true} profile={uiSettings.hardwareProfile} assets={combinedAssets} />
                ) : activeTab === 'INTEGRATIONS' ? (
                <IntegrationHub />
                ) : (
                <SystemDebugger logs={logs} isActive={true} onClear={() => { setLogs([]); addLog('INFO', 'DEBUG', 'System logs purged.'); }} />
                )}
            </div>
        </div>
    </div>
  );

  return (
    <ErrorBoundary>
      <div 
        className={`h-full flex flex-col p-4 md:p-6 gap-4 bg-cream text-earth overflow-hidden ${isGlitching ? 'fusion-glitch' : ''} ${uiSettings.enableSway && !isLoading && !uiSettings.reducedMotion ? 'tv-glitch-active' : 'no-sway'}`}
        style={{
          '--header-h': `${uiSettings.layout.headerHeight}px`,
        } as React.CSSProperties}
      >
        {isMolting && <div className="molting-shred"></div>}

        {/* Global Voice Command Toast */}
        {voiceCommandToast && (
          <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[300] bg-earth text-integrityOk border-2 border-integrityOk px-6 py-2 font-black uppercase tracking-widest text-[10px] shadow-neon-orange-sm animate-bounce paper-grain">
             <span className="opacity-40 mr-2">VOICE_EXEC:</span> {voiceCommandToast}
          </div>
        )}

        <UISettingsPanel 
          settings={uiSettings} 
          onUpdate={(s) => {
            setUiSettings(s);
            addLog('INFO', 'CONFIG', 'System UI configuration updated.');
          }} 
          onThemeChange={handleMolt} 
          onClose={() => setIsUISettingsOpen(false)} 
          isActive={isUISettingsOpen} 
          allFeatures={FEATURES} 
        />

        <header className="flex shrink-0 items-center justify-between border-b-4 border-earth pb-4 px-2 relative paper-grain-subtle" style={{ height: 'var(--header-h)' }}>
          <div className="flex items-center gap-6">
            <div className="w-12 h-12 bg-earth flex items-center justify-center border-2 border-neonOrange relative shadow-neon-orange">
               <span className="text-white text-3xl font-black italic neon-text-glow-white">Ω</span>
               {!uiSettings.reducedMotion && <NeonParticles trigger={particleTrigger} color="#FFFFFF" />}

               {/* Global Voice Status Indicator */}
               {uiSettings.handsFreeVoice && (
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white flex items-center justify-center text-[8px] z-50 ${voiceStatus === 'TALKING' ? 'bg-neonOrange animate-ping' : voiceStatus === 'LISTENING' ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}>
                     {voiceStatus === 'TALKING' ? '🔊' : '🎙️'}
                  </div>
               )}
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-black uppercase tracking-tighter italic">&lt;V&gt;-9.5_ARCHON_OMEGA</h1>
              {!isMobile && <p className="text-[9px] font-black uppercase text-earth/60">COPILOT: <span className="text-integrityOk">ARCHON_ACTIVE</span> | GOVERNANCE: <span className="text-integrityOk">SOL_X</span></p>}
            </div>
          </div>
          <div className="flex gap-4">
             {uiSettings.handsFreeVoice && (
                <div className="flex items-center gap-2 px-2 md:px-4 bg-integrityOk/20 border border-integrityOk rounded-full shadow-neon-orange-sm">
                   <span className="text-[10px] font-black text-integrityOk flex items-center gap-2">
                     <span className={`w-2 h-2 rounded-full ${voiceStatus === 'IDLE' ? 'bg-taupe' : 'bg-integrityOk animate-pulse'}`}></span>
                     LIVE_BRIDGE
                   </span>
                </div>
             )}
             <button onClick={() => { setIsUISettingsOpen(true); addLog('INFO', 'UI', 'Settings panel opened.'); }} className="text-[10px] font-black uppercase underline decoration-neonOrange/40">CONFIG</button>
             {!isMobile && <StatusBoard />}
          </div>
        </header>

        <main className="flex-grow grid grid-cols-12 gap-6 overflow-hidden relative">
          {isMobile ? (
            <div className="col-span-12 flex flex-col h-full overflow-hidden">
               {mobileView === 'NAV' && <div className="h-full">{renderLeftCol()}</div>}
               {mobileView === 'MAIN' && (
                  <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden">
                    {selectedFeature === Feature.GALAXY_MAP_GEN ? (
                        <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={(t) => {
                          triggerHandshake();
                          addLog('INFO', 'NAV', `Wormhole Jump Successful: Arrived at ${t.name}.`);
                          setOutput(`ARCHON_WORMHOLE_FEED: Arrived at ${t.name}.\n\nFaction: ${t.faction}\nSpectral: ${t.spectral_class}\n\nARCHON: "External bridges re-syncing for local strata."`);
                        }} />
                    ) : (
                        <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
                    )}
                  </div>
               )}
               {mobileView === 'CONTROLS' && (
                  <div className="h-full border-2 border-neonOrange shadow-neon-orange-sm overflow-hidden">
                    <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={(f) => { setSelectedFeature(f); addLog('INFO', 'UI', `Feature selected: ${f}`); }} onGenerate={() => handleGenerate()} isLoading={isLoading} />
                  </div>
               )}

               <nav className="flex shrink-0 border-t-2 border-earth/20 mt-4 bg-cream z-50">
                  <button onClick={() => setMobileView('NAV')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'NAV' ? 'bg-earth text-cream' : ''}`}>Silo</button>
                  <button onClick={() => setMobileView('MAIN')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'MAIN' ? 'bg-earth text-cream' : ''}`}>Main</button>
                  <button onClick={() => setMobileView('CONTROLS')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'CONTROLS' ? 'bg-earth text-cream' : ''}`}>Cmd</button>
               </nav>
            </div>
          ) : (
            <>
              <div className="overflow-hidden h-full" style={{ gridColumn: `span ${Math.round(uiSettings.layout.leftColWidth / 8.33)}` }}>
                {!uiSettings.floatingWindows ? renderLeftCol() : (
                    <div className="h-full border-2 border-dashed border-neonOrange/30 flex items-center justify-center italic text-[10px] text-earth/40 uppercase">
                      Floating_Silo_Active
                    </div>
                )}
              </div>

              <div className="flex flex-col gap-4 overflow-hidden h-full" style={{ gridColumn: `span ${Math.round((100 - uiSettings.layout.leftColWidth - uiSettings.layout.rightColWidth) / 8.33)}` }}>
                <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden">
                  {selectedFeature === Feature.GALAXY_MAP_GEN ? (
                      <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={(t) => {
                        triggerHandshake();
                        addLog('INFO', 'NAV', `Wormhole Jump Successful: Arrived at ${t.name}.`);
                        setOutput(`ARCHON_WORMHOLE_FEED: Arrived at ${t.name}.\n\nFaction: ${t.faction}\nSpectral: ${t.spectral_class}\n\nARCHON: "External bridges re-syncing for local strata."`);
                      }} />
                  ) : (
                      <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />
                  )}
                </div>
              </div>

              <div className="overflow-hidden h-full border-2 border-neonOrange shadow-neon-orange-sm" style={{ gridColumn: `span ${Math.round(uiSettings.layout.rightColWidth / 8.33)}` }}>
                <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={(f) => { setSelectedFeature(f); addLog('INFO', 'UI', `Feature selected: ${f}`); }} onGenerate={() => handleGenerate()} isLoading={isLoading} />
              </div>
            </>
          )}

          {/* Voice Chat Bridge */}
          {(uiSettings.handsFreeVoice || uiSettings.dualScreenMode) && (
            <div className={`fixed bottom-4 right-4 z-[150] transition-all ${isMobile ? 'w-[calc(100%-2rem)]' : 'w-96'}`}>
               <LiveVoiceChat 
                isActive={uiSettings.handsFreeVoice} 
                handsFree={uiSettings.handsFreeVoice} 
                onAction={handleVoiceAction} 
                onStatusChange={setVoiceStatus}
               />
            </div>
          )}

          {uiSettings.floatingWindows && !isMobile && (
            <>
                <FloatingWindow title="OMNI_MEDIA" initialPos={{x: 50, y: 50}} width="320px">
                  <MediaCenter />
                </FloatingWindow>
                <FloatingWindow title="SYNC_ACTIVITY" initialPos={{x: 400, y: 150}} width="350px">
                  <div className="bg-cream/40 p-4 font-mono text-[8px] h-40 overflow-auto">
                      {syncLogs.length > 0 ? syncLogs.map(l => (
                        <div key={l.id} className="mb-1 border-b border-earth/10">{l.timestamp} - {l.operation} - {l.target}</div>
                      )) : "Awaiting sync activity..."}
                  </div>
                </FloatingWindow>
            </>
          )}
        </main>

        <style dangerouslySetInnerHTML={{ __html: `
          .neon-text-glow-white { text-shadow: 0 0 calc(10px * var(--neon-intensity)) #FFFFFF, 0 0 calc(20px * var(--neon-intensity)) #FFFFFF; }
          .font-size-custom { font-size: ${uiSettings.fontSize}px; }
        `}} />
      </div>
    </ErrorBoundary>
  );
};

export default App;

import React, { useState } from 'react';
import { UISettings, HardwareProfile, Feature, FeatureInfo } from '../types';
import { HARDWARE_TARGETS, ARCHON_MANUAL } from '../constants';

interface UISettingsPanelProps {
  settings: UISettings;
  onUpdate: (settings: UISettings) => void;
  onThemeChange: (theme: UISettings['theme']) => void;
  onClose: () => void;
  isActive: boolean;
  allFeatures: FeatureInfo[];
}

const UISettingsPanel: React.FC<UISettingsPanelProps> = ({ settings, onUpdate, onThemeChange, onClose, isActive, allFeatures }) => {
  const [activeTab, setActiveTab] = useState<'VISUAL' | 'MOBILE' | 'FEATURES' | 'MANUAL'>('VISUAL');
  const [manualSection, setManualSection] = useState(ARCHON_MANUAL.sections[0].id);

  if (!isActive) return null;

  const handleChange = (key: keyof UISettings, value: any) => {
    onUpdate({ ...settings, [key]: value });
  };

  const handleLayoutChange = (key: keyof UISettings['layout'], value: number) => {
    onUpdate({
      ...settings,
      layout: { ...settings.layout, [key]: value }
    });
  };

  const toggleFeature = (fid: Feature) => {
    const next = settings.activeFeatures.includes(fid)
      ? settings.activeFeatures.filter(id => id !== fid)
      : [...settings.activeFeatures, fid];
    handleChange('activeFeatures', next);
  };

  const Slider = ({ label, value, min, max, step = 1, unit = "", onChange }: { label: string, value: number, min: number, max: number, step?: number, unit?: string, onChange: (val: number) => void }) => (
    <div className="mb-4">
      <div className="flex justify-between items-center mb-1">
        <label className="text-[9px] text-earth font-black uppercase italic">{label}</label>
        <span className="text-[9px] text-neonOrange font-mono">{typeof value === 'number' ? value.toFixed(step < 1 ? 2 : 0) : value}{unit}</span>
      </div>
      <input
        type="range"
        min={min}
        max={max}
        step={step}
        value={value}
        onChange={(e) => onChange(parseFloat(e.target.value))}
        className="w-full h-1 bg-taupe/30 border border-taupe/50 rounded-none appearance-none cursor-pointer accent-neonOrange"
      />
    </div>
  );

  const Toggle = ({ label, active, onClick }: { label: string, active: boolean, onClick: () => void }) => (
    <button 
      onClick={onClick}
      className={`p-3 border-2 font-black text-[9px] uppercase transition-all flex items-center justify-between gap-4 ${active ? 'bg-earth text-cream border-earth' : 'bg-cream text-earth border-taupe/40'}`}
    >
      <span>{label}</span>
      <div className={`w-8 h-4 border ${active ? 'bg-neonOrange border-neonOrange' : 'bg-taupe/20 border-taupe/40'} relative`}>
        <div className={`absolute top-0.5 w-3 h-2.5 bg-white transition-all ${active ? 'right-0.5' : 'left-0.5'}`}></div>
      </div>
    </button>
  );

  const hardwareProfiles: HardwareProfile[] = ['LEGACY', 'BALANCED', 'MOBILE_STARK', 'ULTRA'];

  return (
    <div className="fixed inset-0 z-[200] flex items-center justify-center bg-black/60 backdrop-blur-md p-4 animate-in fade-in duration-300">
      <div className="bg-cream border-4 border-earth w-full max-w-2xl p-6 shadow-[15px_15px_0px_var(--accent-burgundy)] flex flex-col gap-6 relative max-h-[95vh] overflow-hidden paper-grain">
        <div className="absolute top-0 right-0 p-2 text-[6px] font-black text-earth/20 uppercase tracking-widest z-20">
          ARCHON_UI_KERNEL_CONFIG_V9.5
        </div>

