               {!uiSettings.reducedMotion && <NeonParticles trigger={particleTrigger} color="#FFFFFF" />}
               {uiSettings.handsFreeVoice && (
                  <div className={`absolute -bottom-1 -right-1 w-4 h-4 rounded-full border-2 border-white flex items-center justify-center text-[8px] z-50 ${voiceStatus === 'TALKING' ? 'bg-neonOrange animate-ping' : voiceStatus === 'LISTENING' ? 'bg-integrityOk animate-pulse' : 'bg-taupe'}`}>
                     {voiceStatus === 'TALKING' ? '🔊' : '🎙️'}
                  </div>
               )}
            </div>
            <div>
              <h1 className="text-xl md:text-2xl font-black uppercase tracking-tighter italic">&lt;V&gt;-9.5_ARCHON_OMEGA</h1>
              {!isMobile && <p className="text-[9px] font-black uppercase text-earth/60">COPILOT: <span className="text-integrityOk">ARCHON_ACTIVE</span> | GOVERNANCE: <span className="text-integrityOk">SOL_X</span></p>}
            </div>
          </div>
          <div className="flex gap-4">
             <button onClick={() => setIsUISettingsOpen(true)} className="text-[10px] font-black uppercase underline decoration-neonOrange/40">CONFIG</button>
             {!isMobile && <StatusBoard />}
          </div>
        </header>

        <main className="flex-grow grid grid-cols-12 gap-6 overflow-hidden relative">
          {isMobile ? (
            <div className="col-span-12 flex flex-col h-full overflow-hidden">
               {mobileView === 'NAV' && <div className="h-full">{renderLeftCol()}</div>}
               {mobileView === 'MAIN' && <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden"><OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} /></div>}
               {mobileView === 'CONTROLS' && <div className="h-full border-2 border-neonOrange shadow-neon-orange-sm overflow-hidden"><ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} /></div>}
               <nav className="flex shrink-0 border-t-2 border-earth/20 mt-4 bg-cream z-50">
                  <button onClick={() => setMobileView('NAV')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'NAV' ? 'bg-earth text-cream' : ''}`}>Silo</button>
                  <button onClick={() => setMobileView('MAIN')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'MAIN' ? 'bg-earth text-cream' : ''}`}>Main</button>
                  <button onClick={() => setMobileView('CONTROLS')} className={`flex-1 py-3 text-[10px] font-black uppercase ${mobileView === 'CONTROLS' ? 'bg-earth text-cream' : ''}`}>Cmd</button>
               </nav>
            </div>
          ) : (
            <>
              {uiSettings.layout.leftColWidth > 0 && (
                <div className="overflow-hidden h-full" style={{ gridColumn: `span ${Math.round(uiSettings.layout.leftColWidth / 8.33)}` }}>
                  {!uiSettings.floatingWindows ? renderLeftCol() : <div className="h-full border-2 border-dashed border-neonOrange/30 flex items-center justify-center italic text-[10px] text-earth/40 uppercase">Floating_Silo_Active</div>}
                </div>
              )}
              <div className="flex flex-col gap-4 overflow-hidden h-full" style={{ gridColumn: `span ${Math.round((100 - (uiSettings.layout.leftColWidth > 0 ? uiSettings.layout.leftColWidth : 0) - uiSettings.layout.rightColWidth) / 8.33)}` }}>
                <div className="h-full border-2 border-neonOrange shadow-neon-orange overflow-hidden">
                  {selectedFeature === Feature.GALAXY_MAP_GEN ? <GalaxyMap systems={MOCK_STAR_SYSTEMS} isLoading={isLoading} onJumpComplete={(t) => setOutput(`Wormhole Jump to ${t.name} complete.`)} /> : <OutputDisplay output={output} isLoading={isLoading} featureTitle={selectedFeature} featureId={selectedFeature} meetingMessages={meetingMessages} syncLogs={syncLogs} groundingUrls={groundingUrls} />}
                </div>
              </div>
              {uiSettings.layout.rightColWidth > 0 && (
                <div className="overflow-hidden h-full border-2 border-neonOrange shadow-neon-orange-sm" style={{ gridColumn: `span ${Math.round(uiSettings.layout.rightColWidth / 8.33)}` }}>
                  <ControlPanel features={activeFeaturesList} selectedFeature={selectedFeature} onSelectFeature={setSelectedFeature} onGenerate={() => handleGenerate()} isLoading={isLoading} />
                </div>
              )}
            </>
          )}

          {uiSettings.handsFreeVoice && (
            <div className={`fixed bottom-4 right-4 z-[150] transition-all ${isMobile ? 'w-[calc(100%-2rem)]' : 'w-96'}`}>
               <LiveVoiceChat isActive={uiSettings.handsFreeVoice} handsFree={uiSettings.handsFreeVoice} onAction={handleVoiceAction} onStatusChange={setVoiceStatus} />
            </div>
          )}

          {uiSettings.floatingWindows && !isMobile && (
            <>
              <FloatingWindow title="OMNI_MEDIA" initialPos={{x: 50, y: 50}} width="320px"><MediaCenter /></FloatingWindow>
              <FloatingWindow title="SYNC_ACTIVITY" initialPos={{x: 400, y: 150}} width="350px"><div className="bg-cream/40 p-4 font-mono text-[8px] h-40 overflow-auto">{syncLogs.length > 0 ? syncLogs.map(l => <div key={l.id}>{l.timestamp} - {l.operation}</div>) : "Awaiting sync..."}</div></FloatingWindow>
            </>
          )}
        </main>
      </div>
    </ErrorBoundary>
  );
};

export default App;
